var RUTUBE_DESC = /*RTDESC*/{"93004055":"Картина воссоздает 1918-1919 годы, когда Республика Советов с оружием в руках отстаивала завоевание Великого Октября. В центре внимания - судьба крестьянского сына Кости, чье мировоззрение, характер, чья личность складывалась в суровое, но героическое время великих свершений.","93010822":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","93024605":"Первые послевоенные годы. В таежных лесах Восточной Сибири проводятся геодезические исследования. В лагере экспедиции готовятся к возвращению на базу. Радиограмма из штаба о том, что на гольце Ямбуй бесследно исчез наблюдатель, заставила изменить планы.","93029113":"Сергей и Тамара знакомятся в поезде. Она рассказывает ему, что едет к своим родителям, у которых сейчас ее сын, а с мужем развелась и больше к нему не вернется. Однако говорить родителям об этом она не хочет, чтобы их лишний раз не расстраивать. И Сергей решает представиться ее мужем… Однако эта новая роль в итоге окажется очень для него сложна.","93032134":"Новая серия Простоквашино — Едем в город, 1 часть на нашем канале.","93032990":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","93044654":"Моряк Андрей, отправляясь в отпуск, становится свидетелем мошенничества молодых людей, вымогающих деньги на вокзалах. Его привлекает героиня «аферы» - Светлана. Андрей проникается сочувствием к девушке, стремится помочь ей вырваться из порочного круга… Но выясняется, что это всего лишь специально срежиссированное действо, придуманное…","93046159":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","93046537":"Сказочная история, произошедшая в 21 веке. Экипаж космического корабля обнаруживает в заброшенной инопланетной станции данные о доставленном на Землю много тысяч лет назад лиловом шаре, в котором находится вирус вражды.","93059435":"Кинокомедия Андрея Фролова \"Песня табунщика\"","93064472":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93069189":"Современная драма о молодом человеке, который случайно совершив преступление, не находит в себе сил понести за это ответственность. \nДействие фильма происходит в наши дни. Молодой военнослужащий Виктор случайно убивает человека и пускается в бега. Добравшись до Владивостока, он начинает искать старого друга, который может нелегально вывезти его из…","93070564":"«Крылья» - советский художественный фильм режиссёра Ларисы Шепитько. Фильм повествует о послевоенной жизни бывшей боевой лётчицы, а ныне директора училища Надежды Петрухиной. Давно окончилась война, но для героини фильма только те годы и были наполнены подлинным смыслом. Она глубоко переживает разлад с действительностью, отсутствие контакта с дочерью. Ей…","93073263":"Спасаясь от одиночества и скуки, пенсионерка Майя Дмитриевна снимается в массовке, организовывает женский клуб, встречается с подругами и каждый день начинает новую жизнь…","93084083":"Драма Сергея Соловьева \"Егор Булычев и другие\"","93084293":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","93088220":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","93088687":"Об участии юных друзей Пети Бачея и Гаврика Черноиваненко в работе одесского большевистского подполья в предреволюционные годы (1910-1912).","93094281":"Новая серия Простоквашино — Экология на нашем канале.","93101677":"Закончилась у солдата служба, спешит солдат домой. Но по пути в родные места довелось ему сделать еще одно доброе дело: помочь мальчику Иванушке вызволить из плена матушку свою – Марью–Искусницу.","93102345":"У рабочего леспромхоза – жена Надя, трое детей и голубятня. Впервые в жизни он по путевке едет на юг. Там наивный деревенский простак встречает роковую женщину Раису Захаровну и… возвращается с отдыха не к себе в деревню, а в дом новой знакомой. Начинается для него новая жизнь, в которой много непонятного и интересного, но нет дома, где остались Надя,…","93113721":"В стародавние времена жил на Руси пахарь, звали его Финист. Был он могучий богатырь, защищал отчизну от чужеземных захватчиков. Но однажды хитроумный прихвостень заморского царя заманил его в подземелье и заколдовал! Превратился богатырь в страшное чудище. А расколдовать его может только красна девица… Если она полюбит его в таком облике, он снова станет…","93115136":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","93115269":"Страховой агент Юрий Деточкин, кристально чистый и наивный человек, выходит на тропу войны со взяточниками и спекулянтами. Движимый чувством справедливости, действует он весьма своеобразно: угоняет машины у людей, наживших их нечестным путем, продает их, а деньги целиком переводит в детские дома. В прокуратуре дела об этих угонах ведет следователь…","93142075":"Хореографический ансамбль «Девичья весна» отправляется на гастроли по Волжским городам. Влюблённый в солистку ансамбля Галину, оптик Володя не смог попасть в число пассажиров теплохода, на котором отплывали артисты: по случаю спецрейса билеты на теплоход не продавались.","93145979":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","93148469":"Борьба с космическими пиратами, захватывающее путешествие во времени, знакомство с девочкой из будущего Алисой Селезневой — вот к чему привел обычный поход за кефиром мальчика Колю из 6-го класса.","93154635":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93156420":"Любовь, которую невозможно ни принять, ни забыть. История, от которой не остаётся равнодушных — ни тогда, ни сейчас.","93163543":"По одноименной комедии Н.Гоголя. Городничий небольшого уездного города получает из Петербурга секретное послание с предупреждением о предполагаемом прибытии инкогнито столичного ревизора. Местное чиновничество во главе с градоначальником крайне взволновано. А тем временем в городе остановился некто Хлестаков, проигравшийся и протратившийся мелкий…","93164267":"По pоману А.Чаковского. В основу двухсерийного фильма положены важные исторические события: Потсдамская конференция глав трех держав (1945 г.) и Хельсинское совещание европейских стран по безопасности и сотрудничеству в Европе (1975 г.). Главные герои фильма - советский журналист Михаил Воронов и американский журналист Чарльз Брайт - в 1945 году работали…","93166737":"Герой фильма - инженер-конструктор сельскохозяйственной техники. Однажды он получает телеграмму о том, что придуманный им трактор не работает. Инженер отправляется на выручку колхозникам. И далеко не по служебным мотивам его деревенская командировка неожиданно затягивается...","93168393":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","93177489":"В первые дни второй мировой войны молодая женщина с тремя детьми эвакуируется из прифронтовой зоны на Урал. Через некоторое время она получает похоронку на мужа. Но с нею маленькие сыновья. Старший сын Коля становится надежным помощником матери.","93179389":"В аэроклубе Зина познакомилась с кинооператором воздушных съемок Сергеем Алейкиным, очень серьезно занялась парашютным спортом и через некоторое время на международных соревнованиях стала одной из претенденток на золотую медаль.","93186211":"«Похождения зубного врача» - советская кинокомедия режиссёра Элема Климова. Этот фильм вышел лишь в 1987 году, поскольку в 1967 году его не пропустила цензура, которая усмотрела в фильме пародию на советскую действительность. \nЭто веселый и добрый фильм о молодом зубном враче Сергее Чеснокове (Андрей Мягков), который, попав по распределению в небольшой…","93199312":"Молодые супруги отправляются на теплоходе в свадебное путешествие. В пути возникает пожар - и на глазах у молодой жены на Матвея падает горящая балка. Проходит время, Наташа выходит замуж за Степана, спасшего ее в ту трагическую ночь. Но однажды, они случайно узнают о том, что Матвей жив. Степан принимает решение разыскать его и покидает Москву...","93202864":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","93203017":"Драма Валентина Невзорова \"Семья Ульяновых\"","93207141":"1960 год. Советские ученые осуществили пробный запуск космического корабля «Восток». Полет окончился неудачей. Одна из ступеней ракеты не отделилась вместе со спусковой капсулой. Чтобы разобраться в причинах аварии, необходимо было срочно найти корабль.","93210081":"Девушка Лида влюбляется в красивого парня, спортсмена Сергея, но он женится на другой. А потом произошла трагедия, и Сергей оказывается прикованным к постели из-за тяжелой травмы позвоночника. Жена, не выдержав испытания, бросает его, и жизнь для молодого человека кажется законченной. Но, узнав о его беде, к Сергею приезжает Лида. Поначалу он относится к…","93210302":"История жизни и борьбы разведчика, Героя Советского Союза Льва Маневича, умершего через 5 дней после освобождения из концлагеря 9 мая 1945 года.","93215456":"Музыкальная комедия. Профессор Никитина работает над проблемой использования солнечной энергии. Кинорежиссер Громов, задумав снять о ней фильм, поручает главную роль актрисе театра оперетты Шатровой, поразительно похожей на Никитину. Однако обстоятельства складываются так, что женщины действительно вынуждены тайно для всех подменить друг друга. После…","93216017":"Музыкальная комедия Франчиска Мунтяну \"Песни моря\".","93217919":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","93219075":"Когда в детском саду объявили карантин, оказалось, что пятилетнюю Машу не у кого оставить, все заняты неотложными делами. Даже прабабушка и прадедушка тоже работают.","93232361":"Драма Сергея Колосова \"Солдатское сердце\"","93235792":"О первых годах революционной деятельности большевика М.В. Фрунзе в городе Иваново-Вознесенске.","93238957":"Дальний Восток, 1921 год. Остатки белой армии с помощью Японии совершают переворот. Создается буферная республика под руководством Блюхера и Постышева. Большевики уходят в подполье.","93239335":"Это веселый музыкальный фильм о цирке и о талантливой девушке, которая мечтает стать артисткой. И хотя на ее пути будет немало препятствий и забавных недоразумений, неунывающая героиня все-таки сделает свой фантастический номер - \"Полет к звездам\".","93246023":"Фильм о смелых мальчишках — таежниках, которые, несмотря на препятствия, разыскивают давно заброшенный медный рудник, вступая в схватку с незаконным претендентом на него — охотником Аникиным.","93252136":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","93254047":"На даче, куда съезжается группа людей, чтобы отметить «девятый день» со дня смерти директора швейной фабрики, ближе к вечеру траурное застолье становится более раскованным - и выясняется, что покойный не просто умер, а был убит. И теперь собравшиеся должны выяснить две вещи: кто убил и куда делся чемодан с крупной суммой денег?","93255184":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","93255668":"Новобранец Алексей Кошкин, пришедший служить на границу, получил в напарники... щенка. Назвал пса Алый, и началась для них настоящая военная служба, во время которой Алый спас жизнь своего хозяина…","93262698":"Из деревенского музея украли самые ценные экспонаты, к великому сожалению его директора и реставратора, художника Бережкова, приехавшего вместе с женой из города. О преступнике известно, что это мужчина высокого роста и с большим размером обуви.","93270064":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","93286374":"По пьесе А.Володина. На место начальника некоего учреждения Куропеева, ловкого приспособленца, получившего повышение, назначается Лямин, умный интеллигент с мягким характером. Подчиненные беззастенчиво пользуются его добротой. Однако под влиянием обстоятельств Лямин постепенно меняется. Тема гражданской ответственности руководителя раскрывается в жанре…","93292974":"Фильм снят по мотивам произведений Ф. М. Достоевского «Неточка Незванова» и «Белые ночи». Крепостной Егор Ефимов, талантливый скрипач, мечтает о настоящем искусстве. Отпущенный на волю помещиком, он отправляется в столицу. Но холодный, чиновный Петербург быстро разрушает иллюзии.","93293423":"Виктор Середа, школьный авторитет во всем, что касается точных наук, рассказывает о проекте полета к созвездию Кассиопеи на космическом корабле «Заря». Собственно, ничего бы не произошло, если бы вдруг не появилась некая загадочная личность, представившаяся как ИОО, что означает «исполняющий особые обязанности». Из детей не старше 14 лет набирается…","93298188":"Россия первой половины XIX века. Известный актёр Щепин приезжает в театр князя Скалинского для участия в постановке пьесы \"Сорока-воровка\" и знакомится с талантливой крепостной актрисой Анетой. Девушка рассказывает ему о своей нелегкой судьбе, и Щепин решает во что бы то ни стало помочь крепостной.","93298200":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","93303615":"Новая серия Простоквашино — Шоколадное безумие на нашем канале.","93304406":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","93307301":"«В зоне особого внимания» - остросюжетный фильм режиссёра Андрея Малюкова 1977 года.","93308843":"Окончилась гражданская война. Демобилизованный Федор Сухов держит путь домой через пески Туркестана и встречает отряд красных бойцов. Они преследуют банду Абдулы и девять стройных женщин - его гарем, который озверевший бандит намерен уничтожить. Много смекалки, ловкости, отчаянной храбрости потребуется Сухову, чтобы победить банду. В остросюжетной ленте…","93313721":"Герой фильма Саша переживает сложный период своей жизни: его мать ушла из семьи, а отец скрыл правду от сына.","93318658":"Каждый месяц Печкин становится лучшим почтальоном, но ему никак не удается в декабре побить результат Деда Мороза. Как за одну ночь он успевает сделать так много доставок? Печкин уже который год пытается поймать Деда Мороза, чтобы узнать его секрет. В этом году он не изменяет своей традиции и решает расставить ловушки в доме простоквашинцев.","93325094":"События фильма происходят в летной школе гражданской авиации. Командир отряда учлетов Сергей Беляев в поисках романтики нарушает дисциплину, бравирует, пренебрегает опасностью. В результате он разбивает самолет. Начальник школы Рогачев отстраняет Беляева от работы. Ученица летной школы Галя Быстрова, которой нравится Беляев, стремится ему подражать - за…","93326770":"Следователь Муромцев, расследуя должностное преступление участкового милиционера, выходит на дельцов теневой экономики. Параллельно с основным действием развивается средневековый сюжет с врачом-алхимиком, портрет которого висит в комнате одного из героев современной истории.","93330095":"Фильм-балет киностудии \"Мосфильм\" по знаменитой постановке Юрия Григоровича на музыку Арама Хачатуряна. Партии исполняют величайшие танцоры современности - Владимир Васильев и Марис Лиепа. Балет А.Хачатуряна, повествующий о восстании гладиаторов и рабов под предводительством фракийца Спартака и разгроме его войсками римского полководца Красса, основан на…","93337776":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","93342351":"Военная драма Александра Столпера \"Возмездие\" 1-я серия","93369769":"Новая серия Простоквашино — Переводчик на нашем канале.","93370345":"Музыкальный фильм по мотивам одноименной комедии Уильяма Шекспира. Жизнерадостная история о том, как две пары влюбленных, преодолев множество препятствий, находят путь к счастью. Действие происходит в Италии во времена эпохи Возрождения. Молодой знатный флорентиец страстно влюблен в дочь губернатора - чистую, юную Геро, но постоянные интриги придворных…","93376928":"Королева Януария решила выдать обеих дочерей замуж. Но Августа слишком зла, а Алели, как считают все придворные, глупа, потому что говорит то, что думает. И тогда волшебник Альманзор приходит им на помощь. Он предлагает барышням два колечка: обыкновенное золотое и волшебное оловянное, у которого есть двойничок. Алели выбирает второе - и с этих пор…","93379458":"Лето 1943 года. На Курской дуге сосредоточены сотни танков, тысячи орудий, более миллиона солдат с обеих сторон. Германское командование запускает операцию «Цитадель» — последнюю попытку переломить ход войны на Восточном фронте. Советские войска готовы встретить удар.","93385100":"Чтобы спасти будущих утят, первоклассники Миша и Катя целый месяц не отходили от яиц, следя за температурой в самодельном инкубаторе. И, наконец, настал тот день, когда девять птенцов увидели свет…","93401758":"Драма режиссёра Игоря Таланкина  по мотивам одноименной знаменитой повести Л.Н.Толстого. Фильм погружает нас в бурный мир страстей, захлестнувший незаурядного и сильного человека - князя Степана Касатского. В картине раскрывается история жизни светского красавца, поклонника царя, командира лейб-эскадрона кирасирского полка, ушедшего в монастырское…","93410994":"Злой колдун-магрибинец взывает к звездам, чтобы те поведали ему имя человека, что найдет волшебную лампу, способную творить чудеса. Звезды ответили: «Это Аладдин». В Багдаде живет дочь султана, красавица Будур. Всякий, кто посмеет взглянуть на нее, будет казнен.\nНо своевольная и капризная принцесса заставляет Аладдина взглянуть на нее. Юноша как увидел…","93421662":"Веселые дачные приключения восьмилетних друзей — Миши и Коли, а также их лохматого приятеля — верного и терпеливого Дружка.","93422526":"Надя раньше Володи окончила школу и уехала в Ленинград учиться в медицинском институте, где безоглядно полюбила, женатого, намного старше себя мужчину, - и вернулась домой. А у ее родителей свои проблемы - они устали идти навстречу друг другу. Узнав, что Надя вернулась, Володя пришел к ним в дом и попытался сделать всех троих счастливыми.","93426009":"Золотой фонд советского кинематографа. Фильм, сделавший знаменитым режиссера Ивана Пырьева. Незатейливая история демобилизованного танкиста-дальневосточника Клима, вернувшегося в родной украинский колхоз, где живет его любимая Марьяна — уже знатная трактористка района. У нее много поклонников,  простодушный Клим попадает в сложную ситуацию...","93428538":"Новая серия Простоквашино — Хобби на нашем канале.","93430288":"Этого города нет на карте, он значится только в строке путевого листа. Именно туда отправляется Егор Матвеев, сын Петра Матвеева. Он хочет жить, может любить, а главное хочет узнать себя.","93439099":"Фильм-спектакль по одноименной комедии А. Н. Островского. Хозяин постоялого двора Бессудный и его жена Евгения - злые и алчные люди. А их племянница, скромная и порядочная Аннушка, любит помещика Миловидова. Однако завистница Евгения всячески пытается помешать ее личному счастью...","93446081":"Двухсерийная экранизация одноимённой повести Л. Н. Толстого.","93455007":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93458133":"По книге В. Киселева «Девочка и птицелет». У героини фильма — семиклассницы Оли — поистине счастливое детство: у нее замечательные родители, друзья, с которыми ей интересно не только в школе. А еще у нее есть дар, который выделяет ее среди ровесников, — она пишет стихи, поражающие взрослых своей недетской мудростью...","93461216":"Двенадцатилетний Женька Грачев бежит из пионерлагеря, чтобы встретиться со своим братом, служащим в армии. В дороге он знакомится с трактористом Мякишевым, которому во что бы то ни стало срочно нужно раздобыть... фрак.","93462410":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","93467661":"Оригинальный подарок ко дню рождения решил преподнести заядлому рыбаку Карпу Трофимовичу его племянник — подцепив дяде на крючок огромную щуку.","93476075":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93481627":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","93517513":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93524228":"Галя, потерявшая во время войны родителей, воспитывалась в детском доме, а когда реабилитировали ее дедушку, они стали жить вдвоем. Однажды в квартире поломался телефон, и Галя в поисках мастера обратилась в службу быта. Так в их квартире появился Алексей.","93534698":"Это история очень красивой и очень милой женщины, не отягощенной моральными нормами. Первый выбор в ее жизни - брак по расчету - перечеркнул жизнь тех, кто искренне любил Анну, и одновременно ввел красавицу в блестящий мир столичного общества.","93535606":"Пионерский лагерь на берегу Черного моря объединил детей из разных стран мира. Но случилась беда: заболела маленькая японка Инеко. После атомной бомбардировки Хиросимы она страдает лучевой болезнью, и дети пытаются ее спасти. Врач ей сказал, что она обязательно выздоровеет, если сложит из бумаги 1000 журавликов.","93540168":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","93540191":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93543612":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93548190":"Картина о стpоительстве Каховской ГЭС, о перекрытии Днепра, о рождении Каховского моря. И, конечно, о человеческих судьбах, вовлеченных в этот гигантский переворот жизни края. 1956-57 годы. В приднепровское село, которое вот-вот будет затоплено, по зову председателя колхоза съезжаются люди, родившиеся здесь, чтобы навсегда проститься с малой родиной.…","93561827":"1944 год. На одном из участков фронта советское командование готовит крупное наступление. Войска должны пройти через лесной массив, охраняемый фашистами. Для выяснений целей вражеских формирований в этот район направляется группа советских разведчиков, которую возглавляет капитан Надежда Мороз...","93561955":"Новая серия Простоквашино — Музыкальная уборка на нашем канале.","93563617":"В ПТУ приходит условно осужденный подросток Слава Горохов. Чуткий и тактичный мастер Ершов не поддается на уговоры коллектива, который сразу же «сломал зуб» об инфантильного лоботряса, а спокойно прокладывает стежки-дорожки к душе парня.","93565325":"Человек, подаривший человечеству мечту о звёздах, — но при жизни почти никем не услышанный. История о том, как одна идея может изменить мир.","93569832":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","93587351":"1941 год. Волею судьбы простой сибирский парень оказался под Москвой в числе бойцов-защитников столицы, и в подмосковном селе познакомился с красавицей Варварой. Но вскоре начались затяжные страшные бои за Москву…","93588385":"Бессмертный роман Михаила Шолохова, отмеченный Нобелевской премией и вошедший в число наиболее ярких произведений мировой литературы, рассказывает о трагической ситуации, сложившейся в России в начале ХХ века, о сломанных Первой мировой войной и революцией судьбах людей, о крушении устоев и идеалов донского казачества, о личной трагедии главного героя -…","93589929":"Во время похода по местам боевой славы, школьники размышляют, как бы они повели себя, оказавшись на месте солдат Второй мировой войны.","93590359":"Славянский юноша Кукша, попавший в плен к викингам, за мужество и отвагу получает имя Эйнар Счастливый. Начинается новый период в его жизни, полный приключений и обещаемого викингами счастья. Но единственное его желание - вернуться домой…","93595301":"Исключенные из Петербургского университета студенты Александр Михайлов и Евгений Светлов и молодая революционерка Софья проходят непростой путь революционеров-подпольщиков. Действие фильма происходит в России во время подготовки и проведения первой русской революции - с 1896 по 1906г.","93607815":"«Автомобиль, скрипка и собака Клякса» -  широкоформатный фильм режиссёра Ролана Быкова. В Таллине, в большом дворе, окруженном старыми обшарпанными двухэтажными домами, живут герои этого фильма. Два школьных товарища влюблены в самую красивую девочку двора. Один из них, Давид, учится играть на скрипке, а другой - Олег - мастер на все руки - возится с…","93631812":"Боевик Александра Аравина \"Решение об ликвидации\"","93634147":"Новая серия Простоквашино — Интересная профессия на нашем канале.","93652290":"1911 год. В.И.Ленин оказывается под Парижем, где организует партийную школу для большевиков. Цепью исторических параллелей и ассоциаций это время переплетено с событиями Парижской коммуны, Октябрьской революцией и политической борьбой послереволюционных лет. Слушатели школы, как бы прорвавшись сквозь десятилетия, вступают в спор о путях революции с…","93665474":"Фильм рассказывает о детстве мальчика из далекого алтайского села, о его сестре и матери, об их трудной жизни в лихолетье Великой Отечественной войны.","93666707":"Первый в мировом кинематографе полнометражный фильм, созданный средствами объёмной мультипликации!","93676426":"«Цареубийца» - художественный фильм режиссёра Карена Шахназарова, снятый в 1991 году. Психологическая драма с элементами мистики. История о враче-психиатре Смирнове, приехавшем заменить уходящего на пенсию главврача местной психиатрической клиники Александра Егоровича. В его руках оказался один из давних пациентов клиники - бывший уголовник Тимофеев…","93683191":"Фильм Карена Шахнозарова \"Исчезнувшая империя\"","93683327":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","93685264":"В крупный промышленный город в составе труппы московского театра приезжает на гастроли известный актер Александр Васнецов. Это город его детства, здесь он вырос, здесь живет его племянник Алексей Юрьев - учитель литературы, буквально боготворящий дядю. Однако встреча двух родных, любящих друг друга людей приносит им только разочарование.","93689286":"Художественный трёхсерийный фильм по одноименному поэтико-драматическому циклу А. С. Пушкина. Исследование души, охваченной страстью, - вот что объединяет «Mаленькие трагедии» А. С. Пушкина и делает интересной каждую новую встречу с ними. В первую серию включены «Сцена из Фауста», «Египетские ночи» и «Моцарт и Сальери». Во второй серии - «Скупой рыцарь»,…","93689903":"Фильм о раннем мужании ребят, сверстников героической гражданской войны…","93691061":"1918 год. Из Петрограда в Сибирь отправляется первая в СССР экспедиция, разыскивающая золотые месторождения. Сначала в ее составе всего два человека, красный комиссар и профессор. Вскоре у них появляются спутники из местных жителей. Кто-то действительно хочет помочь, а кое-кто просто желает за чужой счет поживиться... Ради наживы злоумышленники не…","93696215":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93697547":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","93698407":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","93699578":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","93700284":"«Попрыгунья» дебютный фильм Самсона Самсонова по одноимённому рассказу Антона Павловича Чехова.","93712267":"🏡 В этот раз в Простоквашино — ещё больше веселья!","93727112":"Молодые ленинградцы, вчерашние школьники, вступают во взрослую жизнь. Соня влюблена в Стёпу, но он любит Таню, а Таня отдаёт предпочтение Феде. Отвергнутый Стёпа уезжает в далёкий сибирский город и начинает работать на заводе, обучаясь в вечернем институте.","93729958":"Бывший десантник Виктор Кольцов поступил на работу в милицию. Однажды, возвращаясь с дежурства, он заметил в подворотне подозрительного человека и узнал в нем особо опасного преступника, объявленного в розыск. Начав преследование, доблестный милиционер получает тяжелое ранение, но сдаваться не собирается...","93736203":"Евгений вернулся из армии, а его друг Костя Сила - из исправительно-трудовой колонии. Встретившись, герои решили уехать из города: одного не дождалась любимая девушка, другой не хочет видеть сочувствующих взглядов прежних знакомых. Но встреча с майором милиции - талантливым педагогом - изменила их намерения. Все лето герои посвятили тому, чтобы вырвать…","93737195":"Музыкальная комедия о баскетбольной команде «Студент», которую возглавляет тренер Самсон Грозняк. Команда полна амбиций, но ей не хватает хорошего центрового. Юрий Кулич-Куликовский — обычный чабан, имеет блестящие природные данные для баскетбола, но спорт его совсем не интересует. Он бы никогда и не попал в команду, если бы не влюбился в певицу Нину…","93737445":"Историко-революционный Фильм о вооруженном восстании русских солдат, офицеров и финских красногвардейцев в царской крепости \"Свеаборг\" в 1906 году.","93748249":"Послевоенная драма Александра Прошкина \"Холодное лето пятьдесят третьего...\"","93750857":"Что скрывается за вечными льдами Крайнего Севера? Русские землепроходцы отправляются на поиски легендарной Земли Санникова — и то, что они находят, меняет всё.","93756888":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","93773332":"Комедия Юлия Райзмана \"Поезд идет на Восток\"","93773871":"В одной семье растут два совершенно разных сына. Младший, Фрол Калиткин, примерный восьмиклассник, победитель олимпиад, первый ученик. А старший, Андрюша, — лоботряс, бездельник и пижон. За воспитание брата берется «правильный» Фрол.","93775207":"В небольшом южном городе живет скромный, добрый матрос Сергей Чайкин. Друзьям нравятся его веселые и задушевные песни. Сергей влюблен в спортсменку Лену, к которой неравнодушен также директор Дворца моряков Вадим. Лена и Вадим уезжают в Москву на Всемирный фестиваль молодежи и студентов, следом за ними вылетает в Москву и Сергей…","93776641":"Фильм режиссёра Сергея Юткевича по бессмертной трагедии В. Шекспира о вечном конфликте человеческих чувств — чистой и кроткой любви, безумной страсти и ревности, коварстве и подлости.В тайне от отца, венецианского купца Брабанцио, Дездемона венчается с генералом венецианской республики мавром Отелло. Мичман Яго слепо ненавидит Отелло и поэтому стремится…","93784148":"По pоману А.Чаковского. В основу двухсерийного фильма положены важные исторические события: Потсдамская конференция глав трех держав (1945 г.) и Хельсинское совещание европейских стран по безопасности и сотрудничеству в Европе (1975 г.). Главные герои фильма - советский журналист Михаил Воронов и американский журналист Чарльз Брайт - в 1945 году работали…","93786068":"Приключенческий фильм режиссёра Андрея Тутышкина.  В основе сюжета недоразумения молодой влюбленной пары: Ирина и  Николай решают поехать на  машине к  Черному морю и  по дороге отпраздновать свадьбу. Их  преследует машина преподавателя Хохлова, который давно любит Ирину. Вскоре к  ним присоединяется энергичная девушка. Эту  четверку ожидает масса…","93788983":"Погрузитесь в мир великого русского балета с легендарной постановкой Юрия Григоровича — «Иван Грозный»! Звуки мощной музыки Сергея Прокофьева и захватывающая хореография Большого театра СССР перенесут вас в драматическую эпоху царствования грозного царя. Это не просто балет — это история, ожившая в танце и музыке, классика советского искусства, которая…","93794065":"Долгие годы соседствовали два короля: Федот и Амфибрахий. Когда последний однажды бесследно исчез, его королеве стало тяжело одной управлять делами, государство пришло в упадок, а дочь Алена совсем отбилась от рук. Тогда-то и решила мать выдать ее замуж.","93797875":"По мотивам одноименной повести Бориса Алмазова. О том, как серьезное увлечение конным спортом помогло двоечнику Игорю Пономареву стать одним из лучших учеников класса.","93806619":"Талантливая актриса провинциального театра Негина должна покинуть сцену, так как чистота ее поведения несовместима с театральными нравами. Она любит студента Мелузова, и оба мечтают о честной, трудовой жизни. Суровая действительность разрушает ее планы.","93807899":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","93807945":"Было у купца три дочери. Отправляясь в заморское странствие, пообещал он им привезти подарки, какие они пожелают. Две старшие попросили себе тканей и красивых безделушек. И лишь меньшая, любимая Настенька, заказала отцу чудо диковинное, невиданное - аленький цветочек, который видела она во сне.","93816109":"Ему 17 лет, он только что провалил экзамены и стал курьером. А потом всё пошло не по плану — к счастью.","93818374":"Документальный фильм-опpос жителей Евpопы о том, помнят ли они Вторую миpовую войну, и что знает о ней молодежь.","93822932":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","93825382":"Комедийный фильм Андрея Фролова \"Первая перчатка\"","93828435":"Десятилетний яхтсмен Миша Ерохин приехал к тетке в приморский городок, снарядил лодку, подобрал экипаж и вскоре был готов к экспедиции. Но местные ребята, которых Миша обошел своим вниманием, решили сорвать путешествие романтиков…","93846201":"Кин-дза-дза - это название далекой планеты, на которую попадают двое землян. Фильм рассказывает об их невероятных приключениях, знакомстве с обычаями аборигенов, часто пародирующих обычаи землян, и о счастливом возвращении на Землю. Сюжет фильма позволяет авторам размышлять о противостоянии добра и зла, о власти денег и жестокости, о судьбе человеческой…","93848677":"У талантливого педагога и переводчика Бузыкина нерешительный характер. Он не может уйти от супруги к женщине, с которой давно тайно встречается, не может отказать эксплуатирующей его талант сокурснице, а когда, наконец, решается на смелый шаг – терпит фиаско, так как по природе он мягок и податлив, как воск.","93849084":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","93861742":"Фильм-сказка по мотивам русской народной сказки о Снегурочке. Полюбился ей деревенский гончар - и захотела она стать обыкновенной девушкой и выйти за него замуж. Но счастью влюбленных мешает коварный обман князя…","93865633":"Комедия Марка Захарова \"Тот самый Мюнхгаузен\" 1 серия.","93865999":"Дерамо, король Серендиппа, крайне озабочен: ему уже за тридцать, но у него нет ни достойной королевы, ни наследника трона. Кроме того, он не знает, как отличить искреннюю любовь от придворной лести. Волшебник берется поставить опыт, который поможет осуществить заветное желание короля.","93866432":"Музыкант одного из московских ресторанов Варакин прилетает в Сан-Франциско, чтобы похитить свою дочь. Маленькую Анюту тайно увезла с собой его бывшая жена Елена, выйдя замуж за богатого американца. Девочка сразу признает в Варакине родного отца, тянется к нему и готова уехать с ним на далекую родину. Анюта убегает с отцом, и возможно, их план возвращения…","93872852":"О последнем дне свободы депутата Моссовета и директора главка.","93873070":"Пришло время – волшебник женился, остепенился, занялся хозяйством. Но однажды, встретив в лесу медведя, все-таки не вытерпел: взял и превратил его в прекрасного юношу, поставив условие, что тот снова станет медведем, если его поцелует принцесса.","93882829":"История молодой вдовы Александры Потаповой, которая волею судеб стала председателем колхоза. Исполнительница главной роли Нонна Мордюкова рассказывала, что в образе своей героини она стремилась передать впечатления детства и юности, когда ей приходилось видеть многих женщин с похожей судьбой.","93900438":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93900534":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","93902345":"По мотивам pассказов С.Антонова. С фронта возвращается инвалидом школьный учитель Николай Егоров, который узнает, что его жена умерла, оставив маленькую дочь Надю. Он находит в себе силы жить дальше - ради дочери и ради родной деревни, которую нужно возрождать. Односельчане избирают Николая председателем. Он принимается яростно поднимать из пепелища…","93906393":"Взломан сейф, убит бухгалтер. Подозрение падает на нескольких человек. Среди них неуловимый вор-рецидивист Огонек, вернувшийся в родной город матросом иностранного судна. Но настигнув его, старый мудрый комиссар милиции понимает, что Огонька привели в город желание порвать с прошлым и тоска по Родине. Кто же тогда преступник?","93914030":"Кинокомедия Александра Столбова \"Обыкновенный человек\"","93919526":"Фильм-хроника состоит из двух частей - «Бессонница» и «Уход». Зритель встречается с великим русским писателем в последние годы его жизни (1908-1910), однако воспоминания Льва Толстого возвращают нас и к событиям его молодости, и к поре решительного и страстного перелома в его взглядах. Финал - трагический уход из Ясной Поляны и смерть, ставшая началом…","93920502":"Председатель колхоза Родион Михайлович Шишкин - человек со сложным характером. Он ругается с высоким начальством, которое не дает ему работать, и не терпит несправедливости. Но однажды очередной поднятый им скандал закончился для него... повышением!","93934846":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","93942491":"Полюбив друг друга еще в школе, они поженились - и теперь в счастливой и благополучной семье растет маленький сын. Однажды герой становится свидетелем грабежа. Среди хулиганов - девушка, которая пытается им помешать. Осадив парней, он освобождает ее.","93953015":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","93959286":"История о совpеменной молодой женщине, котоpая кажется стpанной окpужающим ее людям. А она всего лишь мечтает о безpассудной, беспpедельной поэтической любви…","93961652":"Оперативник уголовного розыска Сергей Воронин занимает свою должность по призванию. Он создал клуб юных друзей милиции, в котором ребята занимаются спортом и встречаются с интересными людьми. Но его тревожит компания ребят, попавших по влияние циничного старшеклассника Николая Бойко, который «путает грабеж с шалостью».","93972238":"Фильм рассказывает о мальчике, который с малых лет предоставлен самому себе. Мать не может уделить сыну достаточно внимания, а отец, в прошлом хороший наездник, спился и потерял работу. Единственная радость в жизни Родьки - конь Маркиз, за которым он ухаживает как настоящий конюх.","93975994":"Международная геологическая экспедиция, возглавляемая русским инженером, работает в труднодоступном районе одной из латиноамериканских стран. Ученые оказываются заложниками базирующейся неподалеку банды, которая промышляет торговлей наркотиками. Геологам угрожает смертельная опасность…","93977374":"Психологическая кинодрама Никиты Михалкова по мотивам пьесы Софьи Прокофьевой «Беседы без свидетелей». История двух людей, некогда любивших друг друга. Фильм полностью решён в камерном стиле - действие фильма происходит в замкнутом пространстве двухкомнатной квартиры. Когда-то он оставил жену и сына, чтобы жениться на дочери академика, тем самым…","93985859":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","93999151":"В годы войны французская актриса Мадлен Тибо, активная участница Сопротивления, случайно узнает, что ее сын завербован фашистами. Все ее попытки пробудить в сыне патриотические чувства безуспешны. По вине Шарля погибают многие люди, в смертельной опасности оказывается и сама Мадлен…","94002276":"Новая серия Простоквашино — Сила рекламы на нашем канале.","94003100":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","94015144":"Английский лекарь, по ошибке осужденный на каторжные работы, сумел бежать. Бывшие заключенные, захватившие испанский фрегат, вынуждены поднять черный пиратский флаг. Они по-прежнему вне закона, и на них объявлена настоящая охота…","94023612":"События развиваются в XV веке. Тверской купец Афанасий Никитин отправляется в опасное морское путешествие в Индию. В результате ему удается проложить торговый путь из Европы в эту далекую и загадочную страну. Историко-биографический фильм, снятый по путевым заметкам русского путешественника и первооткрывателя Афанасия Никитина. Его сочинение «Хождение за…","94031416":"Лето 1943 года. Советскому командованию становится известно, что на оккупированной территории Украины действует специальная разведшкола по подготовке разведчиков и диверсантов. «Все мы здесь, ребятки, не первый год замужем, посему откровенен. Операция нас ждёт тяжелейшая», — с такими словами Егор Сёмин предупредил группу советских разведчиков,…","94041274":"Экранизация одноименной пьесы К.Симонова. Начало 70-х годов. Известному и преуспевающему американскому журналисту стало известно, что некими силами в Америке замышляется провокация, которая может вызвать новую войну. Человек, сообщивший ему эти сведения, надеется, что он опубликует их в европейской печати и тем самым предотвратит угрозу, нависшую над…","94043455":"👀 Приключения Пети и Волка продолжаются! В сериях 21–29 друзей ждут новые испытания и весёлые открытия.","94043797":"Скромность и принципиальность приводит инспектора ГАИ Петра Зыкина к конфликту с начальником станции технического обслуживания Труновым, который, нарушив правила дорожного движения, пытается воспользоваться своими связями и «поставить на место» не в меру ретивого милиционера. Однако ничто не может заставить Зыкина изменить своим принципам: ни связи, ни…","94048231":"В августе 1945 года герои предыдущей ленты «Приказ: огонь не открывать» получают долгожданный приказ: «Перейти границу». В сложных условиях Дальнего Востока проходят первые боевые действия батальона капитана Тихонова. Попав в ловушку, они ищут выход из опасной ситуации…","94063260":"Музыкальный фильм, поведавший об одном удивительном дне из далекого прекрасного детства дедушки Пети, когда он побывал в цирке, на летном поле, летал сам, пережил много интересного, необычного. Впечатлениями этого дня дедушка поделился со своим пятилетним внуком Петей в день его рождения.","94064670":"В телевизионной постановке режиссер Карен Шахназаров представит зрителям свой новый взгляд на великий роман.","94067338":"В основе сюжета — нравоучительная история о том, как два брата выросли в разных местах: один — в деревне, с мамой, другой — в городе, у тетки. Деревенский — самостоятельный, работящий, надежный. А городской — избалованный, себе на уме. Встретились братья — и поняли, что если хотят они остаться родными людьми, надо им заново учиться понимать и беречь друг…","94074633":"Как найти свое призвание? Есть ли способы распознать талант в детстве? Можно ли сменить профессию в 30? Добрая и остроумная советская комедия «Как стать счастливым» с Николаем Караченцовым и Львом Дуровым дает ответы на все эти очень актуальные вопросы. Великолепная игра актеров, искрометный юмор, затрагивающий вопросы отнюдь не только выбора профессии,…","94076471":"Биографический сериал «Михайло Ломоносов» состоит из 9 серий:","94079701":"Счастливые дни первой любви восьмиклассников потускнели, когда они узнали, что Надина мама и недавно овдовевший отец Сережи собираются жить вместе. Юношеский максимализм подростков больно ранит родителей.","94082667":"Фильм повествует о жизни и приключениях советских школьников в предвоенные годы. О том, как вчерашние друзья — одноклассники едва не становятся врагами.","94095651":"Комедия Аллы Суриковой \"Две стрелы\", 1989 г.","94096532":"Середина 1920-х годов. Десять демобилизованных красноармейцев, командир погранзаставы с женой и ученый-геолог едут по Каракумской пустыне к железнодорожной станции. По дороге им встречается полуразрушенная мечеть с замаскированным колодцем во дворе, в котором вместо воды оказывается пулемет. Командир догадывается, что он принадлежит басмачам и решает…","94105096":"Драма Константина Худякова \"С вечера до полудня\" 2-я серия","94126249":"Драма Александра Столпера \"Живые и мертвые\" 2-я серия","94135643":"Комедия Олдржиха Липского \"Соло для слона с оркестром\" 2-я серия","94149721":"Комедия о том, как ударница труда комсомолка Надя Берестова взяла на себя задачу по перевоспитанию двух отъявленных прогульщиков и весельчаков Грачкина и Громобоева. Притворившись влюбленной в своих подопечных, Надя достигает того, что не смогли сделать ни увещевания, ни просьбы, ни приказы: Грачкин и Громобоев увлекаются работой и делами завода и…","94160394":"Суд рассматривает дело супругов Степановых. Они оставляют племяннику Никите на попечение дочку Дунечку. Но для Никиты - это тоже не самый хороший день: запись на радио, экзамены в театральном институте, да еще и ссора с любимой девушкой.","94171115":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","94181688":"Симпатичные енотики живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","94202061":"Инженер Баркасов, переживший ряд нелепых приключений и анекдотических ситуаций, в конце концов подвергает сомнению свои жизненные принципы","94202722":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","94202818":"Они не виделись двадцать пять лет - геройский экипаж истребителя, трое фронтовых друзей. Жизнь у каждого сложилась по-разному: один - убежденный коммунист, не пропускающий ни одного «красного» митинга, другой - преуспевающий вице-председатель небедного «Фонда ветеранов», третий - эмигрант, на старости лет потерявший зрение и приехавший на родину, чтобы…","94204712":"1920 год. Стран Советов в экономической блокаде. Инженер Виктор Крымов едет в Швецию с важным правительственным поручением: заказать паровозы у местных промышленников. Он и не подозревает о намерениях белогвардейцев сорвать контракт. Инженеру грозит смертельная опасность. Но кто не рискует, тот паровозы не заказывает! Сделка состоялась еще и потому, что…","94205945":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","94210174":"Миллионер Филипп Стоун, располагающий секретной информацией о ядерной политике США, убежден, что она несёт реальную опасность людям планеты. Веря в созидательную миссию искусства, он решает заказать драматургу Майклу Трентону пьесу на тему об угрозе ядерной войны. Для того чтобы написать пьесу Трентон вынужден встретиться с правительственными…","94211703":"Гениальная комедия Эльдара Рязанова. Занимает по посещаемости 19-е место среди отечественных фильмов за всю историю советского кинопроката; лучший фильм по опросу журнала «Советский экран» в 1979 году.","94224250":"По мотивам онежских былин. После долгих странствий по свету в поисках птицы счастья гусляр и купец Садко возвращается домой, в Великий Новгород. Может быть, здесь он найдет свое счастье?","94233076":"По мотивам одноименного романа Л.Фейхтвангера. Приход фашизма в Германии показан через призму трагедии еврейской семьи: Эдгар Оппенгейм – известный хирург-офтальмолог. Рядом – дружная, подающая надежды молодежь. С появлением фашистов против них начинается травля. Оппенгейм попадает в тюрьму, его сын кончает жизнь самоубийством, брат Эдгара – Мартин – на…","94234361":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","94252554":"В далеком горном селении отцы и матери провожают своих сыновей на фронт. Согласно традиции, горец не должен расставаться с оружием своих предков. Пожилая Патимат просит лейтенанта Зворыкина передать ее сыновьям Султану и Магомеду древние родовые кинжалы. Он не соглашается, боясь нарушить устав. Но и обычай нельзя нарушать, поэтому одинокая мать, взяв в…","94261272":"Веселая фантазия о пребывании на Кавказе великого французского романтика. Необычайные приключения, любовь, дружба, верность помогают герою, вступившему в борьбу с жестоким и коварным черкесским князем Вахвари.","94262383":"Нестареющий приключенческий фильм «Гардемарины, вперед!», снятый по роману Нины Соротокиной  «Трое из Навигацкой школы», предлагает вам погрузиться в дымку юношеской романтики вместе с гардемаринами и снова вспомнить, каким он был, век восемнадцатый... В основе сюжета — политические и любовные интриги русского двора времен Екатерины II.  Именно тогда в…","94272527":"У отца, капитана торгового флота, было три сына : Кирилл - художник, Юрий - моряк, Герка - музыкант. Казалось бы, ничто не может помешать их дружбе. Но старший и средний братья влюблены в одну девушку - Светлану. Соперничество делает их врагами. Юрий не может простить измены, и между братьями происходит крупная ссора. Неожиданно на семью обрушивается…","94280734":"По одноименной повести В.Конецкого. В поисках романтики пятнадцатилетний Васька устраивается уборщиком на судно \"Кола\". Васька нравится команде, и только боцман Росомаха - прекрасный моряк, но тяжелый, угрюмый человек - не испытывает к нему добрых чувств. Под его руководством Ваське предстоит отправиться в экспедицию на Новую Землю.","94286420":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","94289463":"Опытный разведчик, сын русского эмигранта графа Тульева, должен добыть для западных спецслужб сведения о разработках в советской атомной промышленности.","94291546":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","94292895":"Маленький мальчик Стёпка очень любил слушать перед сном сказки, которые сочиняла его мама. И вот однажды она рассказала ему о реке, возле которой они жили. Это была большая и могучая река, но она нуждалась в защите и заботе человека. Утром мама не нашла Стёпку - он ушел искать исток реки. Так начались Степкины приключения...","94300816":"По пьесе А.Вейцлера и А.Мишарина \"День-деньской\". Действие фильма происходит в середине 70-х годов, во время так называемой научно-технической революции в СССР. Директора крупного предприятия Игоря Друянова собираются снять с работы за невыполнение государственного плана. На его место хотят назначить молодого энергичного сотрудника министерства Дмитрия…","94303528":"По одноименной новелле Ги де Мопассана. 1870 год, Франция оккупирована Пруссией. В дилижансе из Руана едут граф с женой, чета виноторговцев, фабрикант, монахини. В пути к ним присоединяется Елизавета Руссэ, более известная в городе под именем \"Пышка\". Путники остановиваются на ночлег в придорожной гостинице. Прусский офицер, увидев аппетитную Пышку,…","94307700":"Военная драма Сергея Колосова \"Вызываем огонь на себя\"","94320736":"Гениальная комедия Эльдара Рязанова. Занимает по посещаемости 19-е место среди отечественных фильмов за всю историю советского кинопроката; лучший фильм по опросу журнала «Советский экран» в 1979 году.","94332869":"20-е годы. Воспитанники детского дома - пионеры Петька, Кузька и Санька - направляются райкомом комсомола для ликвидации неграмотности в глухую деревню Пеньки.","94339813":"Фильм-сказка Ивана Никитченкова и Виктора Невежина \"Руслан и Людмила\"","94342223":"Герой вырос в потомственной семье металлургов: высокий белокурый красавец, не без чувства своеобразного юмора, передовик труда, спортсмен. Познакомившись при весьма неординарных обстоятельствах со вздорной девчонкой, влюбился.","94350520":"Кир Лопухов и Алеша Мамыкин — одноклассники, только что получившие аттестат зрелости. Началась война и ребята, не задумываясь, так же вместе поступают в одну артиллерийскую спецшколу.","94350964":"Рабочий завода Виктор Белов избит в парке двумя подростками. Один из них попадает на два года в исправительную колонию, другой — получает срок условно. А Белов по-прежнему работает на заводе. Жизнь, как и прежде, очевидна и однозначна: завод, чуткая жена и заводские спортивные состязания. Однако воспоминания о прошедшем суде не дают ему покоя. Все было…","94351597":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","94365260":"Бессмертный роман Михаила Шолохова, отмеченный Нобелевской премией и вошедший в число наиболее ярких произведений мировой литературы, рассказывает о трагической ситуации, сложившейся в России в начале ХХ века, о сломанных Первой мировой войной и революцией судьбах людей, о крушении устоев и идеалов донского казачества, о личной трагедии главного героя -…","94368673":"Выпускники одной из московских школ через двадцать лет после окончания собираются вместе. Каждого просят ответить на два вопроса: «Что вы уже сделали?» и «Чего еще в жизни ждете?». Вместе с бывшими однокашниками пытается найти ответы на поставленные вопросы и главная героиня фильма - многодетная мать Надя Круглова.","94375024":"Драма Станислава Говорухина \"Брызги шампанского\"","94378516":"Ольга Васильева выросла в детдоме и никогда не знала своей матери. Волею судьбы ей в руки попало старое письмо, написанное ее матерью много лет назад, и она, бросив все, едет из Свердловска в Москву с надеждой встретиться с родным человеком…","94379553":"Между царем и солдатом Иваном происходит нешуточный спор. Бывалый солдат, конечно, берет верх над вздорным государем. Но до той поры приключится в царстве много необычного и веселого…","94380670":"Экpанизация одноименного pомана М.Гоpького. После отмены крепостного права Илья Артамонов открывает фабрику полотна. Его стремление укреплять и развивать дело не знает преград, и для крестьян он свой человек. С его смертью все меняется. Петра, сына Ильи, угнетает необходимость руководить сложным производством. Между Артамоновым и рабочими нарастает…","94388333":"Комедия абсурда Карена Шахназарова \"Город Зеро\"","94389842":"Димке пять лет, и у него нет отца. Однажды мальчик решил, что деньги, отложенные на покупку папы, мама просто потратила на мороженое. Он решил сам исправить положение - и отправился в универмаг, в витрине которого однажды видел очень красивого «дядю»…","94390290":"Жительница Магадана Укладова ограблена в московском переулке. Она утверждает, что ее ударил молотком по голове и отнял большую сумму денег таксист. Следователь находит таксиста, сидевшего уже за хулиганство. Против подозреваемого все факты, но он не сознается. Люди, знавшие его, убеждают, что на такое преступление парень не способен. Укладова, однако,…","94394323":"Попав в столицу, провинциальная девчонка, мечтающая выучиться на артистку, быстро расстается с романтическим представлением о жизни как сплошном празднике. Зато начинает понимать, что в мире действительно стоит ценить и что вовсе не имеет цены.","94398124":"Гражданская война в России. Бок о бок с красноармейцами, защищая молодую советскую республику, сражаются венгерские интернационалисты. Фильм рассказывает о героизме бойцов Красной армии и представителей разных национальностей, сражавшихся вместе.","94399207":"Преуспевающий молодой журналист едет в небольшой промышленный город с тем, чтобы разобраться в письменных жалобах некой Аникиной.","94407908":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","94408035":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","94408078":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","94408919":"Фильм Валерия Кремнева \"Последние каникулы\"","94410460":"В деревню Опенки приезжает молодой и красивый священник отец Михаил. Отремонтировав полуразрушенную церковь, батюшка начинает службу. Но образованный священник не внушает доверие старушкам и, тем более, молодым опенковцам, у которых общеизвестные взгляды на веру. Однажды в Опенках появляется благообразный старичок Филин — святой жизни человек.…","94415836":"Экранизация одноименной повести А.Куприна. Начало XX века. Подпоручик Ромашов служит в полку, расквартированном в небольшом городишке российской провинции. Чуткому молодому офицеру претит муштра, беспробудное пьянство сослуживцев, томление в бездуховности. Единственное, что наполняет смыслом существование Ромашова, это его любовь к жене капитана…","94421349":"Действие фильма происходит в годы Второй мировой войны. Выйдя из госпиталя, молодой лейтенант на несколько часов попадает в Москву, в свой дом, где прошли его детство и юность.","94421809":"По мотивам водевиля П.Федорова \"Аз и Ферт\". Богатая девица в летах Евпраксия Аристарховна Фырсикова завещает состояние своей племянице Любе при условии, что та, достигнув восемнадцати лет, выйдет замуж за человека, имя и фамилия которого начинаются с букв \"аз\" и \"ферт\". В дни празднования победы над Наполеоном Люба знакомится с молодым гусаром Антоном…","94442549":"Школьники Роман и Катя тянутся друг к другу со всей безоглядностью первой любви. Мать Кати очень счастлива во втором браке и в озарении этого счастья хорошо понимает дочь. Роман находит поддержку у отца, давно и безответно любящего Катину маму. Но рядом ходят люди, ничего не знающие о любви...","94448392":"В прифронтовой полосе группа девушек-зенитчиц вынуждена вступить в неравный бой с вражескими десантниками. Эти девчонки мечтали о большой любви, нежности, семейном тепле - но на их долю выпала жестокая война, и они до конца выполнили свой воинский долг…","94453718":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","94456153":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","94461252":"Пионерский лагерь на берегу Чёрного моря. Перед началом традиционной военной игры обнаруживается пропажа пионерского горна. В поиски включается весь пионерский отряд. И пока ребята ищут пропажу, они ссорятся, мирятся и переживают всевозможные приключения.","94465924":"Новая серия Простоквашино — Тайна старой таблички на нашем канале.","94468724":"Весна 1942 года. Эшелон с эвакуировавшимися детьми из Двинского детского дома попадает под авиабомбардировку гитлеровцев. После налета дети оказываются на оккупированной территории в районе действий белорусского партизанского отряда. Для обнаружения народных мстителей фашисты решают использовать детей.","94468907":"Фильм построен как рассказ девочки о своем папе, о том, что с ним происходило, когда он тоже был маленьким, и как он становился взрослым. Она представляет: если бы папа был сейчас её ровесником... Какие замечательные приключения ждали бы их…","94471619":"Новая серия Простоквашино — Шарик ловит хайп на нашем канале.","94481995":"Исторический фильм Сергея Бондарчука \"Война и мир\". Фильм 1-й \"Андрей Болконский\" 1-я серия","94486013":"Драма Сергея Бондарчука \"Судьба человека\"","94486500":"Когда-то — еще в пятидесятые — Беглов был звездой чечетки. А сейчас ему даже неприятны воспоминания о тех далеких днях. Как будто бы это было не с ним. Но приезжает в Москву молодой человек с твердым намерением овладеть чечеткой. Без комплексов и намеков на способности, но с большим желанием танцевать он обращается именно к Беглову — тому самому Беглову,…","94500629":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","94510646":"«Семейное счастье» - комедийный киноальманах из четырёх новелл, снятых режиссёрами Сергеем Соловьёвым, Александром Шейном и Андреем Ладыниным в 1969 году.","94525130":"Фильм Василия Ордынского \"Первая любовь\", 1968 г.","94530466":"Фильм для всей семьи. Кыш — это маленький, проворный щенок, а Двапортфеля — это прозвище первоклассника Алеши, который получил его из-за своего маленького роста. Эти двое с необычными именами становятся самыми настоящими друзьями! Однако Алеша, который совсем недавно пошел в школу, встретил там не только добрых людей... Но верные друзья помогут пережить…","94530943":"Шестиклассник Митя Громов хочет остаться на второй год, потому что ему нравится Нина, которая по всей видимости не перейдет с ним в следующий класс. Еще он пытается спасти старую лошадь, которую ведут на бойню, но действует при этом незаконно. А потом, помогая однокласснику Ване в учебе, похищает его из дома... Как долго эти странности будут продолжаться…","94541777":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","94547489":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","94548531":"У маленькой девочки Тани есть верный товарищ - пес по кличке Друг. Он спасает ее, когда она тонет, находит девочку, когда та теряется, носит в школу ее тетради, а однажды даже помогает задержать вора! А когда Таня заболевает, ее преданный Друг не отходит от своей маленькой хозяйки ни на шаг...","94553794":"Январь 1945 года. Советская армия громит фашистов уже на их земле. В один из дней к Гиммлеру из Нью-Йорка прилетают сенатор Аллен и некто Гарви из Бюро стратегической информации. Они разрабатывают план, как захватить Европу и прибрать к рукам патенты промышленных германских корпораций. Наши разведчики Марта и Дементьев должны добыть всю информацию и…","94555986":"Драматический триллер Эллы Архангельской \"Клетка\"","94560114":"Новая серия Простоквашино — Снежный лабиринт на нашем канале.","94567474":"Кинокомедия Георгия Натансона «Аэлита, не приставай к мужчинам»","94573043":"Подобно многим женщинам послевоенного времени, Клавдия одна воспитывала сына. Они были верными друзьями и союзниками против всех невзгод. Однажды в этом доме появилась красивая и беспечная девушка. Мать старалась не мешать сыну быть счастливым. Но случилось несчастье: фронтовое ранение дало о себе знать - и женщина ослепла...","94576705":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","94579040":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","94579947":"О судьбе великого русского изобретателя и конструктора XVIII века Ивана Кулибина и о юном школьнике — изобретателе Вовке Морковкине, который продолжает дело своего знаменитого предшественника.","94584609":"Шел 1927 год. Сын батрака Филипп Касаткин вступил в комсомол и начал кипучую деятельность, полную забот, побед и поражений…","94593358":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","94600827":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","94600960":"В основе сюжета кинодилогии - исследование сложных судеб коммунистов-антифашистов разных национальностей. Фильм основан на биографиях реальных людей, чья жизнь вобрала в себя самые драматические этапы истории 30-50-х годов XX века.","94605774":"Кинокомедия Алексея Грановского \"Еврейское счастье\"","94611156":"Витус Беринг, датчанин по происхождению, который прослужил интересам России более 20-ти лет, в 1725 году по указу Петра Первого возглавил северную экспедицию. Участники героического путешествия сделали новые открытия и нанесли на карту точные контуры российской империи.","94614949":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","94622528":"Фильм о том, как повзрослел семилетний Гришка, оказавшись невольным (но очень активным) участником гражданской войной в родном селе. Как научился любить и защищать своих друзей и не бояться врагов, какими бы могущественными и жестокими они не были.","94634687":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","94648279":"Студенты ПТУ - Саша Лукашов, Бонифаций и Серый - в поисках приключений зашли в гости к Алхимику, недавно вернувшемуся из заключения. Позже, ночью, в пьяном угаре, забравшись в зоопарк, убили ланей - и протрезвели.","94664695":"В первые послевоенные годы в небольшом шахтерском поселке под Тулой живут в основном женщины и подростки. Матери наравне с мужчинами работают в шахте. Дети живут своей жизнью и зависимы от семнадцатилетнего уголовника по прозвищу Зверь. Он всем недоволен, его все боятся и стараются с ним не связываться. Его арестуют только тогда, когда от его руки…","94672904":"В мае 1945 года на освобожденной территории Германии в течение двух дней советские солдаты проводят операцию по спасению детей в небольшом городке Бланкенгайме от нападения группы вервольфовцев.","94682717":"Музыкальная комедия. 1913 год. Россия отмечает 300-летие дома Романовых. Пароход «Святитель Николай» плывет по Волге в Нижний Новгород — центр праздника. На его борту респектабельная публика: коммерсанты, промышленники, князья... Все развлекаются. Богатый купец Фрол Сатановский играет в покер с другими купцами, не подозревая, что за одним столом с ним…","94684546":"Новая серия Простоквашино — Обидное слово на нашем канале.","94687614":"Комедийный фильм Константина Юдина \"Близнецы\"","94699538":"Скучающий без друзей семилетний Олежка написал письмо в газету с просьбой прислать ему оловянных солдатиков. И вот в деревне появились семеро настоящих солдат. Однако звали их совсем по-сказочному: Понедельник, Вторник, Среда, Четверг, Пятница, Суббота и Воскресенье.","94700610":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","94709791":"Драма Василия Ордынского \"Человек родился\"","94711780":"Профессиональный разведчик Ингмар Росс, сотрудник одного из посольств, получает задание — завербовать специалиста московского засекреченного предприятия. Но, полюбив русскую женщину, Росс отказывается от двойной жизни и решается на довольно неординарный поступок.","94720126":"1922 год - время, когда в Хакасии шли изнурительные бои красных с бандой атамана Соловьева. Фильм воспроизводит одну из малоизвестных страниц биографии Аркадия Гайдара (Голикова), когда он юношей был назначен командиром отряда ЧОНа (частей особого назначения).","94721654":"Детский фильм Евгения Зильберштейна и Анатолия Дудорова \"Звездный мальчик\"","94722871":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","94727572":"Фильм снят по одноимённому роману Жюля Верна. Экипаж яхты «Дункан» лорда Гленарвана в водах Шотландии поймал акулу. При разделке туши внутри рыбы оказалась бутылка, в которой на трёх языках написана просьба о помощи от потерпевших кораблекрушения. Вода сильно испортила документы, однако удалось разобрать, что капитан Грант и его члены экипажа потерпели…","94755894":"Абсурдистская трагикомедия, в которой ничто не поддается логическому осмыслению. История, маскирующаяся под притчу, - о кризисе среднего возраста. Несколько сорокалетних мужчин отправляются на военные сборы. Собой они представляют срез социума СССР того времени: учёный-астроном, мясник из магазина, рабочий завода, грузчик, архитектор, водитель…","94757554":"Сорвав в поле неведомые цветы, Катя и не подозревала, что нашла чудодейственную «кащееву траву» и, значит, пришла пора расколдовать Василису Прекрасную.","94758370":"1820-е годы. Сын плотника Жюльен Сорель боготворит Наполеона и мечтает о славе. Благодаря способностям и образованию он оказывается в среде сначала провинциального, а затем и высшего дворянства, но жизнь сложилась не так, как ему хотелось бы.","94760944":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","94761502":"По одноименному романа М.Шолохова. О том, как на Дону в острых противоречиях, трудно и напряженно проходило проведение коллективизации.","94763430":"Новая серия Простоквашино — Банный день на нашем канале.","94764808":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","94785547":"Фильм, основанный на реальных событиях 1959 года, рассказывает о любви русского доктора Гусева и японской женщины Кейко. Гусев  - ученый профессор-иммунолог, создатель вакцины против полиомиелита. Вопреки бюрократическому сопротивлению чиновников обеих стран, он добивается отправки нового лекарства в Японию и таким образом спасает 10 миллионов детей.","94788407":"Кинокомедия-фельетон о советском бюрократизме 1950х гг. Петухов, руководитель некой организации под названием КУКУ (кустовое управление курортных учреждений) ,берет отпуск, чтобы жениться. Вместо себя на работе оставляет зама-бюрократа по фамилии Фикусов. В электричке воришка крадет у героя фильма бумажник с деньгами и документами и тут же попадает под…","94791652":"1956 год. По нелепому стечению обстоятельств Алексей Лапин совершает побег из лагеря за месяц до своего освобождения. Случайность спасает героя от розыска. Приехав в Ленинград, Алексей влюбляется в дочь рабочего, у которого снимает комнату, — и решает начать честную жизнь.","94794871":"По мотивам повести И.М. Лаврова \"Встреча с чудом\". Сестры-близнецы Ася и Слава после окончания школы не намерены поступать в обычный институт - их манит море. Однако вступительные документы в мореходное училище им возвращают. Но разве могут отчаяться две юные девушки, мечтающие стать капитанами дальнего плавания? Сестры убегают из дома навстречу…","94800211":"Военная драма Ларисы Шепитько \"Восхождение\"","94809287":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","94813556":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","94818977":"Новая серия Простоквашино — Суперцветик на нашем канале.","94819811":"По мотивам одноименного романа О.Бальзака. XIX век, Франция. Евгения, дочь богатого буржуа Феликса Гранде, влюблена в своего кузена Шарля. Однако весть о самоубийстве обанкротившегося отца Шарля прерывает роман влюбленных. Патологически скупой Феликс Гранде отказывается расплатиться с кредиторами родного брата, поэтому Шарль вынужден уехать навсегда.…","94820921":"Киноверсия балета «Золушка» Сергея Прокофьева, поставленная советским режиссером-сказочником Александром Роу и балетмейстером Ростиславом Захаровым. Знаменитая история, рассказанная в танце. Золушка — несчастная девушка, которую мачеха и сводные сестры считают своей прислугой. Ее даже не хотят пускать на королевский бал, чтобы она ни в коем случае не…","94824511":"О творчестве популярного советского актёра Вячеслава Тихонова рассказывают: Борис Андреев, Эраст Гарин, Сергей Бондарчук, Всеволод Санаев, Евгений Матвеев, Алексей Баталов, Борис Бибиков, а также родители Вячеслава Васильевича.В фильме рассказывается о детских и юношеских годах Тихонова, о его актёрской карьере, самых запоминающихся ролях в кино. Текст…","94827819":"Инженер Баркасов, переживший ряд нелепых приключений и анекдотических ситуаций, в конце концов подвергает сомнению свои жизненные принципы","94837221":"Школьница Машенька попадает в сказочный Город веселых тружеников, которых с помощью слуг и колпака-невидимки угнетает злой король Кроподин I. До того, как горожане окончательно избавятся от угнетателей, Машенька будет участницей увлекательных событий и приключений.","94837997":"Однажды четвероклассник Толя Рыжков нашёл волшебные спички, исполняющие любое желание. И началась у Толи вольготная жизнь! Вместе с другом он оказался на волшебном острове. Но вскоре ребята поняли, что возвращаться им придётся самостоятельно.","94854139":"Официантка вагона-ресторана, побывав в очередной раз в родных Ферзинках, где живет в интернате ее маленький сын, и познакомившись с режиссером местного театра, решила больше не колесить по свету, а воспитывать сына и быть с любимым человеком...","94856103":"Комедия Татьяны Лукашевич \"Учитель танцев\"","94859803":"На войне слова любви тонут в грохоте орудий. Но самый кровавый бой рано или поздно заканчивается. Во время короткой передышки можно сменить автомат на томик Есенина и помечтать о прекрасной польской девушке из освобожденной деревни. Когда молчат пушки — говорят музы.","94861908":"Когда принцу пришла пора жениться, на воротах дворца появилось объявление: «Требуется принцесса». Но не дождался принц визита и отправился на поиски сам.","94871895":"Редкий для тех времен совместный советско-французский проект. История раскрытия и предотвращения покушения нацистов на глав правительств СССР, США и Великобритании во время Тегеранской конференции 1943 года.","94875818":"Комедия Владимира Немоляева \"Счастливый рейс\"","94877776":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","94881685":"Миллионер Филипп Стоун, располагающий секретной информацией о ядерной политике США, убежден, что она несёт реальную опасность людям планеты. Веря в созидательную миссию искусства, он решает заказать драматургу Майклу Трентону пьесу на тему об угрозе ядерной войны. Для того чтобы написать пьесу Трентон вынужден встретиться с правительственными…","94914548":"Начало 1970-х годов, предновогодняя сутолока большого города. Московские шестиклассники Костя и Тоша и четырёхлетний брат Кости, Руслан, стараются найти Катю Иноземцеву, чтобы передать важную телеграмму. В ходе поисков они узнают о волнующих героических страницах её жизни.","94926567":"Что важнее: действовать или оставаться верным себе?","94928758":"Драма Всеволода Пудовкина \"Возвращение Василия Бортникова\"","94939201":"Приключенческий фильм о советских ученых-океанологах. На дне Тихого океана происходит взрыв, в результате которого подводная растительность начинает быстро увеличиваться в размерах. Научный сотрудник института океанологии Денисов, оказавшийся свидетелем стихийного бедствия, предполагает, что это происходит под воздействием нового радиоактивного элемента,…","94939977":"🎬 Включайте сборник и смотрите, чем обернутся новые идеи простоквашинцев!","94946751":"«Они встретились в кафе... Он — физик, она — стюардесса. Он привык всё объяснять формулами, она — просто верить в чудо».","94949925":"Симпатяга-парень Сергей Ковалев решил, что инженер — не его профессия, и уехал к родственникам в провинциальный городок Серебряные Озера. Там познакомился с семьей молодого художника, неожиданно озлобился — и решил отомстить новому другу. Своеобразная дуэль на мотоциклах для Игоря закончилась трагически.","94959653":"Попав в столицу, провинциальная девчонка, мечтающая выучиться на артистку, быстро расстается с романтическим представлением о жизни как сплошном празднике. Зато начинает понимать, что в мире действительно стоит ценить и что вовсе не имеет цены.","94961601":"Фильм рассказывает о детстве и юности жены, друга и боевого соратника основателя страны Советов Надежде Константиновны Крупской. Главное внимание в фильме уделено участию молодой революционерки в организации борьбы рабочих Петербурга за свои права, против самодержавия.","94978195":"О творчестве популярного российского актера Вячеслава Тихонова рассказывают: Борис Андреев, Эраст Гарин, Сергей Бондарчук, Всеволод Санаев, Евгений Матвеев, Алексей Баталов.","94992213":"«Верные друзья» - кинокомедия Михаила Калатозова по одноименной книге Александра Галича. Фильм о путешествии, настоящей Одиссее, предпринятой тремя верными друзьями средней упитанности и средних лет. Когда-то давно на одной из московских окраин жили три товарища: Сашка — «Кошачий барин», Борька — «Чижик» и Васька — «Индюк». Прошли годы. Чижик стал…","95010643":"60-е годы. Окончив десятилетку, Виктор Чернышев, теперь городской житель, не стал утруждать себя продолжением образования и пошел на завод токарем. Он считал вполне нормальным, что ребята с упоением слушали россказни его ровесника Коли, тунеядца, хваставшего победами над женщинами, участвовали в его сомнительных забавах. Лишь один из них, Петр —…","95012410":"Борьба с космическими пиратами, захватывающее путешествие во времени, знакомство с девочкой из будущего Алисой Селезневой — вот к чему привел обычный поход за кефиром мальчика Колю из 6-го класса.","95013413":"Отца Игоря Гусева, капитана морского флота, перевели служить на отдаленный северный остров. Игорь забросил занятия музыкой, но отец хочет, чтобы он играл на аккордеоне и пел. Мальчик не считает себя талантливым, но в новой школе, куда пришел учиться Игорь, полным ходом идет подготовка к весенней школьной олимпиаде по художественной самодеятельности.…","95017969":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","95028152":"Юный конструктор Алеша привез в Москву «живой» макет будущей столицы, которая позволяет представить процесс реконструкции столицы. Алеша встречает в Москве свою любовь — Зосю, вместе они работают над строительством модели, ее предстоящая демонстрация вызывает большой интерес общественности. Не обходится без курьеза: Алеша опоздал к началу демонстрации,…","95030805":"Комедия Эльдара Рязанова \"Девушка без адреса\"","95054955":"О политических событиях в России начала века, в период зарождения социал-демократической партии, среди первых бойцов которой - Вера Протасова, дочь адвоката, защищавшего народовольцев на суде.","95073427":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","95103973":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","95116221":"«Жизнь прекрасна» (1980) — напряжённая драма Григория Чухрая о цене свободы в условиях диктатуры. Бывший лётчик Антонио Мурильо (Джанкарло Джаннини) хотел лишь одного — спокойно жить и вернуться в небо. Но когда система начинает давить, а друзья оказываются в опасности, он делает выбор: бороться.","95124362":"Андрюша и его товарищи по пятому классу в груде утильсырья отыскали плохо переплетенные машинописные страницы с надписью «Атака». Ребята восторженно зачитываются этим собранием фронтовых рассказов. Автор их Букин, оказывается, живет неподалеку, в соседнем квартале. Человек немолодой и болезненный, он, однако, не поддается ударам судьбы. Все свои силы он…","95132495":"Молодой песец Наполеон III, сбежав со зверофермы, оказался в деревне Ковылкино. Вслед за ним в деревню нагрянули охотники, работники зверофермы, отряд милиции и корреспонденты. Благодаря шестилетнему мальчику все завершилось благополучно, а люди, принимавшие участие в погоне за молодым песцом, вернулись к своим делам.","95133688":"Гражданская война. Партизанский отряд Левинсона получает приказ соединиться с другими партизанскими отрядами для дальнейших боевых действий против японцев и белогвардейцев. Во время дислокации партизанский отряд попадает в окружение…","95143508":"Вместе с друзьями он узнаёт, как устроен север, открывает для себя важные вещи — дружбу, поддержку и взаимопонимание.","95143830":"Виктор Кольцов, демобилизовавшись из армии, становится работником милиции. Расследуя дело о квартирной краже, Виктор выходит на одиннадцатилетнего парнишку, сбежавшего из детского дома. Однако герой не принимает крутых мер, а знакомится поближе с детьми и делает все возможное, чтобы вернуть обездоленным детям надежду и веру в лучшую жизнь","95144954":"Cоветский художественный фильм 1958 года. События разворачиваются в небольшом польском городке, последние дни войны.  Смерть в свисте каждой пули, каждого снаряда. Горящие здания, голодные люди в подвалах. Сколько людей прошло по огненной земле - терпеливых, мужественных, молчаливых. Рядом с ними шагал кинооператор Владимир Сушков, создавая суровую…","95161582":"Исторический фильм Сергея Бондарчука \"Война и мир\". Фильм 1-й \"Андрей Болконский\" 2-я серия","95162736":"Легендарная советская комедия Георгия Данелии \"Мимино\" , 1977 г.","95162842":"Историко-революционный фильм о жизни и деятельности молодого В.И.Ленина в период сибирской ссылки в село Шушенское и в первые годы эмиграции.","95165960":"Красные колокола. Фильм первый \"Я видел рождение нового мира\". Первая серия.","95167911":"Выпускник танкового училища Тимофей выбирает Каракумы. «Тяжело в ученье — легко в бою» — таков его принцип.","95169889":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","95170410":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95174303":"Придя руководить школой, новый директор решает ввести в ней школьное самоуправление, создать ребячий актив — из тех, кто совсем недавно были хулиганами, в ком есть, но неправильно используется организаторский талант, способность быть лидером…","95176210":"Однажды школьница Оля взглянула в самое обычное зеркало, которое висело дома в прихожей, и неожиданно отправилась путешествовать в волшебную зазеркальную страну вместе со своим отражением - озорной девочкой Яло. Вдвоем им удается вызволить из тюрьмы мальчика Гурда и разрушить злые чары кривых зеркал…","95190614":"В основе этой истории лежит реальный факт создания в военные годы фронтовой актерской бригады, чьи концерты поднимали боевой дух солдат. Началось все с отъезда выпускников театрального училища в белорусский город, где намечалось основать молодежный театр. Однако в дороге будущие артисты узнают о нападении Германии на СССР и попадают под обстрел...","95214831":"Начало 20-х годов. На Северном Кавказе готовит контрреволюционный мятеж банда под руководством «Головы Горгоны». Красноармеец Светлов, возвращаясь с фронта домой, становится жертвой напавших на него бандитов и оказывается в госпитале, самом центре белогвардейского заговора.","95218114":"Сотрудники одного из отделов МВД, старший инспектор уголовного розыска капитан Юрий Грановский, инспектор старший лейтенант Левон Аветисов и инспектор лейтенант Виктор Петров, готовятся к операции по задержанию опасного вооруженного преступника, которая пройдет в Крыму. Операция должна пройти без риска для отдыхающих.","95218500":"Действие фильма происходит в 1945 году. Подростки, живущие в тыловом городке, прослышали, что где-то в подвалах соседнего дома таится клад. Дело чести найти его, чтобы помочь фронту. Но кладоискательство чуть не стоило ребятам жизни.","95229460":"Молодой инженер едет к месту назначения - в портовый город Сибирск, где его назначают руководить группой крановщиков. Герой довольно быстро осваивается с портовой работой. А вскоре в Сибирск приезжает его невеста, архитектор по профессии…","95231784":"Известный герой восточных преданий Ходжа Насреддин - серьезный шутник, мыслитель и правдоискатель - по воле авторов стал молочным братом и другом юности не менее знаменитого, но во всем противоположного ему - тирана и самодержца Тимура Тамерлана…","95233398":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","95241632":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","95242883":"Криминальная драма советского периода режиссёра Вадимом Дербенёвым по одноимённому роману Лазаря Карелина. Затрагивает тему преступлений, связанных с так называемыми «цеховиками» и прочими участниками советской теневой экономики. Главный герой -- Павел Шорохов - до тюремного заключения был директором крупнейшего московского гастронома, у него была семья,…","95248951":"Юная девушка Вероника увлечена теорией реинкарнации. И однажды Вероника решает проверить искренность чувств ее жениха. Девушка оставляет у себя в квартире... живую корову с запиской, что ее душа пересилилась в это животное. Ситуация осложняется тем, что на носу знакомство Вероники с родителями возлюбенного...","95249503":"Первая серия кинокартины \"Братья Карамазовы\"","95253547":"\"Солярис\" в 4K — шедевр Андрея Тарковского, который заставляет задуматься о любви, памяти и границах человеческого сознания. Полная версия в потрясающей 4K-реставрации от Мосфильма (2025). Философская фантастика по роману Станислава Лема, изменившая sci-fi навсегда.","95255472":"Военная драма Сергея Колосова \"Вызываем огонь на себя\"","95263157":"🌨️ Зима — это не только холод, но и повод для открытий!","95270905":"Батальоны уже на немецком берегу. Они держат плацдарм, ждут артиллерийской поддержки\nи сигнала дивизии. Но дивизия уходит. Полковник Гуляев получает приказ отвести артиллерию. Капитан Ермаков не может поверить в то, что происходит: люди дерутся и умирают — а огня нет и не будет.","95278870":"После армии Женька Кулик пришел работать в милицию. Занимаясь бытовыми делами и мелкими кражами, он мечтал ловить настоящих преступников. Его даже за это «сыщиком» прозвали. И вот однажды Женькина мечта сбылась - лицом к лицу он столкнулся с матерым бандитом...","95296605":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","95314625":"Осенью 1921 года разгромленная в Крыму врангелевская армия находит прибежище в Болгарии. Белогвардейский полковник Сергей Егорьев живет здесь с сыном и дочерью. Его жену и младшую дочь, потерявшихся во время бегства в Севастополе, приютила семья большевика Дмитрия Шелопугина. Дмитрий направляется в Болгарию для агитационной работы среди русских солдат…","95315192":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95321001":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","95321439":"Дебютная работа режиссера Александра Митты. В фильме снимается молодой Савелий Крамаров!","95329327":"Борьба с космическими пиратами, захватывающее путешествие во времени, знакомство с девочкой из будущего Алисой Селезневой — вот к чему привел обычный поход за кефиром мальчика Колю из 6-го класса.","95343089":"Поскитавшись по чужбине, Алексей вернулся на родину и, не найдя сочувствия и понимания у близких, затравленных страхом за свои судьбы, поехал в Запорожье, где случайные попутчицы Анна Андреевна и ее дочь Таня стали первыми, кому Алексей Павлов, поведал о своих мытарствах...","95347881":"По мотивам рассказа М.Зощенко \"Не надо спекулировать\". Фильм состоит из двух новелл. Действие первой новеллы происходит в Москве в 20-е годы во времена НЭПа, а действие второй - в конце 80-х. В каждой новелле три главных героя - Галя, Сергей, Лариса. В первой - Галя, как бы невольно \"продает\" своего мужа Сергея Ларисе, во второй Лариса \"одалживает\"…","95348181":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","95348242":"Действие фильма происходит в Калмыкии, на необъятных весенних просторах которой рождается любовь между юным рабочим завода Нараном, приехавшим в Калмыкию на сакман (время скота), и внучкой чабана - Амулангой.","95351873":"Илья Громов слывет среди односельчан знатным силачом. Под руководством опытного тренера простой деревенский парень становится чемпионом мира по классической борьбе.","95365306":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","95385404":"Драма Ивана Пырьева \"В шесть часов вечера после войны\"","95389643":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95409315":"Веселый фильм о необыкновенных приключениях, которые случились с учащимся Мишкой Стрекачевым во время его путешествия через всю страну. Как только он ни передвигался: и на крыше железнодорожного вагона, и прицепившись к заднему бамперу автомобиля, и вплавь через реку.","95409562":"Исторический фильм Сергея Бондарчука \"Война и мир\". Фильм 4-й \"Пьер Безухов\"","95410353":"Бывший директор предприятия Абрикосов оказывается перед неизбежным и мучительным для него приговором - ему предложили уйти на пенсию. В его жизни начинается драматический период: шестидесятилетний Абрикосов, сильный, властный, знающий свое дело, оказывается будто выброшенным на берег. Он любит жену, сына, дочь от первого брака, но видит, как далеки их…","95420500":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","95422511":"Фильм рассказывает о драматической судьбе известного советского военачальника А.В. Горбатова. Его судьба — армия, тюрьма, лагерь, реабилитация и снова армия…","95425398":"Урожденная волжанка, воспитанница суровой и властной бабушки, Екатерина рано осталась без матери. Редкие встречи с отцом - старым, заслуженным капитаном - сформировали в ней твердый и бескомпромиссный характер. Наступила война. Не задумываясь, Екатерина пошла работать в госпиталь.","95428594":"Экранизация одноименного произведения Александра Сергеевича Пушкина.","95435645":"Фильм о героической борьбе матросов Балтийского флота против формирований Н.Юденича. Образы героев фильма навеяны подлинными матросскими письмами, а также старыми военными песнями.","95440211":"Таня Канарейкина живет в Берсеневке и ничего «романтического» не наблюдает в деревенской жизни. А вокруг летают космонавты, меняются министры, начинаются и заканчиваются чемпионаты мира. Но все это только в телевизоре.","95442595":"Рассказ о старых жителях деревни, которым из-за расширения колхозной фермы предстоит покинуть свои избы и родные места.","95443695":"Во время Второй мировой войны Леон Гаррос и Борис Ваганов бежали из фашистского концлагеря. Пятнадцать лет спустя французский журналист, решив нанести другу визит, приезжает в СССР.","95453514":"Герои картины - студенты, которые ещe не подозревают, что страна, где они родились, скоро исчезнет с карты мира. А пока вчерашние школьники беззаботно учатся в институте. Главные герои - Сергей, Люда и их общий друг Степан. Сергей начинает трогательно ухаживать за доброй и доверчивой Людой, у них завязывается красивый роман. Однако вскоре на курсе…","95457172":"Зимой 1945 года фронтовой разведчик Юрий Соснин, получив контузию , оказывается в госпитале. Сочтя его погибшим, Юрия наградили посмертно. После выписки герой , утратив память, стал работать шофером. Узнав о его судьбе, жулики вовлекают Юрия в свою шайку, и принуждают угнать машину. Но сотрудник милиции, узнав в Юрии своего однополчанина, помогает ему…","95460619":"Герои фильма: пес Фингал, кошка Мария-Антуанетта, две птички, уж по кличке Константин, а также - десятилетняя девочка Ася, ее родители и многие другие... Эта история началась с того, что кошка Мария-Антуанетта съела одну из птичек и, получив новое имя - Дрянная, ушла из дома...","95470853":"Экранизация по одноименной повести Ф.М.Достоевского. Петербург 40-х годов XIX столетия. Лето, белые ночи. На берегу Невы Мечтатель знакомится с Настенькой. Пять ночей, гуляя по городу, молодые люди рассказывают о себе. Разуверившаяся в чувствах человека, которого любит, Настенька обещает влюбленному в нее Мечтателю выйти за него замуж, но... появляется…","95472801":"Фильм повествует о детстве Юрия Гагарина - той поре жизни, которая, по собственным его словам, сыграла важную роль в формировании его характера: война, оккупация, голод, угон в Германию старшего брата и сестры, изгнание фашистов со Смоленщины, переезд семьи в Гжатск.","95474778":"Рабочий железнодорожного депо Сидоров приезжает на станцию обменять карточки на хлеб. Но день для него выдался неудачный: как раз в это время из эшелона, доставляющего на фронт штрафников, бежит его однофамилец. Конвоирам нужно найти беглеца, и не так важно, какой именно Сидоров им окажется. Так железнодорожник оказывается в штрафном батальоне, но не…","95476791":"По одноименной повести Л. Гераскиной. Одаренный, но избалованный и эгоистичный Валентин спровоцировал в школе конфликтную ситуацию. Но друзья не дали парню волю: герой был разоблачен и наказан.","95479297":"Военная драма Александра Столпера \"Возмездие\" 2-я серия","95479412":"В середине 1944 года гитлеровское руководство приняло план уничтожения городов Варшава, Братислава, Прага, Краков. Секретный план гитлеровцев стал известен Советскому командованию В район Кракова была направлена группа советских военных разведчиков, состоящих из майора «Вихря», его помощника Коли и радистки Ани. Группа получила задание связаться с…","95485154":"На целину, в казахские степи, прибывает московская группа комсомольцев и сразу же сталкивается с бюрократизмом и безалаберностью. Кто-то бежит из совхоза на более верные заработки, а кто-то просто не хочет работать. Но появляется новый энергичный директор — и начинается настоящая жизнь...","95490962":"История о трех друзьях, которые решают завоевать на конкурсе среди подростков право на космический полет.","95492058":"Старый потомственный рабочий, Егор Кузьмич, мастер своего дела и уважаемый на заводе человек, в один прекрасный день вдруг понимает, что обе его дочери не вполне счастливы: Ольга развелась с мужем, Варя полюбила недостойного мужчину… И решает Егор Кузьмич помочь своим девочкам наладить личную жизнь.","95497501":"Боевик Александра Аравина \"Решение об ликвидации\"","95503381":"О борьбе югославских партизан против немецко-фашистских захватчиков во время Второй мировой войны. Боснийский селянин Славко Бабич и не думал воевать. Но фашисты добрались до его дома, и Славко берется за оружие. Он создает партизанский отряд и ведет его на соединение с главными силами повстанцев, которыми руководит маршал Иосип Броз Тито. Их…","95522325":"Спасаясь от одиночества и скуки, пенсионерка Майя Дмитриевна снимается в массовке, организовывает женский клуб, встречается с подругами и каждый день начинает новую жизнь…","95522813":"Осенью 1921 года разгромленная в Крыму врангелевская армия находит прибежище в Болгарии. Белогвардейский полковник Сергей Егорьев живет здесь с сыном и дочерью. Его жену и младшую дочь, потерявшихся во время бегства в Севастополе, приютила семья большевика Дмитрия Шелопугина. Дмитрий направляется в Болгарию для агитационной работы среди русских солдат…","95525309":"Немецкие школьники подружились со сверстниками из России, приехавшими в немецкий город Котбус на слет пионеров стран Европы, Азии и Африки. А некоторое время спустя группа немецких школьников приезжает в Москву. Их сверстник Валера Степанов показывает им свой город...","95527145":"Драма Себастьяна Аларкона \"Ночь над Чили\"","95527886":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","95529692":"О подготовке и проведении экспедиции к Северному полюсу под руководством известного исследователя Севера моряка-гидрографа Георгия Яковлевича Седова, организованной им в 1912 год на частные пожертвования.","95531464":"В крупный промышленный город в составе труппы московского театра приезжает на гастроли известный актер Александр Васнецов. Это город его детства, здесь он вырос, здесь живет его племянник Алексей Юрьев - учитель литературы, буквально боготворящий дядю. Однако встреча двух родных, любящих друг друга людей приносит им только разочарование.","95534377":"Перед началом Великой Отечественной войны Вася Говорухин воспитал преданного друга - лихого коня Буяна. Тренер Белецкий сомневается в достоинствах Буяна, но начинается война, и Вася с Буяном демонстрируют чудеса ловкости и храбрости в партизанском отряде.","95535754":"Драма Владимира Петрова \"Без вины виноватые\"","95541855":"О подвигах героя Гражданской войны серба Олеко Дундича, сражавшегося в рядах первой конной армии.","95548567":"Гражданская война. Воспитательница детского дома везет хлеб голодающим детям. Ее случайные попутчики - чекист Горбач, матрос Саша и начальник станции Зайцев, которому в руки попали три слитка золота. А вокруг - красные, белые, бандиты…","95550033":"«Находка» — история по мальчика, который нашел чужой кошелек, но потерял свой ножик. Как ему поступить — вернуть ли чужое, чтобы найти свое? «Игрушечный директор» — о мальчике, выбирающем игрушку в магазине. «Какая-то девочка» — рассказ о девочке, пришедшей на спектакль «Хижина дяди Тома». «Штиль» — новелла о мальчишках из приморского городка, мечтающих…","95550605":"Новая серия Простоквашино — Почтовредитель на нашем канале.","95561737":"Из-за своей финансовой ошибки служащему сберкассы Диме Горину пришлось ехать на далекую сибирскую стройку, где он встретил совершенно незнакомую жизнь и девушку своей мечты…","95561984":"«Свинарка и пастух» -  чёрно-белый фильм 1941 года, музыкальная комедия Ивана Пырьева.\nЛейтмотив этой киноленты - песня «Друга я никогда не забуду, если с ним подружился в Москве» - стал дорог нескольким поколениям советских людей. Глаша Новикова (Марина Ладынина), свинарка из-под Вологды, и дагестанский пастух Мусаиб (Владимир Зельдин) встретились в…","95567885":"Драма Александра Столпера \"Живые и мертвые\" 1-я серия","95584059":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","95607308":"Пятиклассница Таня Нечаева по-детски влюблена в пионервожатого Петю. Он дает ей задание - найти первых пионеров, зачинателей этого движения. Таня самозабвенно приступает к выполнению поручения. Много радостей и огорчений приходится пережить девочке во время поисков. Впечатления, вынесенные из встреч с новыми интересными людьми, откладываются в душе…","95620920":"Нестареющий приключенческий фильм «Гардемарины, вперед!», снятый по роману Нины Соротокиной  «Трое из Навигацкой школы», предлагает вам погрузиться в дымку юношеской романтики вместе с гардемаринами и снова вспомнить, каким он был, век восемнадцатый... В основе сюжета — политические и любовные интриги русского двора времен Екатерины II.  Именно тогда в…","95624792":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95640419":"О приключениях авантюриста-обывателя Облапошкина, попавшего в необыкновенный город Дурова, заселенный зверями. Не в силах изменить своим привычкам, он и здесь старается извлечь для себя выгоду.","95645620":"❄️ Иногда, чтобы узнать что-то новое, достаточно просто посмотреть вокруг!","95648190":"Действие картины происходит в Древней Руси - в те времена, когда славянам, объединившимся в войско под предводительством Ратибора, сына Всеслава, удалось одержать первые победы над племенами кочевников.","95648811":"Экpанизация одной из pанних повестей А.П.Чехова \"Дpама на охоте\". Юная Оленька родилась и выросла в бедной семье, поэтому вынуждена выйти замуж за богатого, но нелюбимого человека, который, к тому же, гораздо старше ее. Но сердцу не прикажешь, и страстная любовь вдруг настигает девушку на выданье - вот только любящий ее человек не может смириться с тем,…","95649043":"У московских школьников Зоси и Гоши — любовь, но совсем не такая, какую обычно показывают советскому зрителю, особенно если он в возрасте главных героев. Зося не собирается убивать свое нерожденное дитя, а вот Гоша оказался не готов к принятию истинно мужского решения и оставляет свою девушку наедине с навалившимися совсем недетскими проблемами.","95657598":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","95661529":"Несколько новелл этого фильма расскажут об истории сложных взаимоотношений трудных детей и их родителей, и, может быть, помогут вам избежать уже совершенных кем-то ошибок.","95665408":"Борьба с космическими пиратами, захватывающее путешествие во времени, знакомство с девочкой из будущего Алисой Селезневой — вот к чему привел обычный поход за кефиром мальчика Колю из 6-го класса.","95674916":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","95676658":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95713400":"О блокадном Ленинграде, семилетнем Мишке Афанасьеве и его друзьях - брате Гене и сестренке Леночке, которые чаще всего оставались без присмотра родителей. Выступая с концертами в госпиталях, ребята общались с героями войны и конечно верили в победу.","95713467":"Детективно-эксцентрическая комедия о скромном служащем Семене Семеновиче Горбункове, который во время туристической поездки за рубеж попадает в центр контрабандистской операции – его принимают за связного и закатывают в гипс на руке драгоценности для переправки через границу. В итоге герой помогает милиции раскрыть преступление.","95714413":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","95718580":"Семен Брусничкин — целеустремленный деревенский парень. Он равнодушен к развлечениям, строго соблюдает режим, изучает языки и точные науки. В его жизни есть две цели — стать космонавтом и завоевать сердце бывшей одноклассницы Марины.","95718614":"Драма из двух серий Элема Климова «Агония». В роли Распутина — Алексей Петренко.","95721007":"Новая серия Простоквашино — Свидание на нашем канале.","95725995":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95727612":"Фильм снят по одноименной повести Б.Лавренёва.\nПо белым пескам Средней Азии движется, преследуемый белыми, умирая от жажды, отряд красноармейцев. На боевом счету у лучшего стрелка отряда Марютки сорок убитых белогвардейцев. В последнем бою по захвату каравана взят в плен белый поручик-аристократ Говоруха-Отрок. Он станет сорок первым...","95733699":"Начало 80-х, уральский металлургический завод. Профессиональный сварщик Федор Боярышев пытается доказать руководству завода, что новое оборудование необходимо заменить. Никто не хочет дорабатывать технику, поэтому ситуация в коллективе обостряется. Но страдает от этого ни в чем не повинный человек - конфликт ломает личную жизнь молодой девушки Вари,…","95738124":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","95745893":"«Своих боюсь, и чужих боюсь». Сильная драма о послевоенной деревне","95750249":"Герой фильма, недавно вышедший на пенсию, остается человеком энергичным и жизнелюбивым. И решил этот мужчина в полном расцвете сил, способный остановить трактор и спрыгнуть с балкона, доказать окружающим, что все еще впереди и что он, если захочет, сможет все, даже жениться...","95750271":"🏡 В Простоквашино всегда весело! На этот раз друзья устраивают кулинарную битву, варят варенье под строгим контролем Матроскина, ищут клад, спасаются от недосыпа из-за храпа Шарика и пробуют себя в новых ролях!","95753174":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","95757871":"Кинокомедия по одноименному роману И.Ильфа и Е.Петрова. Умирая, теща бывшего светского льва и предводителя дворянства, а ныне скромного делопроизводителя уездного ЗАГСа Ипполита Воробьянинова, открыла ему свою тайну: она спрятала фамильные драгоценности в одном из стульев гостиного гарнитура. Бриллиантовый угар вскружил голову Воробьянинова, и он ринулся…","95766417":"Красные колокола. Фильм первый \"Я видел рождение нового мира\". Вторая серия.","95767410":"Фильм представляет собой размышления, мысли человека, названного здесь Автором. Сам он не появляется воочию, звучит лишь его усталый голос. А на экране, словно в зеркале, проходят картины его прошлого. Сначала воспоминания кажутся разрозненными: любовь к матери, которую Автор не умеет выразить, пронзительное чувство к отцу, недовольство собой за…","95769807":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","95780365":"Вторая мировая война. Незадолго до Победы нацисты и их пособники пытались вывезти из Болгарии архивы, которые в будущем могли помочь расследовать дела о военных преступлениях. Совместными усилиями болгарских партизан и советских воинов архивы были спасены.","95782160":"«Ночной экипаж» - фильм режиссёра Бориса Токарева, снятый в 1987 году, криминальная драма. \nДрузья эпатируют публику, совершая один странный поступок за другим, балансируя на грани криминала. Развлечения приводят к трагедии. \nГерои фильма - студент ПТУ по прозвищу Петух, второгодник Балда и начитанный Малыш - в один из июльских вечеров затеяли драку. А…","95793654":"Лёгкая история о молодости, дружбе и любви, рассказанная со всей присущей кинематографу 60-х красотой.","95807709":"Новая серия Простоквашино — Рыцарь на нашем канале.","95807763":"Комедийный фильм Михаила Названова \"Хозяйка гостиницы\"","95808648":"Дальний Восток, 1921 год. Остатки белой армии с помощью Японии совершают переворот. Создается буферная республика под руководством Блюхера и Постышева. Большевики уходят в подполье.","95813987":"Фильм-катастрофа Александра Косарева \"Когда дрожит земля\".","95826097":"Роль д`Артаньяна в школьном спектакле готовит Шура Тычинкин, но внезапно роль отдают другому. Тогда Шура, чтобы убедить всех в своем таланте, надевает мексиканский костюм и выдает себя за собственного брата, приехавшего из Латинской Америки.","95831442":"По мотивам пьесы Александра Володина \"Пять вечеров\". 1950-е годы. Тамара и Александр встречаются после долгих лет разлуки. Александр не вернулся к ней после войны. Стыдясь признаться, что ничего не достиг в жизни, он снова уходит от нее. Сумеют ли герои вновь найти общий язык и быть искренними друг с другом?","95835871":"В ходе подготовки стратегического наступления наших войск в Прибалтике перед разведчиками лейтенанта Фомичёва поставлена непростая задача: захватить и удержать железнодорожный мост до подхода основных сил.","95838850":"Новая серия Простоквашино — Экспедиция на нашем канале.","95842104":"Дмитрий Гусев – ученый-ядерщик, который стоит на пороге грандиозного научного открытия. Но за успех надо платить, и порой цена слишком высока. Зато на самый главный вопрос – «Ты своей жизнью доволен?» – Гусев отвечает не задумываясь. Потому что либо все, либо ничего, а по-другому жить неинтересно...","95842767":"Драма Михаила Швейцер и Софьи Милкиной \"Время, вперед!\"","95854484":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","95866450":"Советская комедия Леонида Гайдая \"Спортлото-82\"","95871471":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","95871708":"По произведениям В.Астафьева «Звездопад», «Сашка Лебедев», «Ода русскому огороду». Фильм о любви, которая не могла существовать в условиях войны. Они встретились и полюбили друг друга в прифронтовом городе. Но шла война, которая диктовала свои законы и не оставлявляла места для любви. Да и мать девушки была против женитьбы: ведь если он погибнет, что…","95874073":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95880109":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","95883187":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","95889734":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","95901463":"Однажды, после дождичка в четверг, у царя Авдея родился первенец. В тот же день родила мальчика и ключница Варвара, а в капусте был обнаружен новорожденный подкидыш. Всех троих нарекли Иванами — и Авдей приказал растить хлопцев вместе. Однако ключница сделала по-своему: положила в царскую люльку своего Ивана, а двух других отдала разбойникам...","95902431":"Одним из тяжелых последствий войны явилась нехватка мужского населения, и, соответственно, трудная судьба простых тружениц-женщин. О трёх поколениях женщин — работниц мебельной фабрики — об их любви, о простых радостях и печалях.","95902999":"Во время германской оккупации белорусский учитель Алесь Мороз не бросает своих подопечных, воспитывая в них волю и мужество. Однажды ученики, ослушавшись своего учителя, решают отомстить за своих родителей. В результате неудачного покушения на фашистских прихвостней дети оказываются в плену.","95905339":"История о девочке Марине, которая все делала как попало и при этом говорила: «Сойдет и так!» На что ее мама отвечала: «Сойдетитак была злая волшебница и любимая ее поговорка была - не будь я злая волшебница Сойдетитак, если это вам так сойдет!» Вот что из этого вышло...","95907970":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95916558":"По одноименной повести Д.Григоровича. После смерти матери Петя остался круглым сиротой и был отдан в учение к цирковому силачу Беккеру, жестокому и несправедливому человеку. Для Пети потянулись дни горького унижения и изнуряющей работы. Однажды за кулисами цирка мальчик повстречал знаменитого клоуна Эдвардса. Талантливый артист, человек большого и…","95917652":"Преуспевающий молодой журналист едет в небольшой промышленный город с тем, чтобы разобраться в письменных жалобах некой Аникиной.","95923251":"Фильм восстановлен в 1968 г.\nОтреставрирован в 2020 г.","95923291":"Веселый и поучительный фильм про шестилетнего Глеба, нежелающего посещать детский сад. Выменяв у первоклассника школьную форму на перочинный нож, Глеб вместо друга 1 сентября пришел в школу…","95925193":"Было это давным-предавно. В стороне нашей светлой лесной жил Олень - Золотые рога. Малых, слабых всегда защищал, а вот зла никому не прощал… Но однажды в рассветном часу объявились злодеи в лесу.","95925819":"Новая серия Простоквашино — Овощной великан на нашем канале.","95945036":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","95951901":"Фильм-фантастика Алексея Сахарова и Эльдара Шенгелая \"Снежная сказка\"","95955538":"Новая серия Простоквашино — Сыворотка правды на нашем канале.","95956274":"Рано повзрослевшему Витьке живётся трудно: отец пьёт, мать в больнице, мальчик работает вместо неё дворником. Но у него есть настоящий друг Вовка.","95958286":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","95960100":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","95964033":"Фильм-концерт, посвященный 20-летию рок-ансамбля \"Машина времени\". В перерывах между музыкальными номерами бессменный руководитель \"Машины времени\" Андрей Макаревич и участник ансамбля Александр Кутиков рассказывают о своем творческом пути, делятся своими впечатлениями о том, что их объединяет, о своем отношении к рок-н-роллу и многом другом.","95967445":"😱 Готовы пощекотать себе нервы? В этом сборнике — зловещие тени, таинственные скрипы, неожиданные повороты и… Монсики, которые снова попали в переделку!","95968111":"Разведчик Михаил Тульев продолжает свою деятельность в стане врага. Вскоре ему предстоит узнать информацию о гибели отца, выйти на нацистского преступника и раскрыть планы о диверсионной акции западных спецслужб на территории СССР.","95971470":"О летчиках-испытателях и конструкторах, которые в первые послевоенные годы, рискуя жизнью, осваивали новую реактивную технику.","95978701":"Нависший над землей загадочный шар становится источником несчастий. После встречи с посредником этого шара люди становятся подвластны злой силе. Однако влияние посредника не распространяется на сумасшедших и детей. Сережа и Настя решают предотвратить катастрофу - и с помощью инженера Замятина спасают Землю от вторжения злого Разума...","95990191":"1820-е годы. Сын плотника Жюльен Сорель боготворит Наполеона и мечтает о славе. Благодаря способностям и образованию он оказывается в среде сначала провинциального, а затем и высшего дворянства, но жизнь сложилась не так, как ему хотелось бы.","95996486":"На широком поле строителями дороги была найдена могила солдата. Дорожники перенесли могилу и поставили на ней плиту и, казалось, выполнили свой долг. Но безымянная могила не давала покоя. И вот юному подсобному рабочему Сергею поручили выяснить имя погибшего солдата. И после долгих поисков Сергею удалось выяснить имена пяти солдат, вступивших здесь в…","96013925":"Новая серия Простоквашино — Ночные гости на нашем канале.","96018783":"Курсанты морских училищ отправились на учебном паруснике «Надежда» к берегам Австралии. Им предстояло впервые пересечь несколько морей, переплыть океан и принять участие в международной регате парусных судов. Большинство ребят первый раз вышли в море, и это плавание должно было определить, кто из них станет настоящим моряком, а кто должен будет покинуть…","96023240":"По мотивам одноименной повести Ш.Аджинджала. Абхазия. Начало 1921 года. После долгого отсутствия в родное село из России возвращается Алхас - крестьянин, солдат, большевик-подпольщик. Отважный горец может укротить любого коня, достойно поддержать беседу с мудрыми стариками. Именно ему предстоит подготовить односельчан к неотвратимо приближающемуся…","96027532":"Художественный трёхсерийный фильм по одноименному поэтико-драматическому циклу А. С. Пушкина. Исследование души, охваченной страстью, - вот что объединяет «Mаленькие трагедии» А. С. Пушкина и делает интересной каждую новую встречу с ними. В первую серию включены «Сцена из Фауста», «Египетские ночи» и «Моцарт и Сальери». Во второй серии - «Скупой рыцарь»,…","96027626":"Фильм о молодом коммунисте Василии Губанове, после гражданской войны прибывшем на строительство электростанции в Загору. Здесь ему приходится не только бороться с расхитителями, добывать стройматериалы, но и защищать свою любовь.","96041124":"Летчик Николай Ермолов прошел через все испытания Великой Отечественной войны: был подбит и горел в самолете, бил врага в одиночку в партизанском отряде, не раз настигала его пуля. Самые близкие друзья потеряли надежду на его возвращение с фронта. Но жена Лиза, несмотря на известие о гибели мужа, верит и надеется, что он жив и когда-нибудь войдет в дверь…","96041268":"Ежегодно летом ребята встречаются для того, чтобы уйти в очередное плавание на паруснике. Всем им очень повезло на верных и преданных друзей. Но семиклассник Кирилл остро ощущает отсутствие дружбы в своем классе.","96063837":"Музыкальная драма М.Мусоргского \"Борис Годунов\" в исполнении артистов Государственного академического Большого театра СССР. Сюжетная основа - одноименная трагедия Александра Пушкина. Юродивый обвиняет нового царя Бориса в убийстве малолетнего царевича Дмитрия. Начинается недолгое и трагическое царствование Бориса Годунова, а вместе с ним и Смутное время…","96075818":"По одноименной пьесе Константина Симонова.","96076945":"По одноименной пьесе А.П.Чехова. В имение Петра Сорина приезжают гости - его сестра Ирина Аркадина (актриса) со своим возлюбленным Борисом Тригориным, известным беллетристом. Сын Ирины, Константин Треплев, живет вместе с Сориным. Треплев, увлеченный литературой и театром, сочинил пьесу, которая вскоре будет поставлена в поместье его дяди. Главную роль в…","96077619":"Четверо школьников попадают в пещеру, бывшую во время Великой Отечественной войны фашистким складом оружия и документов. В результате подземных толчков юные герои неожиданно оказываются замурованными. В поисках выхода ребята проведут несколько дней…","96080248":"Во время Великой Отечественной войны комбат Павел Акимов полюбил военную переводчицу Анечку Белозерову, но обстоятельства военной жизни разлучили их. Акимов, не забывая об Анечке, героически сражался на Северном флоте и погиб в Норвегии, не дожив до Победы и рождения дочери.","96090592":"Новая серия Простоквашино — Как вырастить гения на нашем канале.","96092278":"Фильм о становлении молодежи, о формировании характеров, о вступлении в самостоятельную взрослую жизнь. Главный герой - Петр Горохов - никогда и ничего не делает наполовину. Ему чужды цинизм, вялость души, равнодушие. Решительный и страстный во всем, он снискал себе прозвище «Баламут».","96093855":"О первых послевоенных годах жизни провинциального южного городка. Ежедневно собираясь на пустыре, местные подростки в своих жестоких играх подчинялись самому сильному, имеющему при себе оружие.","96097751":"Люди, которые возводят линии электропередач и эксплуатируют их, сами называют себя «ЛЭПовцами». Работа у них далеко не сахар. Тут и высота, и высокое напряжение, и постоянно возникающие внештатные ситуации, постоянные разъезды, жизнь в полевых условиях. Сериал знакомит зрителей с бригадой ЛЭПовцев под руководством опытного бригадира Владимира Ковалёва и…","96105689":"В небольшом провинциальном городке живут рабочий по имени Евдоким и его жена — Евдокия. Своих детей у них нет, они воспитывают приемных.","96116877":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","96127363":"Историко-биографический фильм, посвященный знаменитому флотоводцу адмиралу Павлу Степановичу Нахимову.\n18 ноября 1853 года на Синопском рейде Нахимов одержал блистательную победу над турецкой эскадрой Османа-паши. Смелый, благородный, дальновидный. Нахимов был одним из немногих, кто предвидел трагедию Крымской войны. Он с удивительной энергией руководил…","96127710":"Второй фильм кинодилогии. (Первый — «Любовь земная»). На долю героев фильма «Любовь земная» выпадают новые испытания — идет Великая Отечественная война.","96135413":"🌿 В этом сборнике Зебра в клеточку с друзьями учит беречь природу, заботиться о ней и сохранять чистоту вокруг.","96136750":"По одноименной пьесе Л.Леонова. Врач Федор Таланов возвращается из заключения в оккупированный фашистами город. Федора подозревают в предательстве, близкие ему не верят. Отстоять свое честное имя Таланову предстоит ценой собственной жизни…","96140089":"Экранизация романа Алексея Толстого “Хождение по мукам”. Второй Фильм кинотрилогии. Первый Фильм “Сестры”, третий - “Хмурое утро”.","96147161":"Драма Никиты Михалкова \"Свой среди чужих, чужой среди своих\"","96149809":"Приключения, выпавшие на долю пионеров, оказавшихся во время войны на оккупированной немцами территории и начавших борьбу с врагами. Фильм снят по одноименному роману — трилогии Валентины Осеевой «Васек Трубачев и его товарищи».","96153701":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","96158762":"Приморский город. Обычная рабочая семья. Отец и мать озабочены лишь бытовыми проблемами и довольствуются непритязательными житейскими радостями. Дочь Вера, только что закончившая школу, проводит время на дискотеках, за бутылкой вина в подворотне и за болтовней с подружками. Важным событием в жизни Веры становится встреча со студентом Сергеем - он вырос в…","96159484":"Биографический сериал «Михайло Ломоносов» состоит из 9 серий:","96171663":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","96176039":"Пользуясь интеллектуальным превосходством, подросток Валя Успенский утонченно и безжалостно мстит окружающим за малые и большие обиды. В поле его интересов попадает и молодой учитель математики Игорь Александрович, ум и тактичность которого должным образом повлияют на парня.","96178200":"1953 год. Председателю колхоза «Новая жизнь» Самоварову, консерватору и перестраховщику, приходится не по душе молодой агроном-новатор Шуров. В разгар посевной кампании Самоваров запрещает Шурову сев пшеницы новым методом. Однако Шуров, видя всю пагубность распоряжения председателя, решает поступить по-своему. С помощью бригадира Алёши Пшеничкина,…","96178758":"«Борец и клоун» - советский цветной художественный фильм, снятый в 1957 году. Работу над фильмом начал режиссёр Константин Юдин. После его внезапной смерти во время съёмок картину закончил Борис Барнет.","96201179":"Июнь 1941 г. Война прервала давно задуманное путешествие московского юриста Бачея и его сына Пети в Одессу, памятную отцу по воспоминаниям детства, сыну — по рассказам отца. Посадив Петю на последний пароход, отправлявшийся из Одессы, Бачей ушел в армию, не думая скоро вновь увидеть родных и близких. Но судьба рассудила иначе. Отец и сын встретились в…","96203779":"По одноимённой повести Б. Бедного. На северные лесозаготовки приезжает Тося Кислицына — выпускница Симферопольского кулинарного училища, сирота, совсем девчонка, — умница, настоящий товарищ. На первых же танцах она отбривает местного кумира — лучшего бригадира Илью Ковригина, и начинается у них любовь-борьба, в лучших традициях советских лирических комедий.","96206842":"Последние бойцы на плацдарме. Приказ — держаться до последнего. Батальоны выполнили\nсвою задачу: они отвлекли противника, дали дивизии возможность наступать. Но какой ценой? Капитан Ермаков и оставшиеся в живых знают ответ. И полковник Гуляев знает.\nИ полковник Иверзев — тоже.","96209498":"Герои фильма — студенты педвуза, которые отправляются на практику далеко от стен родного дома. Им предстоит каждый день сдавать экзамены как перед педагогами, не первый год работающими в школе, так и перед ребятами — очень трудно будущему учителю завоевать авторитет.","96211625":"Художественный руководитель по восстановлению фильма - Сергей Юткевич.","96223811":"Знакомьтесь: Шурик. Просто Шурик — рыцарь, благородный сердцем и поступками. Шурик в два счета перевоспитает хулигана, защитит от расхищения склад и сдаст все экзамены! Потому что Шурик — самый любимый комедийный герой последних пятидесяти лет, каждый кадр похождений которого знает наизусть огромная страна!","96224176":"Герой фильма - художник-модельер Сергей - работает на текстильной фабрике провинциального городка. Будучи человеком творческим, он не может смириться с косностью представлений фабричного руководства о красивой и модной одежде для женщин. Сергей отваживается предложить свою коллекцию нарядов, но она не получает одобрения директора фабрики Лыхиной...","96232030":"Великая Отечественная война. Мать Митраши и Насти получила похоронку на мужа и в скором времени умерла. Дети осиротели. Вся деревня, как могла, помогала им выжить.","96238287":"Председатель райисполкома Голощапов, жестокий и беспринципный человек, узнает, что занимающего высокое служебное положение Выборнова должны отправить на пенсию. Больше заискивать и угодничать перед ним не нужно... Однако выясняется, что слухи об уходе на пенсию Выборнова ошибочны, и тогда Голощапов, опасаясь за собственную карьеру, решает организовать…","96245530":"Одна из самых любимых народом комедий про добряка заведующего детсадом, который как две капли похож на рецидивиста, сбежавшего из тюрьмы. Работники уголовного розыска решили воспользоваться этим сходством для розыска похищенных археологических ценностей.","96249865":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96261297":"Виктор Круглов, молодой футболист из провинциального городка, благодаря упорству и мужеству вошел в состав сильнейшей команды страны. И теперь начался новый, более ответственный, этап спортивной жизни юноши. Вместе с новыми товарищами по команде Виктор выигрывает свой первый трудный матч.","96263189":"Лето 1971 года было жарким и сухим. Это обстоятельство обеспечивало перевыполнение плана и сулило большие заработки геологоразведочной экспедиции Ивана Копырева, расположившейся в районе тунгусского поселка Ербогачен. Наткнувшись на слой мерзлоты, мастер Елфимов, вопреки противопожарной безопасности, приказал оттаивать мерзлоту кострами. Но сухой и…","96263885":"Драма Юлия Райзмана \"Кавалер золотой звезды\"","96266852":"Вася отправляется в лес, чтобы жечь уголь. На полянке он встречает Аленушку, которая пасет козленка. Но слуги Кащея Бессмертного похищают девушку прямо на глазах у Васи, и он вынужден отправиться на ее поиски.","96277178":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","96287098":"«Дворянское гнездо» - художественный фильм Андрея Кончаловского по мотивам одноименного романа И.С. Тургенева. В фильме отображена жизнь российского дворянства 40-х годов XIX века.","96292852":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","96297097":"Фильм по повести З. Тоболкина «Жил-был Кузьма». Паренек из сибирского села всю жизнь провел  среди природы, поэтому он добр и милосерден, чистый, непоколебимый и восприимчивый как к добру, так и к злу.  Малыш все видит и примечает - и, когда на семью сваливаются несчастья — у него случается нервный срыв, и тем самым он дает хороший урок нравственности…","96303482":"О буднях солдат воздушно-десантных частей СА.","96307124":"1918 год. Корабли военной миссии стран Антанты готовы начать вооруженную интервенцию против Страны Советов. Сталкиваясь с предательством и постоянными провокациями, в чрезвычайно сложных условиях здесь работает первый Совет рабочих, солдатских и крестьянских депутатов во главе с Константином Сухановым.","96309676":"Неудачник писатель-сказочник Афанасий Зяблик не может написать ни одной целой сказки. Всё, на что его хватает, — придумать им одни лишь названия. Сквозняком листы с названиями сказок разлетаются, и страница с названием «Куплю волшебную лампу» оказывается в настоящей сказке в руках у дочери Бабы Яги. Взяв с собой ту самую волшебную лампу, которой очень…","96328049":"Историко-революционная эпопея Александра Довженко \"Арсенал\"","96346154":"Редкий для тех времен совместный советско-французский проект. История раскрытия и предотвращения покушения нацистов на глав правительств СССР, США и Великобритании во время Тегеранской конференции 1943 года.","96352625":"Фильм-биография Сергея Эйзенштейна \"Иван Грозный\" 2-я серия","96356292":"Фильм-драма Дмитрия Васильева и Всеволода Пудовкина \"Жуковский\"","96357039":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","96364481":"После окончания войны Бачурин с наградами вернулся домой, где его ждала семья и огромный сад, который он любил с детства. Но вышел указ об обложении налогом фруктовых деревьев, находящихся в частных владениях. И Бачурин загубил сад, ошпарив яблони кипятком. Так он получил свой первый большой срок...","96367016":"Фильм поставлен по одноименному роману М.Ю. Лермонтова.","96368541":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","96370036":"После того как сын женился, Валентина почувствовала себя никому не нужной. Она уехала к родным в деревню, где встретила и полюбила сезонного рабочего Федора. Но кончилась пора отпусков, и к Федору приехала жена с дочерью…","96372369":"Драма Владимира Басова и Мстислава Корчагина \"Школа мужества\"","96391396":"Сентябрь 1943 года. Букринский плацдарм южнее Киева. Два батальона 85-го стрелкового полка получают приказ: форсировать Днепр, прорваться на немецкий берег и завязать бой.\nИх задача — отвлечь на себя силы противника, чтобы дивизия смогла ударить по\nстратегически важному городу Днепров. Основные соединения обещают огневую поддержку.\nКапитан Ермаков ведёт…","96399778":"Невероятные приключения девочки Маши, которая, заблудившись в лесу, встретила героев любимых сказок.","96404121":"Шхуна «Испаньола» бороздит морские просторы в поисках острова, на котором спрятаны легендарные сокровища пиратского капитана Флинта. На корабле зреет заговор. Разбойники во главе с одноногим Джоном Сильвером, кажется, близки к цели.","96405479":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","96405781":"В основе сюжета кинодилогии - исследование сложных судеб коммунистов-антифашистов разных национальностей. Фильм основан на биографиях реальных людей, чья жизнь вобрала в себя самые драматические этапы истории 30-50-х годов XX века.","96422764":"Двухсерийная экранизация одноимённой повести Л. Н. Толстого.","96423288":"Документально-постановочный фильм о спорте. Действие фильма происходит на стадионах Москвы, Филадельфии, Стокгольма и Мехико, на стадионах будущего и далекого прошлого. Используя документальный материал реальных спортивных состязаний и монтируя его с развернутыми новеллами в духе пантомимы и балета, авторы фильма показывают историю развития спорта, его…","96424780":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96428430":"Школьник Кира имеет только один недостаток — он носит очки. Поэтому, когда мальчик встречает свою одноклассницу Айну, прячет их в карман и на ее лукавый вопрос всякий раз утверждает, что забыл очки дома. А между тем мама Киры считает, что его недостаток лишь в том, что он всегда говорит то, что думает. Впрочем, их точки зрения не совсем расходятся.…","96429582":"Фильм о нелегкой судьбе человека, прошедшего через войну, ужас гитлеровского и сталинского лагерей, но сохранившего силу духа, порядочность и чистоту. Он живет в одном городе со своей семьей, но вынужден скрываться, боясь навредить родным.","96438390":"Под Новый год Женя Лукашин и его друзья по традиции идут в баню. Они выпивают и по ошибке отправляют Женю в аэропорт, он летит в Ленинград и проводит новогоднюю ночь в чужой квартире с чужой невестой. Но в результате этих несуразиц герой обретает большую любовь.","96439558":"🚂 Поездка на электричке идёт не по плану, дома разгорается настоящая битва за пульт, Печкин пытается устроить идеальное свидание, а Дядя Фёдор учится справляться со страхом выступлений…","96441235":"Исторический фильм Михаила Калатозова \"Вихри враждебные\"","96443386":"Время действия – с 1939 по 1953 годы. Пора жесткой тирании, когда погибли миллионы безвинно репрессированных. Но были и другие – особая категория приближенных к вождю людей, так называемый «ближний круг». Именно туда забрасывает судьба героя фильма, киномеханика Саньшина – доброго, восторженно-простодушного и слепо обожающего «вождя народов»…","96448048":"О создании в Петрограде первой рабочей молодежной организации. В основе сюжета - судьба Тани Огневой, в образе которой отражены черты Лизы Пылаевой (1898-1926), первого председателя Социалистического союза Молодежи.","96454266":"Третий фильм кинотрилогии («Сестры», «Восемнадцатый год», \"Хмурое утро\") по роману А.Н.Толстого \"Хождение по мукам\". Гражданская война перевернула жизнь всех героев киноповествования. Обороняя Царицын, красный командир Телегин тяжело ранен. В госпитале он встречает Дашу. После его выздоровления молодые супруги вместе отправляются в Красную армию. Тем…","96456115":"Драма русских провинциалов, считающих, что жизнь их не состоялась, растрачена понапрасну. Для дяди Вани ощущение усугубляется неразделенной любовью к женщине, которую судьба на короткое время забросила в захолустное поместье, где герой и его племянница живут и работают, не покладая рук и едва сводя концы с концами...","96460819":"Бессмертный роман Михаила Шолохова, отмеченный Нобелевской премией и вошедший в число наиболее ярких произведений мировой литературы, рассказывает о трагической ситуации, сложившейся в России в начале ХХ века, о сломанных Первой мировой войной и революцией судьбах людей, о крушении устоев и идеалов донского казачества, о личной трагедии главного героя -…","96466735":"Всю свою жизнь герой фильма любил одну женщину. Но она замужем, мать взрослых детей, бабушка. С ее замужеством он смирился и был все эти годы преданным другом. Пройдет время - и однажды в новогодний вечер она постучит в его дверь…","96471673":"Промышляющий врачеванием предприимчивый юноша, стремясь завоевать расположение своей возлюбленной, клянется вылечить ее матушку от тяжкой болезни.","96473690":"В середине 1944 года гитлеровское руководство приняло план уничтожения городов Варшава, Братислава, Прага, Краков. Секретный план гитлеровцев стал известен Советскому командованию В район Кракова была направлена группа советских военных разведчиков, состоящих из майора «Вихря», его помощника Коли и радистки Ани. Группа получила задание связаться с…","96474988":"Мечта школьника Саши Воробьева - стать знаменитым хоккеистом. Но в спортивную школу его не берут - слабо подготовлен. И Саша начинает упорно работать над собой.","96475789":"Комедия рассказывает об одном дне страхового агента Виссариона Булкина. Виссарион выполняет свою работу максимально нестандартно: он уговаривает бригаду рабочих взять шефство над детским домом и платить за сирот страховые взносы, страхует восьмидесятилетнюю старушку и т.д. Но когда дело касается его личных интересов, молодой человек робок и застентив.…","96478549":"Фильм-сказка Александра Птушко \"Илья Муромец\"","96484108":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96484165":"Группа студентов техникума из-за прогулов осталась без зачета по физкультуре. Чтобы избежать неприятностей, они придумывают розыгрыш: одна из «пострадавших» должна объясниться учителю в любви, растрогать его и получить зачет для себя и своих друзей…","96487250":"«В квадрате 45» - шпионский фильм о летчиках и парашютистах приграничной полосы, охраняющих леса от пожаров и прочих стихийных бедствий. В фильме показаны переживания новичка-пожарника  Волгина, который на протяжении всего фильма борется со своей нерешительностью и пытается влиться в коллектив.","96490256":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","96491897":"Смешная и грустная история о сантехнике ЖЭКа Афанасии Борщове, которого все зовут просто Афоня. Среди собутыльников и случайных подруг скудеет его душа. Жить бы Афоне и дальше так, но встретилась на его пути трогательная девушка Катя. Чистая и самоотверженная любовь Кати, считающей его не совсем потерянным человеком, возвращает Афоне веру в себя, и он…","96496887":"По мотивам одноименного детектива Агаты Кристи. Знаменитый сыщик Эркюль Пуаро, собравшись было уйти на покой, оказывается вовлеченным в расследование таинственных обстоятельств, связанных с неоднократными попытками покушения на жизнь хозяйки замка Эндхауз - очаровательной Ник Бакли...","96501232":"Дальневосточная тайга. В поселок, где работает научная экспедиция, проникает диверсант Воробьев под именем убитого им зверолова Майбороды. Он хочет помешать открытию вакцины против жестоких таежных заболеваний…","96501803":"Знаменитая комедия Эльдара Рязанова \"Зигзаг удачи\" в FULL HD.\nМолодой фотограф Володя Орешников выигрывает 10 000 рублей. Огромные деньги по советским временам. Товарищи по работе, не долго думая, организовывают общественный суд. Дело в том, что 20 рублей на покупку облигации Орешников тайком взял из кассы взаимопомощи, председателем которой он был.","96504195":"Потерявший во время войны жену, Кузьма Кузьмич Иорданов начал пить и совершенно опустился. Но однажды, случайно узнав о девочке, потерявшей на войне родителей, Иорданов решил стать ей отцом. Оставив Москву, он отправляется на встречу с будущей дочерью...","96515878":"Историко-революционная эпопея Сергея Эйзенштейна \"Броненосец \"Потемкин\"\"\nОзвучен в 1930 г., повторно озвучен в 1950 г., восстановлен в 1976 г.","96519073":"Коля Филатов попадает с тяжелым заболеванием в санаторий, где ему предстоит неподвижно пролежать долгие месяцы. Коля берет себя в руки и не скисает. В палате много веселья и в дружном коллективе каждый день происходит непредсказуемое событие. Но мужества мальчику хватает не надолго. Почувствовав себя лучше, герой бежит из санатория...","96526618":"Политический памфлет. Комитет 19-ти, один из рабочих органов ООН, устав от бесплодных дискуссий, направляет в Африку экспедицию из шести человек во главе с советским профессором Смоленцевым, чтобы на месте изучить вспышку неизвестной эпидемии. Члены комиссии обнаруживают центр, где неофашисты производят бактериологическое оружие и испытывают его на…","96534777":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","96548259":"Однажды город веселых тружеников захватили чужеземцы и поработили его мирных жителей. Но это несчастье было недолгим. Дух свободы гулял по городу и пробуждал в угнетенных гордость. Главным вольнодумцем был городской дворник. Горбатый балагур меньше всего вызывал опасений у городских властей. Когда труженики были готовы сражаться за свободу, им на помощь…","96549611":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96552212":"Счастливо завершается круиз молодоженов по Черному морю. Впереди — Москва, интересная работа и уют семейной жизни. Но трагическая случайность рушит надежды Веденеевых — Виктора обвиняют в преступлении. Начинается следствие…","96591888":"Музыкальная комедия по одноименной повести А. Некрасова. Сев писать сочинение на тему «Как я провел лето», Вася Лопотухин вспомнил своего любимого героя капитана Врунгеля, представил себя рядом с ним внутри Бермудского треугольника. И не заметил, как вступил в смертельную схватку с гангстерами и штормом...","96595883":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","96603699":"Новая серия Простоквашино — Поход на нашем канале.","96609338":"Кинокомедия Андрея Фролова \"Гость с Кубани\"","96618403":"Картина посвящена судьбе Людмилы Михайловны Кусаковой — художнику-постановщику киностудии  Мосфильм, создавшему костюмы и декорации для культовых советских кинокартин «Анна Каренина», «Гранатовый браслет», «Айболит 66», «Обыкновенное чудо», «Покровские ворота», \"Город Зеро\", \"Цареубийца\" и др.","96619312":"Писатель Павел Снегирев приезжает в село, где во время войны был детдом, в котором прошло его детство, и встречает старого друга Клима Авилова.","96625063":"По вызову своего жениха, Светлана поехала в захолустный городок, где на самой окраине стоял двухэтажный дом «на семи ветрах». Но началась война, Игорь не встретил Светлану, а она решила остаться ждать его и конца войны.","96627664":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","96628405":"В конце XVII века Россия терпела убытки в торговле, потому что не имела выхода к морю. Юный российский самодержец Петр I начинает строительство флота. Тем временем, среди бояр зреет недовольство молодым монархом.","96629879":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96639332":"Комедия Маргариты Микаэлян \"Путешествие мсье Перришона\"","96642081":"Документальный фильм о Московских Олимпийских играх. В картине показаны напряженные спортивные поединки, рекорды чемпионов, красочные церемонии открытия и закрытия Олимпиады.","96643487":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","96651214":"В большой оленьей семье родился олененок Бемби. С первого дня Мама учит его понимать таинственный и загадочный мир леса. Жизнь красива и удивительна — так думает Бемби. Но вскоре погибает его мать и олененок впервые начинает думать о существующем зле…","96655516":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","96660726":"Во время гастролей советского цирка в Японии маленький уличный музыкант Кэн знакомится с клоуном Юрием Никулиным. Узнав, что его больной отец находится на лечении в Советском Союзе, Кэн отправляется на его поиски. Дружба великого клоуна и мальчика продолжается уже в Москве.","96670436":"Наташа, влюбившись в Сергея, бросает учебу в пединституте и едет за ним на стройку. Успехи на работе делают Сергея все более самоуверенным и грубым, а она все больше чувствует себя одинокой. Наташа бросает Сергея и возвращается на учебу. Она становится учителем, но мысли о Сергее по прежнему не покидают ее…","96675396":"Когда в Трубинске не осталось ни одной школы, не пострадавшей от изобретений фантазера Сергея Берендеева, родители перевели непутевого сына в ПТУ. Но парень не сник, а, получив доступ к хорошей технике и полную самостоятельность, стал настоящим изобретателем.","96678864":"Сложные, противоречивые взаимоотношения между двумя совершенно разными людьми — начальником уголовного розыска и бывшим вором-рецидивистом — казалось, заходят в тупик. Но критическая ситуация заставляет бывшего уголовника переступить порог недоверия и неприязни.","96683601":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","96708190":"По мотивам повести Валентина Распутина «Прощание с Матёрой». Сибирская деревня Матёра веками стояла на острове, окруженном водами реки Ангара. В связи со строительством ГЭС остров должен быть затоплен. Всех жителей деревни переселяют в новый поселок городского типа. Для старшего поколения расставание с Матерой трагично. Откладывая отъезд со дня на день,…","96709775":"Новая серия Простоквашино — Дискотека века на нашем канале.","96712684":"В центре сюжета картины путешествие в Южную Америку польского школьника Янека и его попутчицы, русской девочки Тани. Самолет, на котором летели ребята, оказался захвачен бандой наркоторговцев во главе с бывшим нацистским преступником.","96723991":"Неразлучные друзья-шестиклассники Саша, Аня и Юра ничего не скрывают друг от друга. Но из-за неугомонного Юры Пузырева сокровенная тайна толстушки Ани, которая влюбилась в учителя литературы, становится всем известна. Так в кругу друзей назрела первая серьезная размолвка...","96725463":"В маленьком провинциальном городке в студенческом общежитии выступил фокусник Виктор Михайлович Кукушкин. Его фокусы не отличались сложностью и не произвели большого впечатления на публику. Но именно этот вечер послужил началом дружбы между студентами и фокусником - добрым, отзывчивым человеком с чистым сердцем.","96726184":"После армии Женька Кулик пришел работать в милицию. Занимаясь бытовыми делами и мелкими кражами, он мечтал ловить настоящих преступников. Его даже за это «сыщиком» прозвали. И вот однажды Женькина мечта сбылась - лицом к лицу он столкнулся с матерым бандитом...","96727181":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","96729014":"В родное село возвращается из мест «не столь отдаленных» лихой тракторист Матвей Морозов. И вспоминается ему история его женитьбы, его роковой любви, несостоявшейся измены и совершенного сгоряча «преступления», в котором он нисколько не раскаивается. Первый парень на деревне, Матвей Морозов был настоящей головной болью для председателя колхоза. Правда,…","96730639":"🎵 Улыбка сама появляется на лице, когда звучат весёлые песни из любимых мультфильмов!","96735634":"В жизни шестилетней Ани Ивановой происходит большое событие - она идет в первый класс. Трудно маленькому человеку все сразу понять, отличить плохое от хорошего. Подражая бойким подружкам, Аня невзначай обижает своего друга Сережу и школьную няню тетю Клаву. Но рядом с девочкой - родители, друзья, учительница, которые всегда помогут разобраться в плохом и…","96740820":"Шарик в очередной раз грезит космосом. Увидев интервью с настоящим командиром отряда космонавтов, герой узнает о новом наборе и загорается идеей испытать себя. Шарик решает построить собственную космическую станцию прямо на чердаке дома, но Матроскин совсем не рад такой авантюре и пускается на всевозможные хитрости, чтобы выманить друга обратно домой.…","96745910":"Тяжело знать будущее. Еще труднее чувствовать его неизбежность. Он сборщик налогов. По - русски - Мытарь. Он обладает необъяснимым сверхъестественным даром предвидеть будущее.","96759015":"Четыре истории о коротком пребывании разных людей в столице.","96761961":"Студент Шурик приезжает в одну из маленьких горных республик, чтобы изучать обычаи, обряды и фольклор горцев. Он знакомится с девушкой Ниной, которую сватают за председателя местного райкомхоза Саахова. Предвидя её несогласие, дядя Нины – Джабраил – с помощью известных проходимцев Труса, Балбеса и Бывалого устраивает похищение девушки. Множество…","96769273":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96771625":"О мальчике, которого отец — капитан судна речного флота — взял в интересное путешествие по Енисею. О том, как сын, поначалу восхищавшийся лишь романтической стороной отцовской профессии, постепенно начинает понимать истинный смысл и значение труда.","96784780":"По одноименной повести Н.Чуковского. 1942 год. Прифронтовой черноморский город. Советские моряки пытаются обнаружить подводную лодку, которая таинственно исчезает после каждой атаки…","96786355":"Новая серия Простоквашино — Неудобный гость на нашем канале.","96786574":"Новая серия Простоквашино — Недолетные птицы на нашем канале.","96787278":"Любе снится сон, что она — дочь шахматного короля — становится жертвой коварного заговора. Её похищает колдунья, а на поиски девочки отправляется сын мельника Ваня и его друг волшебный кот.","96787624":"Пятнадцатилетний Виктор проводит летние каникулы с приятелями. Развлечения подростков далеко небезобидны. Познакомившись с милиционером Борисом Плетневым, юноша начинает тяготиться каникулами и мечтать о ПТУ…","96792265":"В центре фильма — две жизни, две судьбы. Простой малограмотный солдат царской армии Востриков за годы Советской власти вырос в преданного борца революции, стал генералом Советской Армии, всеми уважаемым. А гвардейский офицер, блестящий князь Нащекин, боровшийся против Советской власти, эмигрировал из родной страны и в конце концов стал лакеем в портовом…","96800911":"Опытный разведчик, сын русского эмигранта графа Тульева, должен добыть для западных спецслужб сведения о разработках в советской атомной промышленности.","96800949":"По одноименному рассказу В. Распутина. Послевоенные годы. Одиннадцатилетнего Володю мать отправляет из родной деревни в райцентр на учебу. Изредка она присылает сыну посылки с картошкой. Молодая учительница французского языка Лидия Михайловна замечает, что мальчик недоедает. Она пытается накормить школьника, но гордый Володя отказывается от еды. И тогда…","96806819":"Маша Барашкина обладает необыкновенными организаторскими способностями. Она помогла открыть детскую больницу, стадион, ателье. А теперь Барашкина должна возглавить комбинат бытового обслуживания «Всё для Вас».","96810341":"Петр Королев, мастер спорта и будущий инженер-металлург, благодаря своей настойчивости и силе воли завоевал право участвовать в международных соревнованиях по легкой атлетике.","96814789":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","96818627":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96824048":"Окончилась война. В мирную Москву возвращаются фронтовые друзья: Антонина, Федор и Алексей. Теперь им предстоит вновь привыкать к обычной жизни - со своими радостями и горестями, победами и поражениями. Это история о поисках и обретении настоящего человеческого счастья - совсем не в том, в чем искал.","96826102":"В один из степных районов Казахстана прибывает отряд молодых энтузиастов осваивать целину. Суровые морозы, потоки весенней грязи, изнуряющая работа и неустроенный быт усложняют и без того трудную жизнь прибывших. Но это не мешает развиваться трогательному роману секретаря комсомольской организации и трактористки Анны…","96832958":"Фильм-спектакль МХАТа по одноименной пьесе Р.Шеридана. Конец XVIII века. Нигде не умеют так ловко и подло плести интриги, как в салоне леди Снируэл. Бездумно и доверчиво бросается в эту соблазнительную светскую жизнь молодая леди Тизл, глубоко огорчая этим своего простодушного мужа. Теперь всех ждет серьезное испытание, ведь в хитросплетениях интриг,…","96842712":"На Михаила Тульева вновь совершается покушение. Тем временем на территории СССР действует резидент и наёмный убийца Брокман, обезвредить которого становится главной задачей советских контрразведчиков.","96843460":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","96844718":"Трогательная лирическая киноповесть о судьбе собаки, теряющей любимого хозяина, об отношении людей к «братьям меньшим», которое как рентгеном просвечивает души, выявляя в одних низость и мелочную подлость, а в других - благородство, способность сострадать и любить…","96847858":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","96850203":"Погрузитесь в атмосферу хрущевской «оттепели» с легендарной лирической комедией Эльдара Рязанова. Теперь классика доступна в качестве 4K!","96858802":"Драма Андрея Михалкова-Кончаловского \"Сибириада\"","96863762":"Геннадий Фетисов - талантливый столичный pежиссеp, приезжает работать в провинциальный театp. Репетируя чеховскую \"Чайку\", он, сам того не замечая, перестает быть разборчивым в методах, он груб и жесток с актерами. После долгожданной премьеры приходит желаемый успех. Но оправдала ли цель средства?","96863767":"Новая серия Простоквашино — Сыр на нашем канале.","96871583":"По одноимённой пьесе Михаила Булгакова. В основе сюжета - переломный момент истории России - революция и Гражданская война, раз и навсегда изменившим жизнь русской интеллигенции.","96874629":"Фильм, действие которого начинается в первые, самые страшные дни Великой Отечественной войны. Это первая лента киноконцерна «Мосфильм», рассказывающая о беспримерном мужестве и героизме защитников Брестской крепости.","96882910":"Фильм-биография Сергея Эйзенштейна \"Иван Грозный\" 1-я серия","96885716":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96889764":"Сотрудники Московского уголовного розыска — полковник Алексей Павлович Садчиков, майор Владислав Николаевич Костенко и старший лейтенант Валентин Росляков расследуют дерзкие разбойные нападения, совершаемые группой преступников в тёмных очках.","96897118":"Драма Аждера Ибрагимова \"Любовь моя, печаль моя\"","96899535":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","96908098":"Продолжение фильма «Великие голодранцы» по дилогии Филиппа Наседкина. Пламенный комсомолец, сын батрака Филипп Касаткин приезжает в деревню Глуховка по направлению райкома комсомола. Его миссия – убедить местных крестьян в преимуществах колхозного строя, и ему это удается. Энергичный молодой человек привлекает на свою сторону даже самых упeртых…","96912267":"Комедия о модных веяниях в воспитании детей. Родители шестилетнего Павлика пытаются сделать из него эрудита: они постоянно заставляют мальчика много читать, учиться и добиваться успехов. А малышу хочется побегать, поиграть, быть просто ребенком! И вот однажды Павлик приезжает погостить к своей бабушке в деревню...","96912444":"Нависший над землей загадочный шар становится источником несчастий. После встречи с посредником этого шара люди становятся подвластны злой силе. Однако влияние посредника не распространяется на сумасшедших и детей. Сережа и Настя решают предотвратить катастрофу - и с помощью инженера Замятина спасают Землю от вторжения злого Разума...","96912707":"Лето 1917 года. По совету партийных товарищей В.И. Ленин переселяется из Петрограда туда, где его вряд ли будут искать. На ближайшие недели шалаш в Разливе станет скромным пристанищем для вождя мирового пролетариата и его соратника Григория Зиновьева.","96918839":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","96920746":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96927772":"Москва пятидесятых годов. В общежитии живут три подруги. Их судьбы складываются именно так, как предполагает характер каждой из девушек. Антонина вышла замуж, растит детей, любит мужа, часто ездит на дачу. Людмиле Москва представляется лотереей, в которой она должна выиграть свое особенное счастье. Катерина же одна растила дочь, закончила институт,…","96933730":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","96935378":"1918 год. Из Петрограда в Сибирь отправляется первая в СССР экспедиция, разыскивающая золотые месторождения. Сначала в ее составе всего два человека, красный комиссар и профессор. Вскоре у них появляются спутники из местных жителей. Кто-то действительно хочет помочь, а кое-кто просто желает за чужой счет поживиться... Ради наживы злоумышленники не…","96944302":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","96947106":"Фильм рассказывает об увлекательных путешествиях замечательного русского ученого и писателя В.К.Арсеньева. В центре повествования образ таежного охотника Дерсу Узала - мудрого, доброго и отважного человека, связанного с Арсеньевым искренней дружбой.","96948880":"События развиваются в XV веке. Тверской купец Афанасий Никитин отправляется в опасное морское путешествие в Индию. В результате ему удается проложить торговый путь из Европы в эту далекую и загадочную страну. Историко-биографический фильм, снятый по путевым заметкам русского путешественника и первооткрывателя Афанасия Никитина. Его сочинение «Хождение за…","96949341":"Нужда приводит деревенского парня на завод, а участие в бунте - в тюрьму. Суровая школа тюрьмы и окопной жизни, общение с революционерами-большевиками открывают глаза бывшему крестьянину - и он в первых рядах солдат и рабочих идёт на штурм Зимнего дворца.","96955185":"Мелодрама Наума Ардашникова \"Пришла и говорю\"","96957075":"По мотивам произведений Михаила Булгакова «Бег», «Белая гвардия» и «Черное море». Фильм повествует о бегстве из России в конце гражданской войны русских людей: военных, дворян, интеллигенции. Трагедия боевого генерала Хлудова, надорвавшего душу собственной жестокостью; история казачьего генерала Черноты, превратившегося на чужбине в нищего; личная драма…","96963714":"Кинокомедия Валерия Рубинчика \"Комедия о Лисистрате\"","96965652":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","96967328":"Женя был принят в компанию сверстников, о которой давно мечтал. Однажды на рыбалке он в шутку спрятал надувную лодку. Друзья избили ни в чем не повинного мальчика. Случившееся потрясло Женю — и он решил отказаться от этой дружбы…","96972306":"1919 год. Приморский городок, занятый белогвардейцами. Готовится суд над революционеркой Антониной Чумак. Чтобы спасти Антонину, в город независимо друг от друга пробираются матрос Кусков, казак Дмитрий Чумак и карточный шулер Федор Чумак. Первый убежден в том, что Антонина его любимая, а братья Чумак думают, что это их сестра. Объединенные общей целью,…","96972760":"Однажды доктора Сперанский и Никулин совершили выдающееся научное открытие: они обнаружили бациллу равнодушия и невежественности. Чтобы как можно подробнее описать ее действие, один из них самоотверженно прививает ее себе. И - тотчас становится невыносим для окружающих, «заболевая» равнодушием и злобностью...","96985632":"По одноимённой пьесе Михаила Булгакова. В основе сюжета - переломный момент истории России - революция и Гражданская война, раз и навсегда изменившим жизнь русской интеллигенции.","96990545":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","96990732":"Музыкальная мелодрама о судьбе эстрадной певицы.  В главных ролях - молодая советская певица Виктория Свободина (София Ротару) с известной в узких кругах молодежной рок-группой (Машина времени). Первая часть действия разворачивается  в Москве, где рассказывается о тяжелой болезни популярной эстрадной певицы. Её покидают друзья-музыканты, а главное -  ей…","96991198":"Приключения девочки Яны из Чехословакии, приехавшей с родителями и щенком Маркизом к своим московским друзьям.","96992341":"Философская сказка в фольклорной традиции. Крестьянин-бедняк Хмырь идет искать по свету счастье. Находит кошель с деньгами, покупает лошадь и осенью собирает большой урожай. Но кулак, помещик и поп отнимают у него все. Полицейские власти приказывают его выпороть и отправляют на войну.","96995998":"Толя Клюквин отправляется в гости к своему другу. Неожиданно дорогу ему перебегает черная кошка. Испугавшись, мальчик поворачивает в другую сторону. Вот тут-то и подстерегают его опасности и неприятности.","97004951":"Новая серия Простоквашино — Папа, не горюй! на нашем канале.","97012775":"Из деревенского музея украли самые ценные экспонаты, к великому сожалению его директора и реставратора, художника Бережкова, приехавшего вместе с женой из города. О преступнике известно, что это мужчина высокого роста и с большим размером обуви.","97032040":"Лирическая комедия о молодом обаятельном Лешке Игнатове, человеке с беспокойным характером, который ищет свое место в жизни. Название картины определяет главное в характере молодого человека: Алексей чувствует личную ответственность за все вокруг. Мечта у него - найти дело, \"чтобы проверяло человека на излом\". И однажды он находит его...","97036117":"Пришедший на авиационный завод молодой инженер Дмитрий Жерехов пытается доказать директору, что необходимо переходить на новые методы организации производства. Его поддерживает и опытный испытатель Алексей Седых, и инженер-испытатель Людмила Руднева. Дмитрий нравится Людмиле, но его жесткость и рационализм усложняют их отношения...","97041119":"Комедия Татьяны Лукашевич \"Учитель танцев\"","97044736":"Художественно-публицистический музыкальный фильм для детей. О том, что детей из разных стран, говорящих на разных языках, может объединять язык музыки, понятный всем людям на Земле без перевода.","97044772":"Москва, 1941 год. Борис и Вероника любят друг друга и строят планы на будущее. Но война разрушает всё. Борис уходит на фронт добровольцем, не успев попрощаться с любимой. Вероника остаётся одна — ждать, надеяться, держаться. Не всем это удаётся.","97045742":"Детектив Константина Юдина \"Шведская спичка\"","97064207":"Бедный студент Родион Раскольников идет на преступление, за которым неизбежно следуют муки совести: его душа, отягощенная грехом убийства, мечется между верой и безверием, надеждой и отчаянием. Расследование сыщика Порфирия Петровича в конечном итоге выводит следствие на Раскольникова, но еще до знакомства со следователем Родион встречает настоящую…","97071591":"Выпускник педагогического института — учитель литературы Вячеслав Кузьмин — становится классным руководителем и лучшим другом ребят десятого, выпускного, класса…","97071631":"Жизнь ставит перед старшеклассниками первые взрослые вопросы. Прощаясь с детством, они начинают по-новому относиться к дружбе и любви, к таланту и соперничеству. Теперь подростки сами решают, каким путем идти к своей мечте…","97072631":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","97072970":"Драма Сергея Тарасова \"Антарктическая повесть\" 3-я серия","97077851":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97081298":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","97088213":"Исторический фильм Сергея Бондарчука \"Война и мир\". Фильм 3-й \"1812 год\"","97118907":"Военная драма Сергея Колосова \"Вызываем огонь на себя\"","97126846":"Фильм состоит из трех новелл по рассказам Василия Шукшина - «Братка», «Роковой выстрел», «Думы». Герои - чудаки, «странные люди», живущие в деревне, не всегда удобные для окружающих, но обладающие богатым внутренним миром.","97136946":"Фильм рассказывает о революционной деятельности моряков Балтийского флота в годы, предшествующие первой мировой войне. Моряки крейсера «Елизавета» во главе с мичманом Паниным спасли приговоренных к смертной казни революционеров и помогли им бежать за границу.","97138138":"Экранизация повести А.П. Чехова — одна из лучших в истории советского кино. Режиссёр Сергей Бондарчук создал удивительно поэтичную картину о взрослении, дороге и человеческих судьбах.","97138847":"Ильмар едет с друзьями в пионерский лагерь на теплоходе «Экватор» и становится случайным свидетелем того, как иностранный пассажир - «коммерсант» мистер Пипп - сбрасывает в море радиобуй. Заметив мальчика, Пипп сбрасывает его в море. Ильмара спасают, а вражеского агента берут с поличным.","97138874":"Во время лекций по литературе фантазия студента Саши Мухина переносит его, то в пушкинскую эпоху, то - во времена восстаний Спартака, то он представляет себя современником Галилея... Его фантазия неукротима, гораздо скромнее - успехи в учебе…","97144100":"Новая серия Простоквашино —Домовой на нашем канале.","97153023":"Бывший ученик школы врывается на урок и на глазах удивлённых однокласников дает пощёчину девочке. Директриса вызывает милицию. Инспектор по делам несовершеннолетних Лапиков пытается разобраться во всём, избегая неправильных действий и несправедливых обвинений. Однако директрисе все ясно — и её раздражает медлительность представителей органов правопорядка...","97157150":"Исторический фильм Сергея Бондарчука \"Война и мир\". Фильм 2-й \"Наташа Ростова\"","97182978":"По мотивам произведений Владимира Гиляровского и повести Артура Конан Дойла \"Знак четырёх\".","97190455":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97196409":"Веселая история про то, как в рождественскую ночь в украинском селе всех попутал бес и как могучему кузнецу Вакуле удалось одолеть нечистую силу и добыть для своей невесты царские черевички. Экранизация повести Н. В. Гоголя «Ночь перед Рождеством».","97212677":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","97225526":"Чтобы завладеть большим состоянием, чиновник Тарелкин инсценирует собственную смерть и «воскресает» под другим именем.","97229656":"Славянский юноша Кукша, попавший в плен к викингам, за мужество и отвагу получает имя Эйнар Счастливый. Начинается новый период в его жизни, полный приключений и обещаемого викингами счастья. Но единственное его желание - вернуться домой…","97240090":"1942 год. Молодой солдат Алёша Скворцов случайно подбивает два немецких танка. Командование готово представить его к ордену, но Алёша просит об одном — дать ему несколько дней отпуска, чтобы увидеть маму и починить в доме крышу.","97243088":"Окончив школу, Лена Кузнецова приехала в Москву и без особых трудностей поступила в пединститут. Став студенткой филфака, она четко сформулировала ближайшую цель — любой ценой достичь материального благополучия и сделать карьеру. Выйдя замуж за старшего научного сотрудника, Лена сразу же получила квартиру, машину и поклонников. А первая ее измена…","97246070":"Драма про жизнь Феликса Дзержинского \"Особых примет нет \"","97248437":"🎄 В Лудлвилле каждый день полон открытий, чудес и весёлых приключений. В этом сборнике — тёплые истории, зимнее волшебство и настроение настоящего праздника вместе с любимыми жителями ✨","97253694":"Приехав на экскурсию в Санкт-Петербург, одноклассники Дана и Лева становятся свидетелями кражи знаменитого Чижика-Пыжика. По легенде, если загадать желание и кинуть монетку на пьедестал памятника, не уронив ее в воду, оно обязательно исполнится. Но Чижик пропал! Значит ли это, что ребятам никогда не удастся воплотить свои мечты и родители Левы все-таки…","97257012":"Драма Захара Аграненко \"Ленинградская симфония\"","97260549":"🌌 День космонавтики — отличный повод посмотреть на мир шире!","97261050":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","97263013":"Клавдия взяла девочку из детдома и назвала Надеждой. Но ребенок не изменил ожесточившуюся против всего мира женщину. Агрессия приемной матери повторилась в Надежде.","97265440":"Английский лекарь, по ошибке осужденный на каторжные работы, сумел бежать. Бывшие заключенные, захватившие испанский фрегат, вынуждены поднять черный пиратский флаг. Они по-прежнему вне закона, и на них объявлена настоящая охота…","97267466":"Молодая воспитательница детского сада вполне довольна своей работой, что совершенно непонятно ее жениху Толику, впрочем, как и многим знакомым и приятелям девушки. Но она искренне любит детей и счастлива их искренней ответной привязанностью.","97275202":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","97279673":"🛰️ В преддверии Дня космонавтики хочется немного больше мечтать и исследовать…","97295863":"Приемная дочь доктора Скворцова, узнав, что ее мать жива, поехала к ней в деревню на каникулы. Женщина не знала, как приблизить к себе дочь. Встречи в колхозе с интересными людьми заставили Таню о многом подумать и многое пережить.","97310301":"Фильм основан на реальных событиях и рассказывает о боевой деятельности летчиков французской эскадрильи «Нормандия — Неман», сражавшейся в годы Второй мировой войны в рядах Советских Вооруженных сил.","97324925":"Телеграфистка Маша Степанова знакомится с шофером такси Алешей Соловьевым. Он назначает ей свидание, но не приходит на него, так как тяжело заболевает. Маша разыскивает Алешу и помогает ему выздороветь. Ее забота перерастает в большое настоящее чувство, но его легкомыслие разъединяет их до тех пор, пока они вновь не встретятся, но уже во время войны…","97335607":"Одиноко живется девятилетнему Боссе в доме у приемных родителей. Однажды с помощью сказочного духа мальчик попадает в волшебную страну Желанную. Теперь он - юный принц Мио, призванный спасти ее от сил зла, а король этой страны - его отец. Со своим другом Юм-Юмом они вызывают на поединок страшного и могучего рыцаря Като.","97336357":"В телевизионной постановке режиссер Карен Шахназаров представит зрителям свой новый взгляд на великий роман.","97338260":"Разведчик Михаил Тульев продолжает свою деятельность в стане врага. Вскоре ему предстоит узнать информацию о гибели отца, выйти на нацистского преступника и раскрыть планы о диверсионной акции западных спецслужб на территории СССР.","97342499":"Учителю истории Мельникову знакомы и сомнения, и чувство неудовлетворенности. Пусть он не всегда бывает прав, но он борется, ищет, любит, преодолевает трудности и сомнения.","97348197":"Новая серия Простоквашино — Перепись населения на нашем канале.","97355546":"Геннадий Куприянов работает на стройке. После постоянных ссор с женой герой уходит из дома к медсестре Зине. Её сын Саша тоже работает на стройке. Ему не нравится Геннадий и парень не знает, как освободить мать от беспокойства и горечи, которые вошли в дом с приходом этого странного человека. Парень стал часто бывать у нового друга. Внимательные…","97358455":"На пост председателя крайисполкома назначают директора судоремонтного завода Дмитрия Корепанова. Новый руководитель имеет свою точку зрения на развитие дальневосточного края. Экологический эксперимент, о котором он раньше только мечтал, ему придется отстаивать шаг за шагом.","97361793":"Поскитавшись по чужбине, Алексей вернулся на родину и, не найдя сочувствия и понимания у близких, затравленных страхом за свои судьбы, поехал в Запорожье, где случайные попутчицы Анна Андреевна и ее дочь Таня стали первыми, кому Алексей Павлов, поведал о своих мытарствах...","97365362":"В Москву из далекой сибирской деревни приезжает поступать в институт Алексей. Он останавливается у родственников, в профессорской семье.","97373348":"Апрель 1945 года. Три советских фронта окружают Берлин. Последняя столица нацистской Германии обречена, но Гитлер приказывает держаться до последнего. Начинается одна из самых кровопролитных городских битв в истории.","97373684":"Советский художественный драматический фильм, рассказывающих о последних днях гражданской войны, когда войско барона Унгерна, находясь в Монголии, попыталось нанести удар по Советской России. В центре сюжета - дружба монгольского пастуха и советского разведчика, который под видом белогвардейского полковника проник в штаб Унгерна и передал своему…","97379339":"В июле 1941 года наступающими немецкими войсками была перехвачена машина, перевозившая ювелирные изделия. Руководство германской разведки решило внедрить своего агента по документам убитого инкассатора...","97387425":"В основе фильма — главы романа «Братья Карамазовы» Ф. М. Достоевского. Пытаясь защитить мальчишку от преследований одноклассников, монах Алёша Карамазов со временем оказывается вовлеченным в историю жизни всего семейства капитана Снегирева — человека, пытающегося сохранить достоинство, несмотря на нищету и горе…","97389140":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","97399429":"Новая серия Простоквашино — Бобровый мех на нашем канале.","97400620":"Шестилетнему Васильку предстоит пойти в так называемый «нулевой класс». Василек готов к этому, но его беспокоит одно: будет ли в школе «все взаправду» или — как в детском саду — «все понарошку».","97428003":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","97437366":"❄️ В Арктике каждый день — новое открытие","97437371":"1919 год. Маленькая железнодорожная станция на Кубани захвачена белыми, но раненому комиссару Субботину чудом удается спастись. Мальчишки организовывают юнармию и просят комиссара Субботина стать их наставником.","97445642":"Комедия Эдмонда Кеосаяна \"Когда наступает сентябрь...\"","97448306":"Комедия о человеке из дикого племени тапи, который попадает в действительность 1960-х годов и пытается адаптироваться в ней.","97449669":"Криминальная драма о борьбе сотрудников уголовного розыска с бандитами в первые годы советской власти. В картине, как и в книге, показан конфликт между доверием к людям и равнодушной жестокостью. Перед зрителем разворачивается сложная драма характеров, контраста между революционной фразеологией и действиями карьеристов и демагогов. Главный герой стоит…","97452137":"История пути к успеху молодого дрессировщика Курихина и его сложных отношений с учителем - старым укротителем Лесновым.","97452306":"Фильм-хроника состоит из двух частей - «Бессонница» и «Уход». Зритель встречается с великим русским писателем в последние годы его жизни (1908-1910), однако воспоминания Льва Толстого возвращают нас и к событиям его молодости, и к поре решительного и страстного перелома в его взглядах. Финал - трагический уход из Ясной Поляны и смерть, ставшая началом…","97454584":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","97457127":"Хотя у Виктора Голикова мало опыта, его приглашают из провинциальной хоккейной команды в команду чемпионов на место вратаря. Тренер возлагает на талантливого парня большие надежды, но в команде все еще остается прежний вратарь.","97458704":"Бывший руководитель животноводческого комплекса получает задание поднять авторитет спорта на селе. Смекнув, что добиться успеха можно очень быстро, он решает пригласить профессионалов выступить под вымышленными фамилиями на областной спартакиаде. Но по дороге команда знакомится с корреспонденткой газеты Людой Миловановой. Скандала теперь не избежать...","97461840":"Комедия о первой любви десятиклассника к ученице хореографического училища. И о том, как под влиянием любимой герой становится другим человеком.","97468944":"В основе фильма реальный факт - футбольный матч между немецкой командой и командой советских военнопленных, бывших «Динамовцев». Это произошло в Киеве 22 июня 1942 года. Цена победы советской команды - смерть. В случае победы немцев советским футболистам была обещана свобода…","97473616":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","97474095":"Внучка председателя колхоза \"Белые пески\" Зинка мечтает стать дояркой. Дед Матвей считает, что она слишком молода для такой работы и может подвести его хозяйство в соревновании со знаменитым колхозом \"Заря победы\". Преодолевая все трудности, девушка умело справляется с коровой по прозвищу Ведьма, которая не слушается даже очень опытную доярку. Зина…","97476078":"В общем-то он обыкновенный парень - шофер Пашка Колокольников. Живет себе, работает, мечтает, встречается и расстается с самыми разными людьми. Но есть у него особая черта: он чувствует себя счастливым, только если вокруг всем хорошо.","97484340":"Фильм «Анна Павлова» (1983) Эмиля Лотяну — биографическая драма о легендарной русской балерине, чьё имя стало символом изящества и самоотверженного служения искусству. Картина прослеживает путь Анны Павловой от первых шагов в Императорском балете до всемирной славы: вы увидите изнурительные репетиции, триумфы «Русских сезонов» в Европе, создание…","97494497":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97496405":"Как и все подростки во время войны, Вася рвался на фронт. Он поступает в водолазную школу, но по ее окончании парня посылают помогать расчищать от топляка озеро. Васе, мечтающему о фронте, трудно свыкнуться с «тыловой прозой»…","97512318":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","97513236":"Драма Сергея Тарасова \"Антарктическая повесть\" 2-я серия","97513837":"В семье героини фильма все шло благополучно до тех пор, пока ее любимый муж, провожая их дочку в музыкальную школу, не познакомился с молоденькой учительницей музыки и не увлекся ею. В образцовой семье судьи Ивановой поселились ложь и обман…","97516743":"Молодая актриса перед тем, как сыграть в кино легендарную партизанку, разыскивает всех, кто знал ее героиню. И вдруг узнает, что бесстрашная партизанка жива и работает директором курортной гостиницы, где остановилась съемочная группа. Далее следуют волнующие встречи восходящей кинозвезды с героиней славного прошлого и с правдой жизни...","97517032":"Маленькая Русалочка полюбила Принца, однажды спасенного ею во время шторма. Ради этой любви Русалочка пожертвовала многим: она не побоялась покинуть свой дом, вступила в сделку с колдуньей. Колдунья, используя различные магические заклятия, сотворила ей вместо рыбьего хвоста человеческие ноги и сделала так, чтобы Русалочка смогла ходить и жить на земле.","97517629":"Однажды у первоклассника Пети появилась тайна, в которую он не мог посвятить самого близкого своего друга — маму. Подаренная отцом «шведская серия» марок была опрометчиво отдана Петей пятикласснику в обмен на марку «великой пиратской страны Гонделупы». Но верные одноклассники разоблачили авантюриста и помогли вернуть коллекцию другу.","97524576":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","97555999":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97569906":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","97570852":"Последний фильм Михаила Калатозова. В главных ролях — Шон Коннери, Клаудия Кардинале, Питер Финч, Харди Крюгер. Первый совместный с СССР фильм, финансировавшийся западной стороной.","97575493":"Молодой человек, лоботряс — допризывник Кеша, не способен надолго задержаться ни на одной работе. Ну никак не хочет он превращаться во взрослого человека! И вот он становится объектом смелого эксперимента: его берут на работу в детский сад. Расстаться с детством ему помогут дети...","97576510":"Что будет, если двое первоклассников решат проверить прочность черепашьего панциря под гусеницами настоящего танка? Один безумный эксперимент — и весь класс на ушах.","97585135":"Лирическая комедия. Главная героиня - Надя Клюева - скромная, неприметная женщина, которой работа и общественные поручения заменяют личную жизнь. Так Надя и продолжала бы жить, если бы не встреча со школьной подругой Сусанной - модной, эффектной, уверенной женщиной, ученым-социологом, разумеется, замужней. Сусанна уверена - \"не родись красивой, а родись…","97591526":"По мотивам произведения В.Ардаматского \"Сатурн\" почти не виден\". Первая серия двухсерийного остросюжетного фильма рассказывает о проникновении в строго засекреченную организацию \"Сатурн\" нашего разведчика, который завоевал доверие руководителей гитлеровского диверсионного центра и передал важное сообщение в Москву.","97591719":"Продолжение фильма \"Хозяин тайги\". История об участковом Сережкине - умном, бескорыстном блюстителе закона, оберегающем людей и природу бескрайних сибирских просторов. Служба Сережкина в новом районе началась в обстоятельствах исключительных и драматических. На каменном берегу Лысой Косы убит ученый-зоолог. На месте преступления одна улика - след ноги 37…","97592785":"Непростая судьба цыган, не раз воспетая поэтами, не лишена тягот и невзгод. Не обошел злой рок и цыганку Марию, которая оказалась на обочине жизни с единственным сыном. Решив оставить непредсказуемую кочевую стезю ради будущего своего Сашки, она поселяется в деревне, где молодой цыганенок находит верных друзей и свою первую любовь.","97593184":"Историко-революционный фильм Василия Ордынского \"Красная площадь\"","97594988":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","97595193":"В 1980 году перед трибуналом предстали предатели, которые 36 лет назад во время оккупации Крыма сотрудничали с гестапо, стали виновниками гибели актеров симферопольского театра. В 1944 году, за три дня до освобождения Симферополя советскими войсками, актриса Перегонец, художник Барышев и директор театра Рябинин были расстреляны по доносу.","97601935":"Советский сухогрузный корабль перевозил большой груз опиума для фармакологической промышленности. Современные пираты, охотившиеся за ценным грузом, коварством завладели кораблем и экипажем.","97610167":"Фильм воссоздает некоторые страницы творческой биографии советского писателя Аркадия Гайдара периода 1924-1941 гг.","97617742":"Студент Родик Самаркин, внук знаменитого ученого-археолога, отправляется с друзьями в Козары на поиски древних скифских захоронений. Не веря в результативность экспедиции, ребята возвращаются, оставив Родика одного…","97620429":"История о мальчике из алтайского совхоза, о поисках отца в огромной Москве; о том, что мечты и мысли редко совпадают с действительностью.","97621290":"На первом уроке истории он ошеломил своими знаниями всех, но потом выяснилось, что по другим предметам он сильно отстаёт от своих одноклассников, и ещё - он такой фантазёр, что ему просто невозможно верить…","97622139":"Драматург Ким Есенин, переживающий творческий кризис, приезжает в старинный русский город Суздаль. В краеведческом музее он встречает филолога Александру. Долгие беседы и неподдельная искренность собеседницы рождают в нем большие чувства…","97623395":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","97629297":"Ученики девятого класса одной из московских школ проходят летнюю практику на крупной автобазе. Быстро освоившись с организацией незамысловатого труда ремонтника, ребята выбирают в своем дружном коллективе снабженца — и каждый находит практику в чем-то полезной. Только Сережа Крашенинников (Крош) со своими гуманитарными способностями и полным отсутствием…","97630421":"Фильм-спектакль МХАТа по одноименной пьесе Р.Шеридана. Конец XVIII века. Нигде не умеют так ловко и подло плести интриги, как в салоне леди Снируэл. Бездумно и доверчиво бросается в эту соблазнительную светскую жизнь молодая леди Тизл, глубоко огорчая этим своего простодушного мужа. Теперь всех ждет серьезное испытание, ведь в хитросплетениях интриг,…","97634754":"Мальчик Петя был таким пугливым, что его мама решила обратиться к доктору. У волшебника-доктора есть прекрасное лекарство — «конфеты настоящей храбрости», да вот беда: чемоданчик с чудо-медикаментами попадает в чужие руки.","97640589":"\"Стачка\" Сергея Эйзенштейна это первый историко-революционный фильм. В нем приняли участие актеры Первого рабочего театра.","97651827":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","97652563":"О творчестве одного из крупнейших мастеров советской кинематографии — режиссера Марка Донского.","97656798":"Самое время отправиться в космическое путешествие вместе с Петей и Волком. В этом сборнике — фантазии о космосе, открытия и настоящие приключения!","97661346":"Нависший над землей загадочный шар становится источником несчастий. После встречи с посредником этого шара люди становятся подвластны злой силе. Однако влияние посредника не распространяется на сумасшедших и детей. Сережа и Настя решают предотвратить катастрофу - и с помощью инженера Замятина спасают Землю от вторжения злого Разума...","97676027":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","97678690":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","97679904":"Накануне отъезда на сибирскую стройку знаменитого строителя-монтажника Степана Бокова бросает жена. Однако в поезде он знакомится с жизнерадостной, обаятельной Аннушкой, молодой бетонщицей, которая по комсомольской путевке тоже едет в Сибирь. Между героями возникает симпатия, которая подкрепляется еще и совпадением «производственных интересов».","97681492":"Вернувшись из заграничной поездки, председатель колхоза узнает, что все девушки, мечтая выйти замуж, покидают колхоз и уезжают в город.","97681684":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","97687042":"По мотивам повести Анатолия Азольского «Лишний». \nСоветский разведчик заброшен на территорию довоенной Германии с целью проверки агентурной сети. Сеть провалена, он высылает информацию о готовящемся нападении фашистской Германии на СССР. Однако в органах госбезопасности ему не верят, хотят ликвидировать и дают ему задание лично убедиться в надёжности…","97705656":"Сатирическая комедия, высмеивающая нелепые представления некоторых американцев о Советской России. Американский буржуа мистер Вест едет в СССР. Родные и близкие Веста всячески отговаривают его от поездки - ведь это огромный риск! Предрассудкам Веста суждено развеяться, а вот предпринятые американцем меры предосторожности не спасают его от необыкновенных…","97712222":"Великая Отечественная война. Советское командование Западного фронта намеревается перебросить в тыл врага разведчицу Ниеле, ранее жившую в Берлине, и с помощью немецкого пленного офицера, внука одного из военноначальников рейха, выйти на генерала фон Герлица. Ради этой цели нужно пожертвовать всем...","97725771":"Анатолий кочевал по тюрьмам с юношеских лет и, отсидев девять лет, решил сделать признание следователю Хлебникову в том, что десять лет назад он в компании с другими подростками совершил убийство во время драки.","97747612":"1820-е годы. Сын плотника Жюльен Сорель боготворит Наполеона и мечтает о славе. Благодаря способностям и образованию он оказывается в среде сначала провинциального, а затем и высшего дворянства, но жизнь сложилась не так, как ему хотелось бы.","97765294":"Друзья строят аттракционы, открывают кафе и попадают в самые неожиданные приключения.","97767608":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97770102":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","97771414":"Продолжение фильма «Пропавшая экспедиция». На этот раз события разворачиваются в 1923 году. Герои фильма вновь попадают в те места, где было найдено богатое месторождение золота. Однако добраться до него оказывается не проще, чем несколько лет назад…","97776689":"Подростки Андрей и Генка живут в одном дворе. Обоим живется несладко. После того, как умерла мать, отец Андрея бросил семью и мальчик остался с сестрой. У семнадцатилетнего Генки мать работает проводником и редко бывает дома. В его квартире живет шофер Михаил Прохоров. Он постоянно одалживал ребятам деньги, но однажды вынуждает их участвовать в…","97785174":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97787304":"«Первая конная» — советский широкоформатный художественный фильм, историческая драма режиссёра Владимира Любомудрова.","97787548":"Из деревенского музея украли самые ценные экспонаты, к великому сожалению его директора и реставратора, художника Бережкова, приехавшего вместе с женой из города. О преступнике известно, что это мужчина высокого роста и с большим размером обуви.","97788031":"Музыкальная карьера известного эстрадного певца Андрея Ильина начиналась в маленьком городке Тутаеве. Спустя много лет к нему приезжает одиннадцатилетний земляк Антон, чтобы спеть ему свою песню. Но у Ильина нет времени на малолетнего барда. Тогда мальчик говорит, что он — его родной сын, после смерти мамы живет в интернате, а песня на самом деле…","97791039":"Мелодрама Карена Шахназарова \"Анна Каренина. История Вронского\"","97793756":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","97797788":"1918 год. В родное село с гражданской войны возвращается комиссар Сигизмунд Раевский, организовывает комсомольскую ячейку и поднимает народ на борьбу с кулачеством…","97808988":"Драма про жизнь Феликса Дзержинского \"Особых примет нет \"","97811438":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","97814303":"1942 год. Двенадцатилетний Иван потерял всё: мать и сестрёнку расстреляли фашисты, отец погиб на фронте.  Вместо детства — ночные вылазки в тыл врага. Вместо игр — бесценные разведданные, которые не смог бы добыть ни один взрослый. Только во снах к нему возвращается то, что отняла война.","97819832":"История о школьниках, увлекающихся историей родного города и случайно столкнувшихся с шайкой воров, которые сбывают краденое из музеев антиквариата.","97820578":"О первой любви — незабываемой, вернувшейся так некстати.\nВ юности они любили друг друга, но расстались. Илья женат, Саша была замужем. Семейная жизнь у обоих не сложилась. А теперь они опять вместе, на маленькой глухой станции они пытаются исправить ошибки юности. У них целых восемь дней...","97821310":"Фильм по одноименной повести Юpия Тpифонова о капитане хоккейной команды Дуганове - пpославленном споpтсмене и неоpдинаpном человеке, борющимся за спортивное долголетие таких «стариков», как он. Дуганов добивается участия в решающем финальном матче между двумя сильнейшими командами, преодолевая все трудности.","97822248":"Драма Павла Чухрая \"Запомните меня такой\" 1-я серия","97829570":"Трогательная лирическая киноповесть о судьбе собаки, теряющей любимого хозяина, об отношении людей к «братьям меньшим», которое как рентгеном просвечивает души, выявляя в одних низость и мелочную подлость, а в других - благородство, способность сострадать и любить…","97829759":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","97830496":"Фабриканта Ланса Гереро на основании неопровержимых доказательств обвиняют в убийстве девушки. Однако молодой адвокат еще надеется разоблачить преступников, занимающихся фабрикацией ложных улик, избавляя своих заказчиков от конкурентов…","97834742":"Печальная история Федора Кузькина, разделившего с родной страной все тяготы тридцатых, а затем и сороковых годов. Теперь Кузькин решает стать единоличником. Но вновь начинаются мытарства крестьянина - и уже без надежды…","97844985":"1919 год. В Сибири идет гражданская война. Пользуясь полной неразберихой, Генерал Колчак хочет вывезти за границу часть золотого запаса страны. В самый последний момент об этом узнают большевики.","97846897":"Под Новый год Женя Лукашин и его друзья по традиции идут в баню. Они выпивают и по ошибке отправляют Женю в аэропорт, он летит в Ленинград и проводит новогоднюю ночь в чужой квартире с чужой невестой. Но в результате этих несуразиц герой обретает большую любовь.","97858997":"Трое друзей из Москвы живут «дикарями» в замечательном месте с песчаным пляжем, пресной водой, тенью и дровами у самого моря. Отдыхают.","97864646":"Злой колдун-магрибинец взывает к звездам, чтобы те поведали ему имя человека, что найдет волшебную лампу, способную творить чудеса. Звезды ответили: «Это Аладдин». В Багдаде живет дочь султана, красавица Будур. Всякий, кто посмеет взглянуть на нее, будет казнен.","97865309":"Действие происходит в 30 — 50 годы. Неразлучные друзья Кайтанов, Уфимцев и Акишин добровольно стали первыми метростроевцами. О них и их подругах Леле, Маше и Тане и других друзьях и товарищах рассказывает этот фильм. Свою дружбу и единство они пронесли через всю жизнь. Трудовой фронт, испанские добровольные бригады, Вторая мировая война и снова…","97865694":"Когда еще Василиса была маленькая, черный колдун принес ее матери зловещий подарок - сундучок с заколдованным свадебным платьем. Надев его, Василиса могла загадать желание, и оно непременно бы исполнилось. Однажды девушка приревновала кузнеца Ивана, и его глаза перестали видеть. Василисе пришлось пройти испытания и строго выполнить наказ колдуна, чтобы…","97875108":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97880687":"В самом конце войны двое ребят сбегают из училища и пробираются на фронт. В вокзальной сутолоке беглецы теряют друг друга — и вскоре одному из них предстоит принять свой первый бой.","97883686":"Действие происходит в 1980-е годы. В некоем европейском городе начинается политическая борьба за кресло мэра. В руки журналиста Петера Лоссера попадают документы, подтверждающие, что предвыборная кампания одного из кандидатов финансируется спецслужбами другой страны. Оказавшись втянутым в политический водоворот, Лоссер должен сделать свой выбор и...…","97883757":"Бедный студент Родион Раскольников идет на преступление, за которым неизбежно следуют муки совести: его душа, отягощенная грехом убийства, мечется между верой и безверием, надеждой и отчаянием. Расследование сыщика Порфирия Петровича в конечном итоге выводит следствие на Раскольникова, но еще до знакомства со следователем Родион встречает настоящую…","97885792":"Борьба с космическими пиратами, захватывающее путешествие во времени, знакомство с девочкой из будущего Алисой Селезневой — вот к чему привел обычный поход за кефиром мальчика Колю из 6-го класса.","97886421":"Гражданская война. Звезда немого кино Ольга Вознесенская в приморском южном городе, занятом белыми, снимается в салонной драме \"Раба любви\". Оператор кинокартины Виктор Потоцкий - революционер-подпольщик. Он, рискуя жизнью, нелегально ведет съемки арестов и расстрелов, чинимых контрразведкой белых. Ольга восхищена его мужеством. Постепенно это чувство…","97897418":"Осенью 1938-го года три бывших бойца интернациональной бригады - русский Шухов, француз Анри и американка Лиз - попадают в курортный городок на границе Испании и Франции. Встретив медсестру, которая должна переправить на Корсику испанских детей, они решают помочь ей. Однако в городе вдруг вспыхивает фашистский мятеж, и дети оказываются заложниками…","97899109":"Однажды с четырнадцатилетним Костей произошла удивительная история: он встретил лося, который случайно забрел в город и очень испугался, оказавшись в незнакомой обстановке. Мальчик решил помочь доверчивому зверю и вывести его из города.","97901292":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","97906334":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","97911862":"Драма Сергея Тарасова \"Антарктическая повесть\" 1-я серия","97916162":"Фильм рассказывает о революционных событиях 1917 года в Петрограде и воспроизводит массовые сцены, выступления Ленина с броневика, митинг в Смольном, залп \"Авроры\", штурм Зимнего дворца.","97923335":"История о советском хирурге, приехавшем в Кабул по приглашению революционного правительства в начале 80-х годов. Вместе со своим учеником Азизом врач проводит в палатах и операционных дни и ночи, помогая всем афганцам, независимо от их убеждений. В госпитале, как в зеркале, отражается сложная политическая ситуация тогдашнего Афганистана, здесь собрались…","97923603":"Фантазерка и мечтательница Лена, солистка балета на льду, мечтает поставить сказочный волшебный спектакль. Однажды героиня знакомится с Юрой, таким же мечтателем, как и она сама, и, не назвав своего имени, оставляет ему свой телефон…","97936810":"🏡 В Простоквашино дружба — это не только весёлые приключения, но и умение находить общий язык, даже когда мнения расходятся.","97939757":"Жил да был царь Еремей. Отправился он в годовой поход, чтобы составить опись своего царства-государства. Наклонился он как-то к колодцу напиться, но тут его и схватил подводный царь Чудо — Юдо. Да потребовал выкуп за освобождение — такой, о чем Еремей не ведал и не гадал, что оно есть в его царстве. Царь согласился, еще не зная, что в его отсутствие…","97943481":"Продолжение фильма «Солдат Иван Бровкин». После демобилизации Иван Бровкин гостил дома недолго. Вместе со своими друзьями он решил поехать на целину. А Любаша, не согласившись ехать в далекую землю, снова осталась ждать своего Ивана, который вместе со всеми преодолевал трудности, а вскоре стал бригадиром трактористов, ударником труда.","97949827":"1944 год. После Курской битвы стратегическая инициатива полностью перешла к советским войскам. Красная Армия готовит серию сокрушительных ударов, которые должны освободить Белоруссию и открыть путь на запад.","97950424":"Весна 1945 года. Близится к концу Великая Отечественная война. Неспокойно в Западной Белоруссии. Там действует жестокая банда бывшего пособника нацистов Болеслава Крука. Бандиты не жалеют никого, в том числе и женщин, и детей, убивая, грабя и поджигая колхозные угодья. Свои щупальца банда протянула аж до Москвы, где имеет своих доверенных людей,…","97954111":"«Первая конная» — советский широкоформатный художественный фильм, историческая драма режиссёра Владимира Любомудрова.","97959592":"30-е годы. Коллективизация широкой волной прокатилась по нашей стране. Поволжский крестьянин Никита Гурьянов не принимает новую систему хозяйствования и пускается в странствование в поисках неведомой благодатной земли…","97961750":"Деревенский паренек Иван Бровкин считался «непутевым», потому председатель колхоза старался держать от него подальше свою дочь Любашу. Захар Силыч попробовал сделать из Ивана шофера. Но Иван подвел своего наставника, утопив в речке колхозный грузовик. Лишь заступничество матери за сына и… повестка в армию помогли избежать серьезных последствий.","97962361":"Смотрите военную драму «Звезда» (2002) в высоком качестве на официальном канале Мосфильма.","97968541":"По мотивам одноименной поэмы А.С. Пушкина. В день свадьбы доблестного витязя Руслана и Людмилы, дочери киевского князя Владимира, невесту похищает злой карлик Черномор. На поиски красавицы отправляются четверо: безутешный Руслан, хазарский хан Ратмир, князь Рогдай и кичливый Фарлаф. Множество трудных дорог пришлось преодолеть Руслану, претерпеть козни…","97976860":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97982925":"Новая серия Простоквашино — Распорядок дня на нашем канале.","97983106":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","97996720":"Талантливый изобретатель, создавший аппарат невиданной разрушительной силы, одержим идеей мирового господства. В своем маниакальном стремлении он совершает одно преступление за другим, не предполагая, сколь ужасными окажутся последствия для него самого…","98007615":"Вторая мировая война. В одной из немецких разведшкол готовятся диверсионные группы из русских военнопленных для заброски в СССР.","98007915":"Отгремела гражданская война. В маленьком южном городке появился шестой по счету начальник милиции. Пятеро предшественников Глодова вместе с другими активистами были зверски убиты бандой неуловимого Вахрамеева. И теперь Глодову с несколькими верными помощниками предстояла смертельная схватка с сильным врагом...","98013353":"Герой фильма уверен: настоящая любовь всегда подобна внезапной вспышке, озарению; не ошибается в любви только тот, кто доверяет своей интуиции. Вскоре ему, ученику выпускного класса, предоставляется шанс проверить эту теорию на практике.","98015160":"«И всё-таки я верю...» - документальный фильм Михаила Ромма, завершённый после его смерти учениками и соратниками Элемом Климовым, Марленом Хуциевым, Германом Лавровым. Основа ленты - архивные хроникальные кадры. В первой части фильма звучит голос М. Ромма. Автор, как «ровесник века», предлагает «пробежать» по истории XX столетия и вспомнить  его важные…","98019316":"Фильм рассказывает об одном из переломных моментов в истории Советского государства — о мятеже левых эсеров 6 июля 1918 года, когда ими была предпринята отчаянная попытка захватить власть в свои руки. На 5-м съезде Советов эсеры призвают к разрыву Брестского мира. Однако, большинством голосов съезд принимает резолюцию фракции большевиков, одобряющую…","98019317":"Драма из двух серий Элема Климова «Агония». В роли Распутина — Алексей Петренко.","98030246":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","98050220":"Драма Сергея Соловьева \"Станционный смотритель\"","98050245":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","98059219":"Экранизация режиссёра Александра Столпера одноименной повести Бориса Полевого. В основе драматической истории - реальные факты биографии летчика-истребителя Алексея Мересьева. Сбитый в бою над оккупированной территорией, он три недели пробирался по заснеженным лесам, пока не попал к партизанам. Потеряв обе ноги, герой впоследствии проявляет удивительную…","98060126":"Военная драма Сергея Колосова \"Вызываем огонь на себя\"","98068155":"Историко-биографический фильм Владимира Петрова \"Кутузов\"","98076363":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","98077703":"Весна 1945 года. Близится к концу Великая Отечественная война. Неспокойно в Западной Белоруссии. Там действует жестокая банда бывшего пособника нацистов Болеслава Крука. Бандиты не жалеют никого, в том числе и женщин, и детей, убивая, грабя и поджигая колхозные угодья. Свои щупальца банда протянула аж до Москвы, где имеет своих доверенных людей,…","98078884":"Драма Константина Худякова \"С вечера до полудня\" 1-я серия","98086120":"Вернувшись из армии, 20-летний Сергей устраивается на ТЭЦ и вливается в обычную жизнь. Каждый день он встречается и проводит время с друзьями детства - молодым семьянином Славой и весельчаком Николаем, а однажды с первого взгляда влюбляется в незнакомку в автобусе. Эти ребята - первое поколение советских людей, которое сомневается и ищет своё место в жизни.","98086383":"По одноименному роману И.С.Тургенева. Середина XIX века. Мечтания, помыслы, надежды юной Елены Стаховой еще еле ощутимы. В сонной атмосфере старого дворянского дома, изредка нарушаемой ссорами родителей, трудно найти ответ на вопрос - как жить? Но вот Елена полюбила. Ее избранник - молодой болгарин Дмитрий Инсаров, страстный патриот, борец за свободу…","98090810":"Тридцатилетняя Галина умна, обаятельна и красива. Она работает реставратором в мастерской ленинградского Екатерининского дворца и, казалось бы, создана для любви. Но настоящего чувства все нет и нет…","98098253":"По мотивам одноименного романа А. Грина. Пианист Гарвей, направляющийся на гастроли, сходит с поезда, чтобы купить сигарет, и узнает у продавщицы, что выдуманные Грином города существуют на самом деле в 30 минутах езды на автобусе. Он забывает о гастролях и отправляется в такой город...","98098758":"Гражданская война окончена, и на земле Хакасии налаживается новая жизнь. Однако все еще дают знать о себе остатки недобитых банд, скрывающихся в тайге и наводящих ужас на испуганных местных жителей. Красноармеец Сыгды Кирбижеков получает задание проникнуть в одну из банд и «разоружить» ее изнутри.","98118312":"По одноименной сказке А.Н.Толстого. Из обыкновенного полена бедный бездетный шарманщик папа Карло выстругал говорящего длинноносого человечка - Буратино. Любознательный Буратино идет в школу, но по дороге слышит музыку, зазывающую зрителей на представление кукольного театра. Ноги сами несут его к театру, и Буратино оказывается в мире, где живут злой и…","98119519":"В пионерском лагере дети играют в традиционную военно-спортивную игру. У всех на плечах бумажные погоны — главный символ в этой игре. Если противник их сорвет — ты «убит». Жестокость ненастоящей войны делает детей озлобленными и одержимыми.","98130955":"По мотивам одноименной повести В.Войновича \"Шапка\". Писатель Рахлин узнает от коллеги, что в Литфонде раздают шапки по принципу значимости людей. Рахлину сообщают, что, несмотря на то, что он популярный прозаик, автор одиннадцати книг, член Союза писателей, он может рассчитывать только на шапку из меха кошки. Не желая признать себя человеком второго…","98166627":"Новая серия Простоквашино — Ужасная тренировка на нашем канале.","98189852":"Драма Михаила Швейцер и Софьи Милкиной \"Время, вперед!\"","98191809":"События происходят в годы гражданской войны. Красный командир (он же — и сельский учитель) отправляет юного поэта Ваню в московскую редакцию журнала «Революция и поэзия». Сопровождает Ваню в долгом, полном событий пути, бывалый солдат Сорокин…","98195335":"Сюжет фильма построен на башкирской народной сказке о богатыре Алтындуге, освободившем свой народ от рабства. Для этого необходимо было соединиться в союзе любви двум племенам: табынцам и айлинцам. Пройдя через многие преграды и испытания, богатырь разыскал свою любимую Ай и разрушил царство зла. Фильм ярко показывает природу Башкирии, нравы и обычаи…","98199893":"Школьник Митя, приехав на каникулы в деревню, попадает в волшебную страну, где вместе с героями любимых книжек вступает в борьбу со всеми сказочными злодеями: Кащеем Бессмертным, Соловьем-Разбойником. И даже Лихо Одноглазое удалось одолеть смельчакам!","98215034":"Победив страшного дракона, солдат Иван возвращается с войны. Тридевятое царство ликует. Царь, тоже Иван, очень доволен.","98220731":"«Доброе утро» - художественный фильм режиссёра Андрея Фролова, снятый в 1955 году.\nФильм о том, как безответная любовь помогает карьере. Тихая, застенчивая Катя оказывается в группе молодых строителей шоссейной дороги. Ей нравится веселый парень, известный экскаваторщик Вася Плотников. Но ему кружит голову только его личный успех. Катя переходит на…","98222978":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","98228514":"Что важнее: действовать или оставаться верным себе?","98232078":"Следователь Муромцев, расследуя должностное преступление участкового милиционера, выходит на дельцов теневой экономики. Параллельно с основным действием развивается средневековый сюжет с врачом-алхимиком, портрет которого висит в комнате одного из героев современной истории.","98235392":"Середина 1930-х годов. Американский цирковой аттракцион «Полет на Луну» приезжает на гастроли в СССР. Звезда номера Марион Диксон пользуется огромным успехом у советских зрителей. Но в жизни цирковой артистки не все так безоблачно, как кажется. Антрепренер Кнейшиц, пользуясь безвыходным положением несчастной женщины, эксплуатирует ее, шантажирует угрозой…","98235936":"Новая серия Простоквашино — Едем в город, 2 часть на нашем канале.","98237273":"Это фильм о событиях второй мировой войны. «Ночными ведьмами» называли бесстрашных советских летчиц фашисты. Они воевали на «ночных» бомбардировщиках ПО-2. Для девушек это прозвище было самой высшей оценкой их вклада в победу.","98249738":"Советский кинофильм Леонида Гайдая 1975 года. Фильм состоит из трех новелл, снятых по произведениям Михаила Зощенко: по комедии «Преступление и наказание», рассказу «Забавное приключение» и комедии «Свадебное происшествие».","98251267":"Следователь Муромцев, расследуя должностное преступление участкового милиционера, выходит на дельцов теневой экономики. Параллельно с основным действием развивается средневековый сюжет с врачом-алхимиком, портрет которого висит в комнате одного из героев современной истории.","98253912":"По повести А. Абу-Бакара «Снежные люди». Могильщик Бекир в сердцах выгоняет из дома свою жену Хеву. По закону шариата муж  может вернуть ее только после того, как она будет изгнана следующим мужем. Бекир договаривается с холостяком-парикмахером Адамом, временно выдает за него Хеву, чтобы она как можно быстрее вернулась обратно. Но Адам не спешит выгонять…","98259361":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","98260068":"Легендарная киноэпопея о событиях Великой Отечественной войны, вышедшая на экраны во времена расцвета культа личности Сталина. В исторический контекст вплетена сюжетная линия сталевара Алексея Иванова, ушедшего добровольцем на фронт. Все важнейшие события войны показаны через личное участие в них Алексея: от знаменитого военного парада в ноябре 1941 года…","98264589":"Два рассказа («Подвиг солдата Мухина», «Последняя осень»). События одного касаются 1917 года, когда временное правительство ужесточает репрессии, и ЦК партии принимает решение переправить Ленина в Финляндию. Действие второго происходит в 1923-1924 гг. во время последних месяцев его жизни в Горках.","98265003":"Каждое утро Сева, Генка и Толик едут на работу на электричке. Однажды в вагоне появляется очаровательная Ася. Девушка только что окончила школу и начала работать на том же заводе, что и трое неразлучных друзей. В нее сразу влюбляется Сева, готовый помочь ей сдать экзамены в институт. Но шансов на взаимность у него нет - Ася отдает предпочтение…","98275494":"По пьесе А.Вейцлера и А.Мишарина \"День-деньской\". Действие фильма происходит в середине 70-х годов, во время так называемой научно-технической революции в СССР. Директора крупного предприятия Игоря Друянова собираются снять с работы за невыполнение государственного плана. На его место хотят назначить молодого энергичного сотрудника министерства Дмитрия…","98276593":"О подвиге комсомолки Веры Флеровой, первооткрывательницы крупнейшего месторождения вольфрама и молибдена в Кабардино-Балкарии. Действие фильма происходит в начале 30-х годов.","98280270":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","98280677":"«Калина красная» -  художественный фильм Василия Шукшина по одноименной повести.","98289408":"Драма Павла Чухрая \"Запомните меня такой\" 2-я серия","98295977":"Фантастический детектив, действие которого происходит в вымышленной стране на юге Африки – Лемурии, где группа неофашистов производит секретные опыты над людьми. Их цель — при помощи психологического оружия установить господство на планете, уничтожив человеческую память.. Этим античеловеческим замыслам противостоит советский ученый-психолог Лесников.","98307296":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","98308983":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","98313776":"Комедийный фильм Татьяны Лукашевич \"Подкидыш\"","98319097":"50-летний Василий Муравин приходит к выводу, что жизнь не удалась - дома его ни во что не ставят, нигде нет ни любви, ни справедливости… Он берет в руки старую гитару и решает перестать размениваться по мелочам и начать, наконец, шагать по главной улице с оркестром.","98321062":"Вернувшись из армии, 20-летний Сергей устраивается на ТЭЦ и вливается в обычную жизнь. Каждый день он встречается и проводит время с друзьями детства - молодым семьянином Славой и весельчаком Николаем, а однажды с первого взгляда влюбляется в незнакомку в автобусе. Эти ребята - первое поколение советских людей, которое сомневается и ищет своё место в жизни.","98321120":"Великая Отечественная война разлучила множество близких людей. Кто-то смирился и продолжал жить. Другие не теряли надежды, пытаясь отыскать родных даже по прошествии многих лет хотя бы для того, чтобы проститься. Валентина потеряла дочь ещe в самом начале военных действий. Теперь же она всеми силами пытается найти еe, даже не представляя, где она может…","98326620":"По мотивам \"Донских рассказов\" Михаила Шолохова. Большевик Фома Коршунов возвратился в станицу и подружился с семилетним Мишкой. Когда ворвавшиеся в станицу бандиты убивают Фому, Мишка седлает коня и спешит предупредить красных об опасности…","98329873":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","98333601":"По одноименной повести К.Симонова. 1942 год. Батальон капитана Сабурова выбивает фашистов из трех домов, вклинившихся в нашу оборону. Немцы, подтянув силы, вновь захватывают их. Приходит осень, и подвоз боеприпасов по Волге прекращается. Экономя каждый патрон, бойцы продолжают сдерживать натиск врагов. В одну из ночей сабуровцы слышат нарастающий гул…","98337806":"По роману Марио Варгаса Льосы \"Город и псы\". События фильма происходят в условной стране, главный герой - курсант привилегированного военного училища, случайно попавший туда из самых низов общества. Теперь он - Ягуар, он - борец с тоталитарным режимом.","98338278":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","98352640":"На Михаила Тульева вновь совершается покушение. Тем временем на территории СССР действует резидент и наёмный убийца Брокман, обезвредить которого становится главной задачей советских контрразведчиков.","98353434":"История о том, как пьяница и дебошир Гришка Орлов и его жена во время нагрянувшей эпидемии становятся санитарами холерного барака.","98358765":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","98358871":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","98359593":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","98375497":"Две новеллы: — «Снежная крепость», «Полчаса на чудеса».","98378009":"1918-1919 годы, Грозненский округ Терской области бывшей Российской империи. Занявшие территорию части Добровольческой армии под командованием генерала Ляхова пытаются не допустить установления Советской власти и ликвидировать перешедших на нелегальное положение большевиков.","98378342":"Комедия Самсона Самсонова \"За витриной универмага\"","98384322":"Фильм драма Александра Столпера и Бориса Иванова \"Парень из нашего города\"","98397437":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","98405398":"...В разгар боев на Украине комиссару полка Клавдии Вавиловой пришла пора стать матерью. Временно покинув полк, она находит приют в семье бедного жестянщика Ефима Магазанника, отца шестерых детей. Комиссарская суровая бескомпромиссность Вавиловой под влиянием мудрой доброты местечкового мечтателя в чем-то утрачивает свою монолитность. И все же после…","98407195":"Последние месяцы Второй мировой войны. Ян Трейбал покидает захваченную Гитлером Чехословакию и попадает в СССР, где становится офицером первого чехословацкого авиационного полка. Вместе с ним воюют неунывающий подпоручик Мартин Габриэль, бескомпромиссный лейтенант Александр Лежнев и полный романтических представлений о жизни юный пилот Томек Яндак…","98408914":"Фильм по мотивам рассказов Юрия Трифонова состоит из 3-х новелл о спортивной жизни.","98428406":"Биографический сериал «Михайло Ломоносов» состоит из 9 серий:","98429661":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","98433466":"По мотивам романа И.Герасимова \"Пробел в календаре\". Герои фильма - ученые, работающие в металлургии. Различные взгляды на научную проблему превращают бывших друзей в непримиримых противников…","98440927":"Профессиональный разведчик Ингмар Росс, сотрудник одного из посольств, получает задание — завербовать специалиста московского засекреченного предприятия. Но, полюбив русскую женщину, Росс отказывается от двойной жизни и решается на довольно неординарный поступок.","98441305":"Фильм «Волга-Волга» — музыкальная комедия о приключениях двух коллективов художественной самодеятельности маленького уральского городка, отправившихся на конкурс в столицу по рекам Чусовая, Волга и каналу имени Москвы. Песня, написанная Дуней по прозвищу Стрелка, выигрывает в конкурсе, несмотря на сопротивление бюрократа Бывалова.","98443938":"Новая серия Простоквашино — Блинный день на нашем канале.","98445840":"🌴 Что получится, если в одном месте собрать самых разных зверят?","98447067":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","98450603":"Следователь Муромцев, расследуя должностное преступление участкового милиционера, выходит на дельцов теневой экономики. Параллельно с основным действием развивается средневековый сюжет с врачом-алхимиком, портрет которого висит в комнате одного из героев современной истории.","98453948":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","98457970":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","98460693":"Фильм-балет Сеpгея Пpокофьева по одноименной тpагедии У.Шекспиpа в исполнении солистов Большого театpа СССР.","98468515":"Человек укрощает огонь — и покоряет космос.","98471847":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","98475024":"Фильм рассказывает о жизни двух лириков, блиставших на поэтических вечерах небольшого портового города. Их судьбы были разделены Гражданской войной: когда они оказываются вовлечёнными в эти грозные события, Орловский становится участником белого движения, а Тарасов, попав в конницу Котовского, борется на стороне красных. На фоне этого неспокойного…","98478570":"Драма Григория Александрова \"Встреча на Эльбе\"","98481666":"Исторический фильм Михаила Ромма и Дмитрия Васильева \"Ленин в октябре\"","98483647":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","98486855":"По мотивам одноименной поэмы А.С. Пушкина. В день свадьбы доблестного витязя Руслана и Людмилы, дочери киевского князя Владимира, невесту похищает злой карлик Черномор. На поиски красавицы отправляются четверо: безутешный Руслан, хазарский хан Ратмир, князь Рогдай и кичливый Фарлаф. Множество трудных дорог пришлось преодолеть Руслану, претерпеть козни…","98487458":"Драма Себастьяна Аларкона \"История одной бильярдной команды\"","98490378":"Отправляясь в дальнее странствие, купец Данила спрашивает своих дочерей, что привезти в подарок? Старшая просит волшебное зеркальце, средняя золотой венец, а младшей не нужны ни зеркала, ни венцы золотые. Нужен ей лишь цветочек аленький, краше которого нет во всем белом свете.","98490756":"История трудного подростка из Сургута. Отец пятнадцатилетнего Борьки Хромова утонул после развода, а мать с новым мужем заняты накопительством, сын ей не нужен. Желание уехать из Сургута так и остаётся несбыточной мечтой подростка. Даже в тайге Борька сталкивается с проблемами, пойдя ночью браконьерствовать...","98499252":"Главный герой фильма - старший брат В.И.Ленина Александр Ульянов, лидер и руководитель «террористической фракции» партии «Народная воля». Ульянов и его товарищи были арестованы при подготовке покушения на российского императора Александра III и приговорены к казни через повешение. Фильм, основанный на исторических материалах, повествует о заключительном…","98500554":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","98501351":"Музыкальная кинокомедия рассказывает о молодых энтузиастах джазовой музыки 20-х годов. Они мечтают о славе и едут в Москву, где преодолевают множество препятствий на пути к признанию.","98501620":"Двенадцатилетний Валера живет с родителями в небольшом поселке. В семье мальчика все подчинено одному — накоплению богатства. Этим же заполнена и жизнь Валеры. Он не играет, не бегает, как все дети, а целые дни работает. Даже рыбной ловлей мальчик занимается не ради удовольствия, а для того, чтобы побольше заработать.","98515073":"«Своих боюсь, и чужих боюсь». Сильная драма о послевоенной деревне","98518394":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","98519499":"По одноименному водевилю А.П.Чехова. Мещане Жигаловы, у которых на выданье дочь Даша, к ужасу своему узнают, что чиновник Апломбов, все лето ухаживавший за Дашей, ежедневно обедавший у них и зарекомендовавший себя женихом, жениться вовсе не собирается.С большим трудом удалось отцу Дашеньки уговорить амбициозного жениха сделать предложение. Жених…","98524999":"Драма Андрея Михалкова-Кончаловского \"Сибириада\"","98525393":"Неразлучные друзья-шестиклассники Саша, Аня и Юра ничего не скрывают друг от друга. Но из-за неугомонного Юры Пузырева сокровенная тайна толстушки Ани, которая влюбилась в учителя литературы, становится всем известна. Так в кругу друзей назрела первая серьезная размолвка...","98525590":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","98530190":"Комедия Марка Захарова \"Тот самый Мюнхгаузен\" 2 серия.","98548052":"По мотивам произведений Михаила Булгакова «Бег», «Белая гвардия» и «Черное море». Фильм повествует о бегстве из России в конце гражданской войны русских людей: военных, дворян, интеллигенции. Трагедия боевого генерала Хлудова, надорвавшего душу собственной жестокостью; история казачьего генерала Черноты, превратившегося на чужбине в нищего; личная драма…","98549055":"О судьбе молодой девушки Анны, оказавшейся среди обитателей меблированных комнат \"Мечта\" в одном из городов Западной Украины. Здесь живут несчастные люди, которые не могут найти свое место в жизни, жестоко отвергающей их. Лишь Анне удается вырваться из серых будней - она уежает в Советский Союз...","98549535":"Пионер Андрей Васильков и его друг Гулька, воодушевленные лозунгом «ни одной жертвы стихии водной, спасти человека наш долг благородный», разыгрывают несчастный случай на воде перед группой иностранных туристов. Свидетелем этого случайно становится юный корреспондент Егор Подушкин, который с большим энтузиазмом начинает раскручивать эту ситуацию.","98549934":"Драма Владимира Басова \"Случай на шахте восемь\"","98560261":"В конце XVII века Россия терпела убытки в торговле, потому что не имела выхода к морю. Юный российский самодержец Петр I начинает строительство флота. Тем временем, среди бояр зреет недовольство молодым монархом.","98567411":"Экранизация одноименной повести Бориса Балтера. О дружбе мальчишек, живущих у моря, первой любви и смысле жизни, в которой завтра будет война, но об этом они пока еще не знают...","98578324":"По мотивам рассказов Веры Пановой \"Валя\" и \"Володя\".","98580047":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","98588240":"Этот фильм - попытка Григория Александрова воссоздать незавершенную киноленту, которую он снимал в Мексике в 1931 году вместе с режиссером Сергеем Эйзенштейном и оператором Эдуардом Тиссэ. Киноматериал в те годы был задержан в Голливуде и попал в СССР лишь в конце 70-х, когда двоих из съемочной группы уже давно не было в живых. Пользуясь либретто…","98590596":"Фильм, снятый по мотивам одноименного очерка Николая Лескова. Главная героиня, Катерина Измайлова - красавица-жена богатого купца, вышедшая замуж не по любви, влюбляется в приказчика Сергея. Она на все готова ради своей грешной, преступной любви. Не знающая границ страсть приводит к преступлению - убийству мужа и маленького племянника Феди. Но все тайное…","98599840":"В середине 1944 года гитлеровское руководство приняло план уничтожения городов Варшава, Братислава, Прага, Краков. Секретный план гитлеровцев стал известен Советскому командованию В район Кракова была направлена группа советских военных разведчиков, состоящих из майора «Вихря», его помощника Коли и радистки Ани. Группа получила задание связаться с…","98620300":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","98620657":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","98623428":"Середина 80-х. Судьбы двух школьных товарищей сложились по-разному: один стал офицером пограничных войск, а другой устроился в ресторане барменом и оказался втянутым в операцию, разработанную иностранной разведкой.","98625336":"Увлекательная история дружбы мальчика Саньки, прозванного рыжиком за медно-красный цвет волос, и артиста-клоуна Полфунта. Вместе они колесят по бескрайним просторам России в поисках счастья.","98629153":"Пограничный сторожевой корабль, которым командует Алексей Никитин, обнаруживает неправомерные действия иностранных рыболовецких судов в наших территориальных водах. Опытный командир разгадывает планы противника и начинает преследовать замаскированное под краболова разведывательное судно...","98630975":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","98636781":"Фильм, рассказывающий о жизни страны Советов в 30-е годы ХХ века. Литературную основу этого фильма составляют фельетоны, рассказы, очерки, записные книжки известных И.Ильфа и Е.Петрова. Фильм лишен как такового сюжета и строится как коллаж, включающий в себя реплики, ситуации и персонажи, взятые из разных произведений писателей-сатириков. В фильме…","98652933":"Герои этого фильма - юные фантазеры. Они никого не обманывают, просто придумывают необыкновенные истории, и сами в них верят.","98654283":"Симпатичные Енотки живут в большой музыкальной шкатулке. Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке.","98655528":"Третья серия кинокартины \"Братья Карамазовы\"","98656225":"В девятом классе появился новенький. Замкнутый парень подчинил себя единственной цели — расшифровать таинственные письмена исчезнувшего племени тольтеков. Не посвятив в свои изыскания никого кроме учителя из своей бывшей школы, герой обрекает себя на непонимание окружающих…","98661230":"По одноимённой пьесе Михаила Булгакова. В основе сюжета - переломный момент истории России - революция и Гражданская война, раз и навсегда изменившим жизнь русской интеллигенции.","98666909":"Комедийный фильм Элема Климова \"Добро пожаловать, или Посторонним вход воспрещен\"","98680052":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","98684596":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","98685839":"По мотивам одноименной повести Г.Бакланова. Фильм об одном из плацдармов на правом берегу Днестра, обороняемом небольшой группой пехотинцев и артиллеристов в 1944 году. В течение нескольких недель они героически отбивают атаки немецкой армии, теряя в бою лучших товарищей.","98686978":"1918 год. Тревожно в Петрограде. Все теснее сжимается вокруг революционного города вражеское кольцо. Уходят на фронт рабочие полки. Борьба с врагами Советской власти идёт не только на подступах к городу, но и в тылу. В это суровое и трудное для революции время по воле партии большевиков на рабочих окраинах создаются комсомольские организации. Первыми в…","98687582":"Телевизионный детектив по мотивам произведений В. Липатова об умном, внешне простоватом, добродушном сельском участковом Анискине, раскрывающем любые преступления. Злоумышленники в черных масках-чулках ограбили сельского кассира. Расследование ведет старший лейтенант Анискин.","98695166":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","98697278":"Случайная встреча круто изменила жизнь Нины. Вместе со своим новым знакомым, Антоном, она отправляется на великую стройку — БАМ. Разумеется, за трудовыми подвигами. Вот только билет на поезд купить забыла!..","98698291":"Фильм посвящен декабрьским наступательным боям 1941 года, проходившим по Волокаламскому направлению в районе Рождественно и Снегирей под командованием генерал-майора А.П.Белобородова.","98700967":"Ленинград, 1925 год. После смерти отца Антонина Старосельская с трудом находит работу. Унылая жизнь - причина для болезней. Моряк торгового флота проявляет заботу о заболевшей Тоне. После женитьбы его арестовывают за контрабанду, и забота о Тоне перекладывается на соседа, который время от времени ее поколачивает. Случайная встреча со строителями жилого…","98705185":"По мотивам романа Виктора Гюго «Отверженные». Французский народ устал от произвола буржуазии и аристократов. Мелкие волнения перерастают в республиканское восстание 1832 года. Парижская коммуна выбирает руководителей, и они сплачивают народные массы для борьбы за свободу и равенство. Вождь революции Анжольрас призывает всех откликнуться на призыв о…","98708033":"1921 год. Гражданская война. «Смотри в оба!» - сказал представитель Ревкома комсомольцу Алеше Команову, давая ему в помощники механика Лыкина: уж очень подозрительным казался этот маленький, бойкий на язык мужичок. К тому же, в округе бродят недобитые красными кавалеристами бандиты, с которыми героям предстоит вступить в смертельную схватку...","98708887":"Историко-революционный фильм Василия Ордынского \"Красная площадь\"","98721732":"В один день родились три мальчика. Проходит время, и отцы начинают подозревать, что их сыновей случайно поменяли в родильном доме. В тайне от жен они начинают свое расследование…","98736881":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","98739563":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","98745240":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","98756325":"Однажды весьма любознательный шестиклассник Миша Андреев потерял интерес к учебе по непонятным причинам. Парень даже смирился, что останется на второй год. Однако случай сводит Мишу с молодыми учеными…","98762229":"Лирическая комедия о человеке, который в канун Нового года разыскивает игру \"Дорожные знаки\" - об этом подарке давно мечтает сын любимой женщины…","98765436":"Печальная история Федора Кузькина, разделившего с родной страной все тяготы тридцатых, а затем и сороковых годов. Теперь Кузькин решает стать единоличником. Но вновь начинаются мытарства крестьянина - и уже без надежды…","98782730":"По совету учителя юный математик Саша Шмагин поехал в Москву, чтобы показать решение интересной и сложной задачи ученым. Однако до профессуры парень не дошел, а попав под временную опеку семьи лейтенанта милиции, вдруг обнаружил, что в его решении — грубая ошибка.","98785891":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","98791186":"Молодой московский физик Белов работает в области атомных испытаний в секретном НИИ. После успешной сдачи проекта, в котором он принимал самое активное участие, на полигоне погибают два солдата. Белова, тяжело переживающего случившееся, посылают на полигон, чтобы разобраться в причине аварии.","98797940":"Историко-революционный Фильм о вооруженном восстании русских солдат, офицеров и финских красногвардейцев в царской крепости \"Свеаборг\" в 1906 году.","98807695":"Городок, куда приезжает на практику студентка педагогического института Дина, парализован страхом. Серия загадочных убийств внешне похожих друг на друга девушек заставляет жителей думать, что в городе орудует настоящий маньяк.","98813299":"Молодые работники клуба готовятся к встрече Нового года. Директор клуба Огурцов, бюрократ и невежа, активно вмешивается в подготовку концерта, требуя убрать из программы все остроумные и талантливые выступления. Организаторы вечера в отчаянии. Но молодость, увлеченность, желание и умение веселиться помогают \"обезвредить\" Огурцова...","98826817":"В первые дни Великой Отечественной Войны батальон советских солдат занимает позицию на одном из участков восточной границы. Более четырех лет герои фильма несут службу на этих рубежах, где нет «состояния войны», но каждую минуту грозит опасность. Японские милитаристы устраивают провокации, диверсии. Немалое мужество, выдержка, собранность потребовались…","98833735":"В жизнь Сережи Баташова, юного барабанщика пионерской организации, приходит беда. Его отца, инженера секретного завода, арестовывают за утерю документов. Виновная в этом мачеха выходит замуж и оставляет Сережу одного.","98838801":"1942 год. Подо Ржевом идут жесточайшие бои, в которых участвует новобранец Сашка. Храбрый, открытый, простой деревенский паренек не сразу находит общий язык с однополчанами, да и вообще не дается ему «наука побеждать». Взяв в плен немецкого солдата и получив приказ его уничтожить, Сашка понимает, что не может стрелять в безоружного...\nПо одноименной…","98840756":"В телевизионной постановке режиссер Карен Шахназаров представит зрителям свой новый взгляд на великий роман.","98851224":"Комедия Николая Досталя и Андрея Тутышкина \"Мы с вами где-то встречались\"","98860841":"Нечистоплотная, подстроенная статья в газете о старой учительнице - принципиальной и негибкой, не ставящей хороших оценок тому, «кому следует». В числе первых - новая молодая учительница, правда, она скорее из сочувствующих, чем из борцов (ничего не поделаешь: дитя своего застойного времени), и отдельные честные, с независимой позицией, ученики.","98864622":"Культовый криминальный боевик эпохи перестройки, снятый режиссером Александром Муратовым по повести Виктора Доценко «Срок для Савелия».","98871871":"Начало сороковых. Герои фильма - обычные советские старшеклассники. Они учатся в советской школе, стараются быть правильными и идейными комсомольцами-активистами. Но не всегда «правильность», внушаемая учителями, совпадает с внутренними убеждениями юных душ - им сложно смириться с тем, что их родные и любимые люди оказываются вдруг «врагами народа».","98880069":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","98889280":"Эгоцентричный пятнадцатилетний подросток Руслан Чутко одержим стремлением очистить город от преступников. Он совсем не чувствует физической боли, и даже сам себе дал прозвище “Плюмбум” (лат. plumbum — свинец). Различными путями, часто шантажом, он втирается в доверие к барменам, фарцовщикам, картёжникам, бомжам, хотя его всё равно в общем не воспринимают…","98899253":"Возникшая любовь бригадира-маляра Анфисы и студента филфака Николая повлекла за собой бурю негодования его родителей. Последовала разлука. А за разлукой - и поиски утраченной любви…","98901942":"Двенадцатилетний Азамат проводит летние каникулы в деревне. После очередной проказы внука дед отправляет его на высокогорное пастбище. Там в кругу пастухов мальчик вначале чувствуют себя не вполне уютно. А сверстники не упускают возможность посмеяться над тем, как Азамат пасет стадо и вычищает загоны. Но вскоре мальчику становится более важным отношение…","98908126":"В тесном кубрике катера, капитаном которого давно ходит Иван Бурлаков и где матросом работает Еленка, вовсе не в шутку называемая им женой, появляется новый работник — помощник капитана Сергей. Внешне энергичный и открытый, он быстро добивается любви Еленки. И также быстро — увольнения Ивана...","98923840":"Лето в пионерском лагере запомнится Мите Лопухину надолго. Каникулы в старинной усадьбе станут для парня переломным этапом — Мите предстоит пройти крещение первой любовью, а вместе с тем познать и горечь, и красоту этого серьезного взрослого чувства.\nУ фильма есть и вторая сюжетная линия. Пионервожатый Сергей (роль исполняет Сергей Шакуров) ставит с…","98940467":"В некотором царстве бояре решили женить старого царя. Выбрал он себе невесту из заморских краев и послал за ней трех дураков — в надежде на то, что не смогут они выполнить его наказа…","98951796":"Приключенческий фильм Николая Досталя \"Дело «Пёстрых»\"","98954233":"Великая Отечественная война... Четверо советских подростков не стали ждать победного ее завершения, а, прослышав о том, что на Соловецких островах открылась школа юнг, отправились туда. Эта школа и стала для ребят настоящей школой взросления, школой жизни...","98972134":"Алька Шанина и Саня Фокин познакомились в самолете. Алька собиралась поступать в театральный институт, а Саня, матрос рыболовецкого сейнера, направлялся через столицу в родную деревню на свадьбу. Из-за непогоды самолет совершил вынужденную посадку. Альке и Сане пришлось провести вместе три дня...","98981906":"Экpанизация одноименной повести Чингиза Айтматова. Фильм о бывшем красноармейце, киргизском учителе Дюйшене. Не обладая большими знаниями, он увлекает за собой учеников, которые любят его за честность, справедливость и готовность помочь каждому.","98998234":"Авторская версия музыкального фильма \"Романс о влюбленных\" в качестве FullHD.","99000437":"Биографическая киноповесть о первом русском исследователе космоса, ученом-изобретателе, ракетостроителе К.Э. Циолковском.","99004476":"Фильм о подвиге русских людей, спасших Архангельск, где строился русский флот, от шведов в конце XVII - начале XVIII века.","99007328":"По мотивам одноименного романа Олега Куваева. Фильм рассказывает о геологах-золотоискателях, их жизни, полной напряжения и риска. Крайний север. Управлением треста \"Северстрой\" принимается решение прикрыть Территорию, где идут поиски уже ненужного олова. Директор Чиннов  предлагает заняться разведкой золотоносного месторождения - это сохранит Территорию.…","99010995":"Андрей Петрович Кочнев, вернувшись с войны, стал инженером-металлургом. Увлеченный работой, он сразу же принял активное участие в управлении заводом — и вскоре стал директором. При монтаже оборудования для реализации своей давней идеи у Кочнева случился инфаркт. Это обстоятельство заставило жену больного вызвать двух женщин, которые много значили в его…","99012886":"Фильм посвящен выдающемуся деятелю русской музыкальной культуры, известному капельмейстеру, основателю первого русского народного хора князю Юрию Николаевичу Голицыну.","99015341":"Десятилетний Самат живёт у бабушки в далёком ауле. Как-то он в горах находит волчонка и приносит его домой, пряча от бабушки. В то же время охотник Асанбек, убивший волчицу и считающий волчонка своей добычей, чтобы сделать чучело, ищет его. Самат, опасаясь, что волчонка обнаружат, относит его в горы, но привыкший к мальчику волчонок не хочет уходить.…","99028270":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","99029022":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","99029262":"Комедийный фильм Константина Юдина \"Девушка с характером\"","99030866":"1990 год. Страна на краю пропасти — разруха, преступность, распад советского строя. Режиссёр Станислав Говорухин снял документальный фильм «Так жить нельзя» — беспощадный портрет советского общества в эпоху перестройки. Эта картина стала одним из самых острых документальных высказываний в истории отечественного кино.","99031475":"Батальоны продолжают держаться. Каждый час — новые потери. Связи нет. Огня нет.\nКапитан Ермаков ведёт людей, зная, что подмоги не будет. Полковник Гуляев,\nвыполнив приказ, не может смотреть в глаза тем, кто остался. Война проверяет каждого — не в штабе, а здесь, на этом берегу.","99032761":"По мотивам романа А.Н.Толстого \"Хождение по мукам\". \nПервый фильм кинотрилогии, посвященной дворянской семье Булавиных. Старшая из сестер Булавиных красавица Катя в растерянности и тоске. С модным поэтом-декадентом Бессоновым она изменяет мужу - петербургскому адвокату-либералу Смоковникову. Ее младшая сестра Даша, приехавшая из Самары, увлечена…","99044595":"Живет в сибирском селе старый Ермолай Воеводин. Четыре сына у него да дочь. Но как по-разному сложились их судьбы. Подался в Москву старший - Игнат, стал выступать в цирке, демонстрируя недюжинную силу. Он доволен своей жизнью и своими рассказами сманивает в город брата Максима. Тот устраивается на стройку чернорабочим, но постоянно чувствует свое…","99052036":"Мультфильм повествует о сказках шамана, который рассказывает о тех временах, когда он был тем самым маленьким мальчиком и дружил с белым медвежонком Умкой. К их веселым приключениям присоединяются новые друзья – милая нерпа Кора, озорная волчица Ильма и смешная розовая чайка Пычик. Сказки шамана пропитаны духом Арктики и ее легендами – добрыми,…","99076677":"Новая серия Простоквашино — Вампиры в Простоквашино на нашем канале.","99077107":"Спасая тонувшего в ледяной воде, солдат Балашов получает воспаление легких, осложнившееся затем тяжелым заболеванием на сердце, и вскоре попадает в военный госпиталь. Молодой доктор Голубев ставит неверный диагноз, в результате чего терапевтическое лечение не дает положительных результатов. Поняв свою ошибку, Голубев предлагает хирургическое…","99085953":"Однажды шестилетний Алешка обрел друга в лице заядлого охотника дяди Вити, пообещавшего мальчугану взять его осенью на охоту. С тех пор Алешка ждал наступления осени и серьезно готовился к охоте. Но дядя Витя не помнил своего обещания. А когда пора охоты наступила и Алешка понял, что его обманули, он поделился своей обидой с родителями — и папа сделал…","99086536":"Новая серия Простоквашино — Новый босс на нашем канале.","99091537":"По одноименному рассказу Л.Пантелеева. О подвиге молодого красноармейца Петра Трофимова, который, выполняя задание, доставляет пакет с донесением в штаб армии Буденного. В пути герой попадает в плен к белогвардейцам...","99092703":"Эксперименты профессора Керома привели к трагической случайности — матрица памяти его погибшей дочери по воле случая попала в океан и наложилась на сознание глубоководной рыбы-манты, не дающей покоя акванавтам.","99100527":"Драма Владимира Каплуновского \"Мексиканец\"","99107547":"Инопланетянка посетила Землю, и в нее влюбился скромный изобретатель Блинков. Его любовь пробудила в ней новые эмоции и чувства. Смирившись с тем, что Блинков не сможет жить в другом мире, она с грустью покидает Землю в одиночестве.","99109070":"Рассказ об учительнице Антонине Васильевне, сумевшей вывезти из осажденного Ленинграда и воспитать нескольких детей - сирот.","99117684":"Май 1945 года. Советские солдаты ведут бои за каждый этаж Рейхстага. Над поверженным Берлином вот-вот взовьётся Знамя Победы. Шесть лет войны, десятки миллионов жизней — и вот она, долгожданная Победа.","99124192":"Нестареющий приключенческий фильм «Гардемарины, вперед!», снятый по роману Нины Соротокиной  «Трое из Навигацкой школы», предлагает вам погрузиться в дымку юношеской романтики вместе с гардемаринами и снова вспомнить, каким он был, век восемнадцатый... В основе сюжета — политические и любовные интриги русского двора времен Екатерины II.  Именно тогда в…","99131283":"Исторический фильм Всеволода Пудовкина и Михаила Доллера \"Суворов\" (1940 г.)\nФильм восстановлен в 1968 г.","99153937":"Легендарная киноэпопея о событиях Великой Отечественной войны, вышедшая на экраны во времена расцвета культа личности Сталина. В исторический контекст вплетена сюжетная линия сталевара Алексея Иванова, ушедшего добровольцем на фронт. Все важнейшие события войны показаны через личное участие в них Алексея: от знаменитого военного парада в ноябре 1941 года…","99153970":"Военная драма Гавриила Егиазарова \"Горячий снег\"","99160808":"Мелодрама \"Высота\" по одноименному роману Е.Воробьева.","99161328":"Полярные летчики Струмилин и сын его фронтового друга Павел спасают ученых со льдины. Не хватает мест, и Струмилин остается на льдине, уступив одному из ученых свое место в кабине. Павел возвращается, но друг отца его не дождался…","99164178":"Мария Александровна — классный руководитель 6-го класса одного из интернатов. Дети любят свою воспитательницу. Поэтому она долго колеблется, прежде чем решается оставить класс и уехать к любимому человеку. Ребята считают ее «предательницей». Некоторые из них готовы на самые отчаянные поступки, чтобы не дать ей уехать.","99169467":"Герои фильма — фантазер и поэт Дениска Кораблев, озорной Мишка, мечтательная Леночка и чрезмерно любопытная Аленка — живут в обыкновенном московском дворе. Они, как и все дети, любят цирк и зоопарк, но не любят манную кашу и домоуправа, который вечно следит за ними и мешает исполнять во дворе всевозможные цирковые номера...","99175736":"Художественный трёхсерийный фильм по одноименному поэтико-драматическому циклу А. С. Пушкина. Исследование души, охваченной страстью, - вот что объединяет «Mаленькие трагедии» А. С. Пушкина и делает интересной каждую новую встречу с ними. В первую серию включены «Сцена из Фауста», «Египетские ночи» и «Моцарт и Сальери». Во второй серии - «Скупой рыцарь»,…","99199629":"В небольшой городок Подмосковья в начале 30-х годов приезжает из деревни Таня Морозова. Смышленая трудолюбивая девушка устраивается домработницей, но ее замечает парторг текстильной фабрики Пронина, по совету которой Таня идет учиться. Трудовые подвиги талантливой труженицы принесет простой деревенской девушке не только профессиональное, но и личное счастье.","99201268":"Учительница Елена Сергеевна совсем не ожидала получить поздравление от учеников в свой День Рождения. Старшеклассники решили зайти к преподавателю, подарить ей букет цветов и подарок. Но сделали они это не из добрых побуждений, а чтобы получить ключ от сейфа, где хранятся контрольные работы.","99201348":"Двухсерийная драма Глеба Панфилова \"Мать\"","99202533":"Новая серия Простоквашино — Последний писк на нашем канале.","99204385":"Фильм посвящен рассказу о героических подвигах одного из храбрых разведчиков Великой Отечественной войны. Отличительная особенность этой киноистории - то, что его главному герою... едва исполнилось двенадцать лет.","99208466":"🐒 Весёлые и неугомонные Мартышкины снова в деле!","99213995":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","99230314":"Экранизация одноименной повести Ф.Гладкова. Драма из жизни крестьянской семьи, приехавшей на рыбные промыслы в Астрахань.","99245596":"В телевизионной постановке режиссер Карен Шахназаров представит зрителям свой новый взгляд на великий роман.","99251966":"Сказка \"Сампо\" по мотивам карело-финского эпоса \"Калевала\". Народ Калевалы мечтает о волшебной мельнице Сампо, которая без зерна дает муку, мед, соль и даже золото. Чтобы заставить мастера Ильмаринена сделать волшебную мельницу для себя, коварная Лоухи похищает его сестру Аннику.","99252717":"В основу этого музыкального фильма положена «Сказка о мертвой царевне и семи богатырях» А.С.Пушкина","99253184":"О юных выпускниках мореходного училища и их первом выходе в море. О трудном жизненном экзамене на профессиональную и человеческую прочность, который пришлось выдержать как команде траулера «Кайра», потерпевшего бедствие во время шторма, так и коллективу спасателя «Посейдон» под командованием капитана Чигринова, где проходил свою службу герой фильма…","99253786":"Герой фильма - обычный водитель московского такси, добрый и порядочный человек. Каждый новый рабочий день сулит ему новые встречи, знакомства - иногда радостные и приятные, а порой и требующие от него суровой решительности и отваги.","99259236":"Фильм построен как воспоминания рядового матроса, который пошел сложные события Октябрьской революции, тягот восстановления хозяйства после гражданской войны, обороны страны от фашистов во время Великой Отечественной войны. Главному герою пришлось побывать в составе охраны В.И.Ленина и оказаться свидетелем сложного процесса электрификации страны,…","99263022":"Действие картины происходит в Древней Руси - в те времена, когда славянам, объединившимся в войско под предводительством Ратибора, сына Всеслава, удалось одержать первые победы над племенами кочевников.","99271687":"С виду герой фильма совершенно нормальный человек. Однако большинство земляков считают его слегка чокнутым. Еще бы: конструирует вечный двигатель, годами сочиняет философский трактат… Словом, витает в эмпиреях и глядит свысока на прочих обитателей грешной земли. Глядит-глядит - а счастья-то своего не видит…","99276077":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","99301199":"Летчик-испытатель Астахов, герой Советского Союза, во время войны попадает в плен. После войны вернувшегося Астахова исключают из партии, увольняют с работы и лишают правительственной награды. Долгие годы герой не имеет возможности вернуться к своей профессии. Астахов спивается, но любовь Саши и вера в себя спасают его и возвращают надежду на…","99306768":"Восстановление кинокартины выполнено специалистами подразделения \"Телекино и Компьютерная графика\" киноконцерна \"Мосфильм\".","99316863":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","99317616":"Вот уже много лет город, в который попадает странствующий рыцарь Ланцелот, находится под властью Дракона. Долг рыцаря — сразиться с жестоким узурпатором. Но Бургомистр отговаривает его от поединка, объясняя, что люди не могут жить без диктатора. И это правда: после победы Ланцелота жители города, не дождавшись от нового властелина строгих указов,…","99345264":"Вторая серия кинокартины \"Братья Карамазовы\"","99347289":"Жила-была хорошая добрая девушка Настенька. Злая мачеха заставляла ее работать, не давая продыху. Однажды она решила избавиться от падчерицы и отправила ту замерзать в зимний лес. В этих же краях жил паренек Иван. Он полюбил Настеньку, да вот только был он большим хвастуном, потому лесной колдун и превратил его в медведя.","99349005":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","99355841":"Мозаика из взглядов случайных прохожих, сложенная Кареном Шахназаровым.","99365262":"Жена старшего лейтенанта Астахова, потомственного пограничника, не сразу понимает, каким серьезным делом занят ее муж. Каждый день на заставе что-то происходит: сначала границу перешла женщина с ребенком, затем — некий Спиридон Долидзе, считавшийся погибшим еще в 1942 году. А теперь под покровом ночи на черном дельтаплане через границу перелетает шпион...","99367520":"Молодой филолог Николай работает в архиве своего учителя, и ему удается расшифровать бесценный пушкинский автограф. Первооткрыватель, вдохновленный успехом, забывает обо всем на свете. И случается невероятное: при загадочных обстоятельствах архив исчезает, и подозрение падает на Николая.","99378695":"Историко-биографический фильм о великом русском флотоводце Федоре Федоровиче Ушакове. События историко-биографического фильма происходят в 1785-1791 годы во время войны с Турцией. Князь Потемкин, фаворит Екатерины II, доверяет молодому Ушакову строительство кораблей. Черноморский флот создается в кратчайшие сроки, несмотря на эпидемию чумы и пожары, а…","99379180":"По мотивам повести Валентина Распутина «Прощание с Матёрой». Сибирская деревня Матёра веками стояла на острове, окруженном водами реки Ангара. В связи со строительством ГЭС остров должен быть затоплен. Всех жителей деревни переселяют в новый поселок городского типа. Для старшего поколения расставание с Матерой трагично. Откладывая отъезд со дня на день,…","99380504":"Оленёнок Бемби, став взрослым прекрасным оленем, встречает олениху Фалину. Юная пара отправляется в далёкое путешествие на поиски цветка жизни.","99381851":"Нестареющий приключенческий фильм «Гардемарины, вперед!», снятый по роману Нины Соротокиной  «Трое из Навигацкой школы», предлагает вам погрузиться в дымку юношеской романтики вместе с гардемаринами и снова вспомнить, каким он был, век восемнадцатый... В основе сюжета — политические и любовные интриги русского двора времен Екатерины II.  Именно тогда в…","99389871":"Новая серия Простоквашино — Хейтер на нашем канале.","99392576":"Второй историко-биографический фильм кинодилогии Михаила Ромма, посвящённой адмиралу Ушакову. Фильм рассказывает о победах российского флота на Средиземном море. Франция начинает захватнические войны. Эскадра Ушакова в ходе Средиземноморского похода (1798—1800 гг.) совместно с войсками Суворова освобождает Италию от войск Наполеона.","99392903":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","99397258":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","99398490":"🌨️ Зима — это не только холод, но и повод для открытий!","99412826":"По повести Э.Казакевича \"Двое в степи\" и военным дневникам К.Симонова. 1942 год. Военный трибунал расследует действия арестованного молодого неопытного лейтенанта Огаркова. Офицер Иван Синяев, выполнявший вместе с Огарковым боевое задание, считает, что тот проявил трусость. Решением суда Огарков приговаривается к расстрелу. К нему приставляется молодой…","99419091":"В приморском городке в разгар сезона жуткий ажиотаж: пляжи переполнены, каждый клочок земли занят палатками и машинами туристов. Да еще и киношники решили снимать здесь свой «шедевр», поставив на берегу бутафорский корабль.","99424270":"Комедия Татьяны Лукашевич \"Свадьба с приданым \"","99426636":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","99427007":"Советский приключенческий фильм про шпионов режиссёра Дмитрия Васильева, снятый в 1958 году по одноимённой книге Александра Авдеенко.","99433422":"Провинциальный городок 1920-х, где власть меняется как декорации, — и один мечтатель, который верит в силу искусства сильнее, чем в силу оружия. Удастся ли ему зажечь свою звезду?","99435283":"Действие фильма происходит в середине 18 века - во времена семилетней англо-французской войны за колониальное господство в Северной Америке. Юная Мэйбл Дунгам держит путь в английский форт. Навстречу дочери сержант Дунгам посылает юного офицера Джаспера и охотника Следопыта...","99435869":"Фильм Ивана Пырьева \"Кубанские казаки\" (1949 г.)\nФильм восстановлен в 1968 г.  Реставрация в 2020 г.","99440569":"Начало 1930х годов. Дальний Восток. В центре фильма – борьба сибиряков против диверсантов-самураев, пытающихся сорвать строительство форпоста обороны у восточных границ СССР – города Аэрограда.","99441708":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","99442807":"Некто Пирошников случайно сталкивается на улице Ленинграда с молодой женщиной Алей. Он делится с ней тем, что его мучает - ощущением собственной бесполезности, ненужности, бессмысленности жизни. Ему даже некуда идти! Аля сочувствует новому знакомому и отводит его туда, где живет сама. Так Пирошников оказывается в доме, из которого невозможно выбраться -…","99445708":"В лесной избушке остались на ночлег Студент, Аптекарь, двое подмастерьев, Графиня с тетушкой. Внезапно появившиеся разбойники потребовали выдать им Графиню.","99457383":"После гибели мужа Тамара отдала дочь Олю в детский дом и уехала на север, где создала новую семью. Когда Тамаре потребовалась нянька (от второго брака у нее три мальчика), она забрала подросшую Ольгу из детского дома. Но отношения у них не сложились...","99469920":"Муж героини трагически погиб в море — и теперь ее жизнь постепенно превращается в бесконечную цепь унижений. Неустроенность, невозможность защитить себя и свою дочь от повседневного грубого обмана приводят к тому, что одинокая женщина становится портовой шлюхой...","99471370":"Новая серия Простоквашино — Радио Дядя на нашем канале.","99481722":"Злодей Шито-Крыто задумал превратить всех детей в лентяев, двоечников и проходимцев, чтобы с их помощью завоевать весь мир. Но лоботрясы и озорники вовремя спохватились — и операция под кодовым названием «Братцы-тунеядцы» с треском провалилась.","99487101":"Старый рабочий Колючкин с выходом на пенсию загрустил. Чтобы жить стало повеселее, его сосед Пушков — бывший актер — старается приобщить друга к рыбалке. Каждое утро отправляются старички на речку, но дойти до нее им никак не удается — все время кто-нибудь отвлекает своими просьбами, а друзья и рады помочь... История о том, что время на пенсии тоже можно…","99488201":"Новая серия Простоквашино — Золотая карта на нашем канале.","99495981":"Иннокентий Сосновский, новый тренер по гимнастике, приехавший в сибирский городок, чтобы преподавать мальчишкам акробатику. Он знает, что не все из них станут чемпионами. Даже не все будут успешными спортсменами. Но главное — все они будут хорошими людьми. Потому что когда человека любят — он не станет плохим. Тренер идет на риск: ради того, чтобы его…","99496900":"Удивительные открытия и большие чудеса ждут героев в этих сериях ✨","99497731":"События происходят в конце XIX века на Диком Западе, в Америке. В основе сюжета — сложные перипетии жизни работяги — старателя Габриэля Конроя. Найдя нефть на своем участке, он познает и счастье, и разочарование, и опасность, и отчаяние…","99498567":"Новая серия Простоквашино — Рыбалка на нашем канале.","99503104":"1820-е годы. Сын плотника Жюльен Сорель боготворит Наполеона и мечтает о славе. Благодаря способностям и образованию он оказывается в среде сначала провинциального, а затем и высшего дворянства, но жизнь сложилась не так, как ему хотелось бы.","99508382":"Герой фильма школьник Петя Копейкин доказывает, что такие понятия как храбрость, благородство и честь присущи не только временам плаща и шпаги, но и сегодняшнему дню. Выбрав примером для подражания героя известной пьесы Эдмона Ростана, он в своих поступках старается походить на Сирано де Бержерака.","99509970":"Герой фильма Дима Манохин мечтает стать клоуном. Однажды он отправляется в санаторий, чтобы развлечь заболевшую одноклассницу.","99517926":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","99519159":"Осень 1944 года. Советские войска вышли к границам Германии. Впереди — решающие сражения, которые должны окончательно сломить нацистскую военную машину. Ставка планирует удар невиданной мощи.","99519823":"Много лет великий эмир Бухары не знает счастья – он утратил волшебный вкус халвы, и теперь жизнь для него кислая, как лимон. А в доме бедного гончара Шир-Мамеда – счастье: у него чудесным образом появился маленький сынок, и звать его – Ходжа Насреддин. И кто бы знал, на что способен этот юный плут и остряк?! Уже вся Бухара наслышана о проделках…","99526260":"Эксцентрическая комедия по мотивам пьесы М.Булгакова «Иван Васильевич» о машине времени, сооруженной московским инженером Шуриком Тимофеевым, с помощью которой Иван Грозный попадает в ХХ век, а управдом Бунша, как две капли воды похожий на царя, – в Древнюю Русь.","99540556":"Новая серия Простоквашино — Древесный мститель на нашем канале.","99541035":"Приключенческий фильм Константина Юдина \"Застава в горах\".","99546116":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","99557501":"Какие они, минуты счастья? Конечно, разные. Но есть среди них и такие: сидит в такси женщина и поёт. Вернее, старательно, не очень умело выводит пронзительную мелодию: «… Опустела без тебя земля, как мне несколько часов прожить».","99570008":"Кинокомедия Константина Юдина \"На подмостках сцены\"","99573136":"Когда ты встаешь утром и не видишь своего отражения, когда главный преступный авторитет города дрожит от страха и отвечает выстрелом на звонок в дверь, когда кровь пьётся, как томатный сок... знай - в городе появился упырь. Тогда пули ничего не решают, и в дело идёт осиновый кол.","99574419":"Моряки подобрали медвежонка и назвали его Егоркой. Спасенный и обласканный людьми звереныш дарит им доверие и любовь. После многих забавных приключений его отпускают на свободу.","99577786":"Пятиклассника Борю, непоседу и выдумщика, назначили вожатым в первый класс. Не восприняв это вначале серьезно, мальчик постепенно проникся интересом к новым и неожиданным для него обязанностям.","99578774":"Тридцатилетний спортсмен-десятиборец покидает большой спорт и становится каскадером в кино. О том как снимается кино, и о развитии личных взаимоотношений между главными героями.","99581781":"Кинокомедия по одноименному роману И.Ильфа и Е.Петрова. Умирая, теща бывшего светского льва и предводителя дворянства, а ныне скромного делопроизводителя уездного ЗАГСа Ипполита Воробьянинова, открыла ему свою тайну: она спрятала фамильные драгоценности в одном из стульев гостиного гарнитура. Бриллиантовый угар вскружил голову Воробьянинова, и он ринулся…","99582472":"Новая серия Простоквашино — Когда маме не поется на нашем канале.","99591769":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","99599155":"Фильм повествует о нелегкой судьбе одной из западных областей послевоенной Украины. Линия противоборства успешного писателя и поэта, пропагандиста Советской Украины и борца с «поджигателями войны» и организованной преступной группировки, действующей в интересах западных стран, пытающихся всячески навредить молодой советской республике.","99603743":"Герой фильма сержант Карпенко получает в свое распоряжение отряд новобранцев. Ему предстоит научить ребят азам солдатской науки, преодолев их недоверчивость, ироничность и нежелание подчиняться воинской дисциплине…","99607483":"Напряженная драма о стремлении к жизни. Весна 1942 года. Маленький пароход с ранеными, отплывающий в Архангельск, попадает под обстрел немецкого самолета. В живых остается только один солдат, за которым начинается изнурительная погоня. Фашистский ас нервничает: ему, профессионалу в своем деле, никак не удается «достать» последнего оставшегося в живых…","99610541":"В прошлом Филимонов был талантливым, подающим надежды музыкантом. Настоящее же прозаично – он зять «большого человека», и только. Однажды у Филимонова прихватило сердце – и это в неполные сорок лет! Этот неприятный случай послужил поводом для знакомства с прекрасной медсестрой Лидой. И закрутился бурный роман... Но найти в себе смелость и силу круто…","99610996":"Продолжение фильма \"Ленин в Октябре\". 1918 год, гражданская война, в стране разруха, голод. В Москве раскрывают контрреволюционный заговор против Ленина, вдохновляемый иностранными дипломатами. Во время ареста организаторам покушения удается уйти, и Фанни Каплан стреляет в Ленина после митинга на заводе Михельсона. Однако Ленин выздоравливает и, несмотря…","99616812":"Германия, канун окончания Второй мировой войны. Советский разведчик полковник Исаев, он же - штандартенфюрер СС Штирлиц, исполняет последние задания Центра, диктуемые ходом военных действий и политическими интригами верхов противоборствующих сторон.","99622606":"Двухсерийная драма Глеба Панфилова \"Мать\"","99627242":"В самой тихой деревне района ЧП - у завхоза клуба украли аккордеон. Улик преступники не оставили, свидетелей тоже. И заподозрить в воровстве некого - в деревне все свои. Завхоз махнул рукой и уже надумал новый аккордеон покупать. Но детектив Анискин всерьез собрался распутать это тёмное дело...","99627733":"По одноименному роману А.Серафимовича. Время действия — последние дни гражданской войны. В основе сюжета - победный путь Таманской армии через районы, занятыми белыми.","99638051":"Комедийный фильм Михаила Жарова \"Беспокойное хозяйство\"","99642762":"По одноименной пьесе Г.Мдивани. 1941 год. После окончания летной школы лейтенант Илья Стрельцов получает назначение в полк истребителей, охраняющих небо Москвы. В первом же воздушном бою он сбивает фашистский самолет. С тех пор боевые товарищи называют его Счастливчиком. В полку Илья неожиданно встречает медсестру Зою, которую знает еще по детским играм...","99648334":"1942 год. Вся центральная Европа под пятой немцев. Член подпольной антифашистской организации Харро Шульце-Бойзен узнает о секретной военной операции \"Блау\", даюшей возможность немцам захватить Кавказ. Шульце-Бойзен сообщает обо всем в Москву, но Сталин посчитал это дезинформацией. План немцев - создать имитацию наступления под Москвой, чтоб удержать там…","99652895":"Сатирическая комедия Карена Шахназарова 1979 года по одноимённой пьесе Леонида Зорина о том, как творчески несостоятельная личность движется по служебной лестнице все выше и выше. Гордей Кабачков, профессиональный аферист, решил сделать карьеру в науке и весьма преуспел. Дело происходит не где-нибудь, а в Институте античной культуры. Он легко обводит…","99662893":"Май 1945 года. В предместьях Праги простые люди встречают советских солдат-освободителей со слезами радости на глазах. В первые дни затишья кто-то с грустью вспоминает о довоенной жизни; кто-то нежданно встречает свою любовь; кто-то возвращается из вражеских застенков, с надеждой смотря в будущее; а кто-то, пересев из танка в чешский трамвайчик, с…","99672088":"1942 год. Вся центральная Европа под пятой немцев. Член подпольной антифашистской организации Харро Шульце-Бойзен узнает о секретной военной операции \"Блау\", даюшей возможность немцам захватить Кавказ. Шульце-Бойзен сообщает обо всем в Москву, но Сталин посчитал это дезинформацией. План немцев - создать имитацию наступления под Москвой, чтоб удержать там…","99678304":"Новая серия Простоквашино — Шар для Шарика на нашем канале.","99679823":"Комедия Константина Юдина \"Сердца четырех\"","99682263":"Миллионер Филипп Стоун, располагающий секретной информацией о ядерной политике США, убежден, что она несёт реальную опасность людям планеты. Веря в созидательную миссию искусства, он решает заказать драматургу Майклу Трентону пьесу на тему об угрозе ядерной войны. Для того чтобы написать пьесу Трентон вынужден встретиться с правительственными…","99691697":"Рассказ о начале жизни. Потеряв рано родителей, Алеша и Надя не остались одни - друг отца и окружающие их люди помогли детям остаться добрыми и открытыми в этом непростом мире взрослых…","99692055":"Экранизация одноименной главы романа М.Ю.Лермонтова «Герой нашего времени». Печорин, узнав об увлечении своего приятеля Грушницкого княжной Мери Лиговской, от скуки и желания досадить насквозь фальшивому юнкеру, влюбляет в себя девушку.","99693540":"Три новеллы по О. Генри — и каждая бьёт точно в цель: смешно, остро и абсолютно неожиданно.","99697217":"По мотивам одноименного романа С.Павлова. Научно-фантастический фильм о проблемах, с которыми может столкнуться человечество, осваивая просторы Вселенной. В разных районах Земли зарегистрированы \"черные следы\" и именно в тех же местах - необъяснимые атмосферные аномалии и магнитные бури. Специально созданной оперативной группе удалось обнаружить связь…","99704614":"В одной из московских школ учились три друга: трус и отличник Гарик, озорник Серега и правдолюбец Мишка. Восьмой «Г», где учились герои, учителя называли восьмым «О», что значит «орда». Но в класс пришел новый классный руководитель Геннадий Николаевич Козлов и ребятам жить стало интересней...","99709983":"«Карусель» - комедия Михаила Швейцера 1970 года. Фильм снят по ранним рассказам, очеркам и зарисовкам Антона Павловича Чехова: «Тоска», «Размазня», «Благородный», «Циник», «О вреде табака», «Поленька», «Роман с контрабасом». \n Вы узнаете, как надо благодарить пожилого мужа молодой красавицы за данные в долг деньги, познакомитесь с историей «несчастного»…","99718662":"Социальная мелодрама по мотивам романа Петра Проскурина «Судьба». Трогательная и печальная история любви женатого председателя колхоза Захара Дерюгина к молодой женщине Мане Поливановой.  В фильме показана жизнь советской деревни 1930-х годов.","99732062":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","99738334":"Рабочий кожевенного завода Нахум Бейчик изобретает машину, облегчающую тяжелый труд по выделке кожи. Частный предприниматель, бывший кулак Лопатин, хочет купить машину и использовать ее в корыстных интересах. Встретив со стороны Бейчика решительный отказ, Лопатин разжигает антисемитские настроения определенной части рабочих и с помощью своих…","99739092":"Следователь Муромцев, расследуя должностное преступление участкового милиционера, выходит на дельцов теневой экономики. Параллельно с основным действием развивается средневековый сюжет с врачом-алхимиком, портрет которого висит в комнате одного из героев современной истории.","99740086":"Драма Михаила Калатозова \"Неотправленное письмо\"","99740492":"Новая серия Простоквашино — Кикота улинарная битвыр на нашем канале.","99740996":"Телевизионщики приезжают в рыболовецкий район снимать репортаж о рыбаках и о передовом хозяйстве председателя Калача. По дороге их перехватывает Сенька Лапин с друзьями. Их цель — показать красоту дивного озера Байкал и чудовищные условия труда и жизни рыбаков...","99741473":"Женский взгляд на поколение тридцатилетних мужчин, на долю которых выпали и Афган, и «криминальная революция», и нарковолна, и СПИД…","99744252":"По мотивам произведения В.Ардаматского \"Сатурн\" почти не виден\". Фильм является продолжением кинокартины \"Путь в \"Сатурн\" и рассказывает о продолжении успешной, полной опасностей работы нашего разведчика. Время действия - с 1942 по 1944 годы. Советский разведчик Крылов работает в немецкой шпионской школе \"Сатурн\" на оккупированной территории в Белоруссии…","99747933":"Новая серия Простоквашино — Мотопочтальон на нашем канале.","99749356":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","99753210":"Фильм-сказка о былинном русском богатыре Василии Буслаеве – сыне Новгородского посадника. Жил он как хотел, сам по себе: не верил ни в сон, ни в чех, ни в змеиный шип, ни в вороний грай. Сила и мощь Василия, сына Новгородского посадника (губернатора), водившего дружбу с простым народом, приводила в бешенство и нагоняла страх на разжиревших купцов…","99754588":"Боевик Александра Аравина \"Решение об ликвидации\"","99755178":"Самые известные принцессы — Бременская, Забава, Золушка и Дюймовочка — собрались в девичий бэнд, чтобы заявить о себе в музыкальном конкурсе «Сказочный голос». На сцене — все легенды Тридевятого царства! Но самая коварная соперница — известная певица Шамаханская царица. Из-за нее под угрозой окажется не только музыкальная карьера принцесс, но и их дружба…","99756961":"Комедия Григория Александрова \"Веселые ребята\"","99757082":"«Свой парень» - прозвище восемнадцатилетней ткачихи Тони, беспокойной и активной комсомолки, названной в районной газете «человеком будущего». Скромная героиня не соглашается с таким определением своей личности - и спешит в редакцию дать опровержение…","99758307":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","99760162":"⭐ Коротко о сериале \"Оранжевая корова\"\nГлавные персонажи – семья Оранжевой Коровы: дети Бо и Зо и их родители Мама Корова и Папа Бык.\nТелята Бо и Зо и их друг поросенок Коля - большие любители приключений, которых в их жизни очень много. Они попадают в смешные, трогательные, таинственные ситуации, которые всегда заканчиваются хорошо. Почему? Потому что…","99763163":"⭐ Коротко о «Зебра в клеточку» ‒ музыкальный мультфильм про единство непохожих и про то, как оставаться самим собой.\nВ каждой серии веселая компания таких разных, не похожих друг на друга маленьких жителей джунглей будет постигать мир, выдумывать игры и попадать в непривычные ситуации.","99765278":"Медовая долина – городок на берегу моря, в котором живут самые разные животные: кулинарный гений ежиха Мари, провинциальная модница белка Люси, меланхоличный и добрый медвежонок Фил и другие. У жителей Медовой долины хорошие добрососедские отношения, почти все в городе знают друг друга, часто проводят время вместе и обращаются друг к другу за помощью.\nНо…","99770578":"По мотивам сатирической комедии Н.В.Гоголя \"Ревизор\". Действие происходит в середине XIX века. Городничий уездного города получает секретное сообщение о прибытии ревизора из Петербурга. Проверяющий приедет инкогнито. Это известие, а также новость о поселившемся в гостинице подозрительном молодом человеке заставляют всех чиновников города чувствовать себя…","99775855":"У отца, капитана торгового флота, было три сына : Кирилл - художник, Юрий - моряк, Герка - музыкант. Казалось бы, ничто не может помешать их дружбе. Но старший и средний братья влюблены в одну девушку - Светлану. Соперничество делает их врагами. Юрий не может простить измены, и между братьями происходит крупная ссора. Неожиданно на семью обрушивается…","99778334":"🩷 Добро пожаловать в Лудлвилль — город, где каждый день превращается в приключение!","99781170":"Фильм-сказка Александра Птушко \"Каменный цветок\" (1946 г.)\nФильм восстановлен в 1964 г.","99785562":"Новая серия Простоквашино — Геймер на нашем канале.","99788305":"Великая Отечественная война. Завод в Альпах, где работают военнопленные, подвергается ночным бомбардировкам. Воспользовавшись этим обстоятельством пятеро заключенных осуществляют побег. Среди них русский солдат. Только ему и удается уйти в горы. В горах Иван встречает итальянскую девушку Джулию, также бежавшую из плена.","99791754":"Фома Гордеев - сын богатого волжского купца - не хочет быть продолжателем его дела. Уму претит грязь и несправедливость окружающей жизни. Фома ищет утешение в пьяном разгуле и диких выходках.","99795925":"Конец 70-х годов. Поздняя осень на южном берегу Крыма. Холодное море. И скука, скука… В одном из пансионатов собралась интересная публика, вынужденная придумывать себе развлечения. В этой обстановке бесконечных разговоров о здоровье и его отсутствии, пересказов бытовых драм и обязательного курортного флирта зарождается любовь двух немолодых людей...","99801009":"Биографический фильм об Иване Мичурине (1948 г.)\nФильм восстановлен в 1976 г.","99823009":"Комедия Олдржиха Липского \"Соло для слона с оркестром\" 1-я серия","99829762":"Симпатичные Енотки живут в большой музыкальной шкатулке —  Они весёлые, любопытные и очень любят песенки, с ними маленький зритель сможет узнать много нового о мире, а заодно развивать свою фантазию и интерес к музыке —","99835388":"Летчику-испытателю Алексею Колчину было поручено первому поднять в воздух реактивный самолет и указать конструкторам на его недостатки. Первые испытания прошли успешно. Но во время работы над усовершенствованием машины двигатель взорвался и Колчин погиб. И теперь Сергей Шаров, внимательно изучив рекомендации друга, записанные на магнитофонную пленку,…","99839526":"Экранизция рок-оперы Алексея Рыбникова по мотивам пьесы в стихах Павла Грушко. Вместе с другими жителями нищей чилийской деревушки Хоакин Мурьета решает отправиться в далекую Калифорнию на поиски золота. В пути он встречает прекрасную девушку, которая становится его женой. Но счастье влюбленных оказывается недолгим.","99844713":"В южный российский город, осажденный деникинцами, спешит чекист Заврагин, чтобы предотвратить белогвардейский мятеж. Белые блокируют железнодорожную ветку, но Заврагин решает продолжать путь на тачанках. Среди его спутников: доктор Шелако, медсестра Катя и скрывающийся под личиной ветеринара Беклимишев — белый офицер, возглавивший мятеж...","99845898":"У десятилетнего Алика были две заветные мечты. Во-первых, он хотел завести щенка. А еще - сняться в кино в роли юного партизана. Но, получив приглашение на съемку, мальчик чуть было не «испортил песню», исправив полученную за диктант «двойку» на «пятерку» - обман раскрылся, и юный обманщик едва не лишился роли...","99848751":"По мотивам pанних pассказов А.П.Чехова. История репетиций необычного хора переплетается с жизнью веселых героев, в основе которой - сюжетные линии рассказов \"В бане\", \"Невидимые миру слезы\", \"Разговор человека с собакой\" и др.","99851278":"«Монсики» это развивающий анимационный сериал о приключениях необычны существ - Монсиков, живущих в Монсиленде, покрытой водой маленькой планета с десятью островами. Три из них пригодны для жилья, а на остальные лучше не попадать...\nОстрова Монсиленда представляют собой воплощения настроений. Здесь есть море Любви, Зловулкан, поляна Грусти, облака…","99864662":"В Кишинев на смотр художественной самодеятельности приезжают многочисленные конкурсанты, среди которых - ударница, комсомолка и просто красавица Ляна, ее друзья и подруги…","99877873":"История о том, как рабочие из Болгарии и СССР встретились на возведении газопpовода \"Дpужба\" и о том, как они боролись за спасение 30 гектаров земли и победили.","99890557":"Мелодрама Василия Ордынского \"Сверстницы\"","99893661":"На Пригорской ювелирной фабрике обнаружены крупные хищения. В Москве совершены два убийства и попытка изнасилования. Казалось бы, что общего между этими преступлениями? Но однажды взаимосвязь проявится, и Костенко срочно вылетит в Сухуми…"}/*ENDRTDESC*/;
if (typeof MOVIES !== 'undefined') for (var _j = 0; _j < MOVIES.length; _j++) { var _t = RUTUBE_DESC[MOVIES[_j].id]; if (_t) MOVIES[_j].desc = { uz: _t }; }
